INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "树身上长出来的小片片。", "primary_collocate": null, "pronunciation": "shù yè", "ipa": "ʂu˥˩ je˥˩", "syllable_count": 2, "sentences": [{"text": "夏天，树叶又绿又大。", "target_word": "树叶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "树叶上有一只小虫子。", "target_word": "树叶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把一片树叶夹在书里。", "target_word": "树叶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天的树叶有红的，有黄的。", "target_word": "树叶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树叶掉进了河里，慢慢往前漂。", "target_word": "树叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用树叶做了一只小船。", "target_word": "树叶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大树的树叶很多，夏天可以在下面休息。", "target_word": "树叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天树上没有树叶了。", "target_word": "树叶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗在树叶堆里玩得很高兴。", "target_word": "树叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，树叶一直在响。", "target_word": "树叶", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "樹葉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "树上长出来的小片叶子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1bd4ef5-97b2-41c8-b5f8-10c80ead5322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21172, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "树叶", "is_correct": true, "explanation": "正确。树叶指树身上长出来的小片叶子。"}, {"text": "书业", "is_correct": false, "explanation": "shū yè（第一声）与 shù yè 声调不同，书业指图书出版行业。"}, {"text": "暑夜", "is_correct": false, "explanation": "shǔ yè（第三声）与 shù yè 只差声调，暑夜指夏天的夜晚。"}, {"text": "事业", "is_correct": false, "explanation": "shì yè 与 shù yè 只差韵母（i 与 u），事业指所从事的工作或事情。"}, {"text": "数月", "is_correct": false, "explanation": "shù yuè 与 shù yè 韵母不同（yuè 与 yè），意思是几个月。"}], "explanations": {"树叶": "正确。树叶指树身上长出来的小片叶子。", "书业": "shū yè（第一声）与 shù yè 声调不同，书业指图书出版行业。", "暑夜": "shǔ yè（第三声）与 shù yè 只差声调，暑夜指夏天的夜晚。", "事业": "shì yè 与 shù yè 只差韵母（i 与 u），事业指所从事的工作或事情。", "数月": "shù yuè 与 shù yè 韵母不同（yuè 与 yè），意思是几个月。"}, "sentence_index": null, "correct_answer": "树叶"}, "level_3": {"options": [{"text": "树叶", "is_correct": true, "explanation": "正确。夏天树叶又绿又大，符合树叶的外观。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块不是绿色的，也不会长得又绿又大，与“绿”矛盾。"}, {"text": "雪花", "is_correct": false, "explanation": "语义：雪花是白色的，“绿”不符合雪花的外观。"}, {"text": "皮鞋", "is_correct": false, "explanation": "搭配：“又绿又大”多用于形容植物或叶子，不说皮鞋又绿又大。"}], "explanations": {"树叶": "正确。夏天树叶又绿又大，符合树叶的外观。", "冰块": "语义：冰块不是绿色的，也不会长得又绿又大，与“绿”矛盾。", "雪花": "语义：雪花是白色的，“绿”不符合雪花的外观。", "皮鞋": "搭配：“又绿又大”多用于形容植物或叶子，不说皮鞋又绿又大。"}, "sentence_index": 0, "correct_answer": "树叶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在路上捡到一只树叶。", "explanation": "这里应该用〈片〉。树叶是薄片，用“片”计量，“只”用于动物或成对的东西。"}, {"text": "农民把刚买的树叶种在院子里。", "explanation": "这里应该用〈树苗〉。种下去的是树苗，树叶不能种。"}, {"text": "爸爸用树叶做了一张结实的桌子。", "explanation": "这里应该用〈木头〉。做桌子用木头，树叶又薄又软，不能做桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967dff1b-b05c-477d-a642-65fecbdc50c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21172, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "树叶", "is_correct": true, "explanation": "正确。树叶指树身上长出来的小片叶子。"}, {"text": "输液", "is_correct": false, "explanation": "shū yè（第一声）与 shù yè 只差声调，输液指往血管里输入药液。"}, {"text": "书页", "is_correct": false, "explanation": "shū yè（第一声）与 shù yè 声调不同，书页指书的页面。"}, {"text": "暑夜", "is_correct": false, "explanation": "shǔ yè（第三声）与 shù yè 只差声调，暑夜指夏天的夜晚。"}, {"text": "主页", "is_correct": false, "explanation": "zhǔ yè 与 shù yè 声母和声调不同，主页指网站的首页。"}], "explanations": {"树叶": "正确。树叶指树身上长出来的小片叶子。", "输液": "shū yè（第一声）与 shù yè 只差声调，输液指往血管里输入药液。", "书页": "shū yè（第一声）与 shù yè 声调不同，书页指书的页面。", "暑夜": "shǔ yè（第三声）与 shù yè 只差声调，暑夜指夏天的夜晚。", "主页": "zhǔ yè 与 shù yè 声母和声调不同，主页指网站的首页。"}, "sentence_index": null, "correct_answer": "树叶"}, "level_3": {"options": [{"text": "树叶", "is_correct": true, "explanation": "正确。“大树的树叶很多”，树叶长在大树上，夏天可以在下面休息。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会长在大树上，与“大树的……很多”不符。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“大树的玻璃”不通，玻璃不是大树的组成部分。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔不是大树的部分，也不能为人遮阴休息。"}], "explanations": {"树叶": "正确。“大树的树叶很多”，树叶长在大树上，夏天可以在下面休息。", "石头": "语义：石头不会长在大树上，与“大树的……很多”不符。", "玻璃": "搭配：“大树的玻璃”不通，玻璃不是大树的组成部分。", "钢笔": "语义：钢笔不是大树的部分，也不能为人遮阴休息。"}, "sentence_index": 6, "correct_answer": "树叶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那棵大树的树叶很粗，两个人才抱得住。", "explanation": "这里应该用〈树干〉。形容粗细、两人才抱得住的是树干，树叶是薄片。"}, {"text": "他把那棵枯树的树叶刨了出来。", "explanation": "这里应该用〈树根〉。刨出来的是埋在土里的根，树叶长在枝上，不能刨。"}, {"text": "他用小刀把树叶一块块削下来。", "explanation": "这里应该用〈树皮〉。能一块块削下来的是树皮，树叶不能这样削。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967dff1b-b05c-477d-a642-65fecbdc50c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只树叶落在我的书上。", "corrected_sentence": "一片树叶落在我的书上。", "error_description": "量词错误：“树叶”应用量词“片”，写成“一只树叶”是错的，应为“一片树叶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967dff1b-b05c-477d-a642-65fecbdc50c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大风吹过，树叶一片片飞起了来。", "corrected_sentence": "大风吹过，树叶一片片飞起来了。", "error_description": "了的位置错误：“飞起来”中“来”是趋向补语，“了”应放在“来”后面，应为“飞起来了”，不能说“飞起了来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967dff1b-b05c-477d-a642-65fecbdc50c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
