INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21174, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "害虫是伤害庄稼、树木或让人生病的虫子。", "primary_collocate": null, "pronunciation": "hài chóng", "ipa": "xaɪ˥˩ ʈʂʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "蝗虫是吃庄稼的害虫。", "target_word": "害虫", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "树叶上有很多害虫。", "target_word": "害虫", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "蚊子和苍蝇都是害虫。", "target_word": "害虫", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "菜地里的害虫把叶子吃光了。", "target_word": "害虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在果树上喷药，杀死害虫。", "target_word": "害虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "害虫太多，今年的白菜长得不好。", "target_word": "害虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蚊子是会让人生病的害虫。", "target_word": "害虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些害虫会咬坏树皮。", "target_word": "害虫", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你看，这条绿色的害虫正在吃叶子。", "target_word": "害虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民很怕害虫，因为它们会吃掉粮食。", "target_word": "害虫", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "害蟲", "label": "繁体"}, {"form": "只", "label": "量词"}], "register": "中性", "sense_fingerprint": "伤害庄稼、树木或使人生病的虫子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a62cd1-2301-4b86-9410-1ff8ff7165a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21174, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "害虫", "is_correct": true, "explanation": "正确。害虫指伤害庄稼的虫子，蝗虫吃庄稼，属于害虫，句意相符。"}, {"text": "益虫", "is_correct": false, "explanation": "语义：益虫不伤害庄稼，与“吃庄稼的”相矛盾。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是虫子，句中说的是蝗虫，句子说不通。"}, {"text": "粮食", "is_correct": false, "explanation": "搭配：“吃庄稼的粮食”不通，粮食是被吃的东西，不能指吃庄稼的一方。"}], "explanations": {"害虫": "正确。害虫指伤害庄稼的虫子，蝗虫吃庄稼，属于害虫，句意相符。", "益虫": "语义：益虫不伤害庄稼，与“吃庄稼的”相矛盾。", "玩具": "语义：玩具不是虫子，句中说的是蝗虫，句子说不通。", "粮食": "搭配：“吃庄稼的粮食”不通，粮食是被吃的东西，不能指吃庄稼的一方。"}, "sentence_index": 0, "correct_answer": "害虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "瓢虫是害虫，能帮农民吃掉蚜虫。", "explanation": "这里应该用〈益虫〉。瓢虫吃蚜虫，对庄稼有益，不是伤害庄稼的害虫。"}, {"text": "这个程序里有害虫，运行时经常死机。", "explanation": "这里应该用〈漏洞〉。害虫指伤害庄稼、树木或让人生病的虫子；程序的错误要说“漏洞”。"}, {"text": "这种杀虫剂的害虫很小，可以放心用。", "explanation": "这里应该用〈害处〉。害虫指虫子，说杀虫剂的危害要用“害处”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3fe9057-f578-4751-9274-1fbd25223cef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "害虫", "is_correct": true, "explanation": "正确。蚊子会传播疾病、让人生病，属于害虫，句意相符。"}, {"text": "疾病", "is_correct": false, "explanation": "搭配：“会让人生病的”修饰的应是能致病的东西，“疾病”本身就是病，不能说“会让人生病的疾病”。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生是治病的人，与“会让人生病”的意思正好相反。"}, {"text": "玫瑰", "is_correct": false, "explanation": "语义：玫瑰是花，不会让人生病，与句意不符。"}], "explanations": {"害虫": "正确。蚊子会传播疾病、让人生病，属于害虫，句意相符。", "疾病": "搭配：“会让人生病的”修饰的应是能致病的东西，“疾病”本身就是病，不能说“会让人生病的疾病”。", "医生": "语义：医生是治病的人，与“会让人生病”的意思正好相反。", "玫瑰": "语义：玫瑰是花，不会让人生病，与句意不符。"}, "sentence_index": 6, "correct_answer": "害虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "伤口里有很多害虫，要用显微镜才能看见。", "explanation": "这里应该用〈细菌〉。细菌是很小的微生物，要用显微镜才能看见；害虫是虫子，不能这样用。"}, {"text": "流感害虫主要通过飞沫传播，所以要戴口罩。", "explanation": "这里应该用〈病毒〉。流感由病毒引起，病毒不是虫子，不能说“流感害虫”。"}, {"text": "这片地里的草是害虫，要用除草剂除掉。", "explanation": "这里应该用〈杂草〉。害虫指伤害庄稼或让人生病的虫子，草是植物，不能说害虫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3fe9057-f578-4751-9274-1fbd25223cef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "树皮下面藏着一棵害虫。", "corrected_sentence": "树皮下面藏着一只害虫。", "error_description": "量词错误：“害虫”应用量词“只”，“棵”只用于植物，不能用来数虫子。正确说法：树皮下面藏着一只害虫。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3fe9057-f578-4751-9274-1fbd25223cef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌子上有一本害虫，快把它赶走。", "corrected_sentence": "桌子上有一只害虫，快把它赶走。", "error_description": "量词错误：“本”用于书，虫子要用“只”。正确说法：桌子上有一只害虫，快把它赶走。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3fe9057-f578-4751-9274-1fbd25223cef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21176, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弃用", "is_correct": true, "explanation": "反义：“采用”是选定并使用，“弃用”是放弃不再使用，二者意思相反。"}, {"text": "研究", "is_correct": false, "explanation": "不构成反义：“研究”指探讨、钻研，与“采用”没有对立关系。"}, {"text": "观察", "is_correct": false, "explanation": "不构成反义：“观察”指仔细看，与“采用”的意思不对立。"}, {"text": "修理", "is_correct": false, "explanation": "不构成反义：“修理”指修补损坏的东西，与“采用”无关。"}], "correct_answer": "弃用", "explanations": {"弃用": "反义：“采用”是选定并使用，“弃用”是放弃不再使用，二者意思相反。", "研究": "不构成反义：“研究”指探讨、钻研，与“采用”没有对立关系。", "观察": "不构成反义：“观察”指仔细看，与“采用”的意思不对立。", "修理": "不构成反义：“修理”指修补损坏的东西，与“采用”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21176, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弃用", "is_correct": true, "explanation": "反义：“采用”是选定并使用，“弃用”是放弃不再使用，二者意思相反。"}, {"text": "讨论", "is_correct": false, "explanation": "不构成反义：“讨论”指交换意见、商议，与“采用”没有对立关系。"}, {"text": "设计", "is_correct": false, "explanation": "不构成反义：“设计”指构思并规划方案，与“采用”的意思不对立。"}, {"text": "训练", "is_correct": false, "explanation": "不构成反义：“训练”指有计划地教导和练习，与“采用”无关。"}], "correct_answer": "弃用", "explanations": {"弃用": "反义：“采用”是选定并使用，“弃用”是放弃不再使用，二者意思相反。", "讨论": "不构成反义：“讨论”指交换意见、商议，与“采用”没有对立关系。", "设计": "不构成反义：“设计”指构思并规划方案，与“采用”的意思不对立。", "训练": "不构成反义：“训练”指有计划地教导和练习，与“采用”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21176, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "选定某种方法、技术或意见并加以使用。", "primary_collocate": null, "pronunciation": "cǎi yòng", "ipa": "tsʰai˨˩˦ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "公司决定采用新的办法。", "target_word": "采用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家工厂采用了先进的技术。", "target_word": "采用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师采用小组学习的方式教我们。", "target_word": "采用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理采用了我的建议。", "target_word": "采用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座房子采用木头和玻璃建成。", "target_word": "采用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的学校采用电子课本上课。", "target_word": "采用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家讨论以后，决定采用第二个方案。", "target_word": "采用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新手机采用了更大的屏幕。", "target_word": "采用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书采用图文结合的方式介绍中国菜。", "target_word": "采用", "complexity_tier": "T3", "furigana": "cǎi yòng", "sentence_source": "generated"}, {"text": "医生采用新药治疗他的病。", "target_word": "采用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "采用了", "label": "完成体"}, {"form": "采用过", "label": "经历体"}, {"form": "採用", "label": "繁体"}], "register": "中性", "sense_fingerprint": "选定并使用某种方法、技术、材料或意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e685e353-0b99-4f1c-ae5d-499665025313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "采用", "is_correct": true, "explanation": "采用：指选定并使用某种办法，与“新的办法”搭配，符合句意。"}, {"text": "饮用", "is_correct": false, "explanation": "语义：“饮用”指喝，办法不能喝，句意不通。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑物或设施，不能用于办法，句意不通。"}, {"text": "接听", "is_correct": false, "explanation": "搭配：“接听”用于电话，不能说“接听新的办法”。"}], "explanations": {"采用": "采用：指选定并使用某种办法，与“新的办法”搭配，符合句意。", "饮用": "语义：“饮用”指喝，办法不能喝，句意不通。", "拆除": "语义：“拆除”指拆掉建筑物或设施，不能用于办法，句意不通。", "接听": "搭配：“接听”用于电话，不能说“接听新的办法”。"}, "sentence_index": 0, "correct_answer": "采用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校采用了三十名新生。", "explanation": "这里应该用〈录取〉。采用指选用方法、材料，不能用于录取人。"}, {"text": "我们去果园采用草莓。", "explanation": "这里应该用〈采摘〉。采用指选择并使用，不能用于摘取果实。"}, {"text": "我们采用了很多邮票。", "explanation": "这里应该用〈收集〉。采用指选定方法、材料来使用，不能用于收集物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "采用", "is_correct": true, "explanation": "采用：指选定某个方案来使用，与“第二个方案”搭配，符合句意。"}, {"text": "饮用", "is_correct": false, "explanation": "语义：“饮用”指喝，方案不能喝，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象一般是衣物、器具等，不能说“洗第二个方案”。"}, {"text": "抱", "is_correct": false, "explanation": "语义：“抱”要求对象是可以拥抱的人或物，方案不能被抱，句意不通。"}], "explanations": {"采用": "采用：指选定某个方案来使用，与“第二个方案”搭配，符合句意。", "饮用": "语义：“饮用”指喝，方案不能喝，句意不通。", "洗": "搭配：“洗”的对象一般是衣物、器具等，不能说“洗第二个方案”。", "抱": "语义：“抱”要求对象是可以拥抱的人或物，方案不能被抱，句意不通。"}, "sentence_index": 6, "correct_answer": "采用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们采用了一场精彩的比赛。", "explanation": "这里应该用〈观看〉。采用指选择方法、材料来使用，不能用于观看比赛。"}, {"text": "老师采用了他的道歉。", "explanation": "这里应该用〈接受〉。采用用于方法、建议等，不能用来接受别人的道歉。"}, {"text": "他采用了全部责任。", "explanation": "这里应该用〈承担〉。采用指选用，不指接过并负起责任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校采用了一条新的评价办法。", "corrected_sentence": "我们学校采用了一种新的评价办法。", "error_description": "错误在量词“条”。“办法”应用“种”计量，“条”用于细长的东西，不能用来计量办法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生决定很采用新药治疗他的病。", "corrected_sentence": "医生决定采用新药治疗他的病。", "error_description": "错误在“很”。“采用”是动作动词，不能受程度副词“很”修饰，应去掉“很”，说“决定采用新药”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
