INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21178, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公寓就是很多人住在一栋楼里，每家有自己的房间。", "primary_collocate": null, "pronunciation": "gōng yù", "ipa": "kʊŋ˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "这座公寓很高，住着几百个人。", "target_word": "公寓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公寓的邻居都很友好。", "target_word": "公寓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公寓里每家都有自己的门。", "target_word": "公寓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住公寓的人，常常在电梯里遇到邻居。", "target_word": "公寓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢住公寓，想要有院子的房子。", "target_word": "公寓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班后，我回到公寓，做了晚饭。", "target_word": "公寓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公寓有一个小花园。", "target_word": "公寓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友的公寓在八楼，窗外能看到河。", "target_word": "公寓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公寓的管理员每天早上打扫大厅。", "target_word": "公寓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她住在一栋公寓里，每家都有自己的房间。", "target_word": "公寓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "栋", "label": "量词"}, {"form": "公寓楼", "label": "复合"}], "register": "中性", "sense_fingerprint": "很多家住在一栋楼里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a62cd1-2301-4b86-9410-1ff8ff7165a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21178, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公寓", "is_correct": true, "explanation": "正确答案。公寓（gōng yù）是很多家住在一栋楼里的住宅。"}, {"text": "公路", "is_correct": false, "explanation": "lù 与 yù 声母不同（l／y），意思是公路。"}, {"text": "工具", "is_correct": false, "explanation": "jù 与 yù 声母不同（j／y），意思是工具。"}, {"text": "公务", "is_correct": false, "explanation": "wù 与 yù 声母不同（w／y），意思是公务。"}, {"text": "工序", "is_correct": false, "explanation": "xù 与 yù 声母不同（x／y），意思是工序。"}, {"text": "工余", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是工作之余。"}], "explanations": {"公寓": "正确答案。公寓（gōng yù）是很多家住在一栋楼里的住宅。", "公路": "lù 与 yù 声母不同（l／y），意思是公路。", "工具": "jù 与 yù 声母不同（j／y），意思是工具。", "公务": "wù 与 yù 声母不同（w／y），意思是公务。", "工序": "xù 与 yù 声母不同（x／y），意思是工序。", "工余": "yú（第二声）与 yù（第四声）声调不同，意思是工作之余。"}, "sentence_index": null, "correct_answer": "公寓"}, "level_3": {"options": [{"text": "公寓", "is_correct": true, "explanation": "正确。公寓是很多家住在一栋楼里的住宅，“这座公寓”搭配自然。"}, {"text": "铁塔", "is_correct": false, "explanation": "语义：铁塔不是住宅，句中“住着几百个人”与铁塔不符。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“很高”形容楼房，花园一般不说“很高”。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的场所，不会住着几百个人。"}], "explanations": {"公寓": "正确。公寓是很多家住在一栋楼里的住宅，“这座公寓”搭配自然。", "铁塔": "语义：铁塔不是住宅，句中“住着几百个人”与铁塔不符。", "花园": "搭配：“很高”形容楼房，花园一般不说“很高”。", "教室": "语义：教室是上课的场所，不会住着几百个人。"}, "sentence_index": 0, "correct_answer": "公寓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座公寓里堆满了货架，货物一直堆到天花板。", "explanation": "这里应该用〈仓库〉。公寓供人居住，满屋货架、货物堆到天花板属于仓库，不能用“公寓”。"}, {"text": "这座公寓里摆满了手术台，医生每天都在做手术。", "explanation": "这里应该用〈医院〉。公寓是供家庭居住的住宅，摆满手术台、天天做手术属于医院，不能用“公寓”。"}, {"text": "这座公寓的一楼是借书台，二楼到五楼都是书架。", "explanation": "这里应该用〈图书馆〉。公寓供人居住，借书台和书架属于图书馆，不能用“公寓”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3fe9057-f578-4751-9274-1fbd25223cef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21178, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "公寓", "is_correct": true, "explanation": "正确答案。公寓（gōng yù）是很多家住在一栋楼里的住宅。"}, {"text": "公墓", "is_correct": false, "explanation": "mù 与 yù 声母不同（m／y），意思是公墓（墓地）。"}, {"text": "公布", "is_correct": false, "explanation": "bù 与 yù 声母不同（b／y），意思是公开发布。"}, {"text": "公益", "is_correct": false, "explanation": "yì 与 yù 韵母不同（i／ü），意思是公共利益。"}], "explanations": {"公寓": "正确答案。公寓（gōng yù）是很多家住在一栋楼里的住宅。", "公墓": "mù 与 yù 声母不同（m／y），意思是公墓（墓地）。", "公布": "bù 与 yù 声母不同（b／y），意思是公开发布。", "公益": "yì 与 yù 韵母不同（i／ü），意思是公共利益。"}, "sentence_index": null, "correct_answer": "公寓"}, "level_3": {"options": [{"text": "公寓", "is_correct": true, "explanation": "正确。公寓是住宅楼，楼前或楼里可以有一个小花园。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不可能有小花园。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，不会“有一个小花园”。"}, {"text": "文件", "is_correct": false, "explanation": "搭配：“有一个小花园”说的是场所或建筑，“文件”不搭配。"}], "explanations": {"公寓": "正确。公寓是住宅楼，楼前或楼里可以有一个小花园。", "冰箱": "语义：冰箱是家用电器，不可能有小花园。", "手机": "语义：手机是通讯工具，不会“有一个小花园”。", "文件": "搭配：“有一个小花园”说的是场所或建筑，“文件”不搭配。"}, "sentence_index": 6, "correct_answer": "公寓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公寓里有很多车间，每个车间都有自己的门。", "explanation": "这里应该用〈工厂〉。车间是工厂的部分，公寓是住宅，不设车间。"}, {"text": "公寓里有很多牛棚，每个牛棚都有自己的门。", "explanation": "这里应该用〈农场〉。牛棚属于农场，公寓里不会有牛棚。"}, {"text": "公寓里有很多教室，每个教室都有自己的门。", "explanation": "这里应该用〈学校〉。教室是学校的场所，公寓是供家庭居住的楼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3fe9057-f578-4751-9274-1fbd25223cef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这栋公寓上有二十户人家。", "corrected_sentence": "这栋公寓里有二十户人家。", "error_description": "方位词错误：“公寓上”应改为“公寓里”。“上”指表面或某个层次，“里”表示在楼宇范围内部，住户所在的楼宇要用“里”。正确说法：这栋公寓里有二十户人家。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3fe9057-f578-4751-9274-1fbd25223cef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套公寓住了二十多户人家。", "corrected_sentence": "这栋公寓住了二十多户人家。", "error_description": "错误形式：“这套公寓”；正确形式：“这栋公寓”。“套”指单户住房，二十多户人家住在一起应用“栋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3fe9057-f578-4751-9274-1fbd25223cef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
