INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21180, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "你从几个东西里挑一个你想要的。", "primary_collocate": null, "pronunciation": "xuǎn zé", "ipa": "ɕɥɛn˨˩˦ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "你选择哪一个？", "target_word": "选择", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我选择红色的。", "target_word": "选择", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他选择去北京工作。", "target_word": "选择", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请选择你喜欢的水果。", "target_word": "选择", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我选择坐火车去上海。", "target_word": "选择", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她选择了一条安静的路。", "target_word": "选择", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面前有三条路，你要选择一条。", "target_word": "选择", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大学毕业以后，他选择留在家乡。", "target_word": "选择", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜单上有很多菜，我不知道该选择什么。", "target_word": "选择", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们选择了便宜的酒店，因为这次旅行钱不多。", "target_word": "选择", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "选择了", "label": "完成体"}, {"form": "选择过", "label": "经历体"}, {"form": "選擇", "label": "繁体"}], "register": "中性", "sense_fingerprint": "选择|从几个里挑出想要的一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e7fa8c-7e28-4a9f-9f73-de782ccd99f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选择", "is_correct": true, "explanation": "选择：从几个东西里挑出一个。“你选择哪一个”是正确的说法。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”不能用来挑选“哪一个”，句子说不通。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是自然现象，不能带“哪一个”作宾语，句子说不通。"}, {"text": "生病", "is_correct": false, "explanation": "配价：“生病”是不及物动词，后面不能接“哪一个”这样的宾语。"}], "explanations": {"选择": "选择：从几个东西里挑出一个。“你选择哪一个”是正确的说法。", "哭": "语义：“哭”不能用来挑选“哪一个”，句子说不通。", "下雨": "语义：“下雨”是自然现象，不能带“哪一个”作宾语，句子说不通。", "生病": "配价：“生病”是不及物动词，后面不能接“哪一个”这样的宾语。"}, "sentence_index": 0, "correct_answer": "选择"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我选择了一会儿电视，就去睡觉了。", "explanation": "这里应该用〈看〉。“选择”是从几个东西里挑一个，不能和“一会儿电视”搭配；说看电视要用〈看〉。"}, {"text": "我每天晚上都给妈妈选择电话。", "explanation": "这里应该用〈打〉。“选择”是从几个东西里挑一个，不能说“选择电话”；联系别人要说〈打〉电话。"}, {"text": "他选择了一场病，很久没去上班。", "explanation": "这里应该用〈得〉。“选择”是从几个东西里挑一个，人不能挑着生病；说患了病要用〈得〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选择", "is_correct": true, "explanation": "选择：从几个东西里挑出一个。“你要选择一条”是正确的说法。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象不能是路，句子说不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能用于“一条路”。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能接“一条”这样的宾语。"}], "explanations": {"选择": "选择：从几个东西里挑出一个。“你要选择一条”是正确的说法。", "洗": "语义：“洗”的对象不能是路，句子说不通。", "吃": "语义：“吃”的对象是食物，不能用于“一条路”。", "睡": "配价：“睡”是不及物动词，后面不能接“一条”这样的宾语。"}, "sentence_index": 6, "correct_answer": "选择"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她选择了很多眼泪，一直哭个不停。", "explanation": "这里应该用〈流〉。“选择”是从几个东西里挑一个，不能和“眼泪”搭配；说眼泪要用〈流〉。"}, {"text": "这间屋子选择了很大的窗户。", "explanation": "这里应该用〈装〉。窗户是人装上去的，屋子不能挑选窗户；说装窗户要用〈装〉。"}, {"text": "这棵树选择了很多叶子，一年四季都很绿。", "explanation": "这里应该用〈长〉。叶子是树自己长出来的，不是挑选出来的；说树长出叶子要用〈长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他选择很仔细，每件东西都看了好久。", "corrected_sentence": "他选择得很仔细，每件东西都看了好久。", "error_description": "错误：“选择很仔细”。正确：“选择得很仔细”。动词“选择”后面接描写程度的补语，要用“得”连接，不能直接用“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没选择了这条路。", "corrected_sentence": "我从来没选择过这条路。", "error_description": "错误：“没选择了”。正确：“没选择过”。表示从来没有过某种经历时，“没”要和“过”搭配，不能和“了”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
