INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21182, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蚯蚓是一种生活在土里的小虫子，身体软软的，像一根小绳子。", "primary_collocate": null, "pronunciation": "qiū yǐn", "ipa": "tɕʰjoʊ˥ jɪn˨˩˦", "syllable_count": 2, "sentences": [{"text": "蚯蚓是土里的小虫子，身体软软的。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一条蚯蚓，像小绳子。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨天，蚯蚓会从土里爬出来。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟怕蚯蚓，不敢用手摸。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚯蚓没有脚，只能慢慢地爬。", "target_word": "蚯蚓", "complexity_tier": "T3", "furigana": "qiū yǐn méi yǒu jiǎo, zhǐ néng màn màn de pá.", "sentence_source": "generated"}, {"text": "公园的草地上有很多蚯蚓。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在花盆里看到了一条蚯蚓。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来了，蚯蚓钻回土里去了。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说蚯蚓对花很有好处。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸡一口就吃了那条蚯蚓。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "生活在土里、身体软软像小绳子的小虫子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddda3849-c2ef-4d42-b931-c11a2d196bc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蚯蚓", "is_correct": true, "explanation": "正确：蚯蚓生活在土里，身体软软的，是小虫子，与句子描述相符。"}, {"text": "蜜蜂", "is_correct": false, "explanation": "语义：蜜蜂靠翅膀在空中飞、采花，不住在土里。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "语义：蝴蝶是飞行的昆虫，不生活在土里。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "体貌：蚂蚁身体外面有坚硬的外壳，与句中“身体软软的”不符。"}], "explanations": {"蚯蚓": "正确：蚯蚓生活在土里，身体软软的，是小虫子，与句子描述相符。", "蜜蜂": "语义：蜜蜂靠翅膀在空中飞、采花，不住在土里。", "蝴蝶": "语义：蝴蝶是飞行的昆虫，不生活在土里。", "蚂蚁": "体貌：蚂蚁身体外面有坚硬的外壳，与句中“身体软软的”不符。"}, "sentence_index": 0, "correct_answer": "蚯蚓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈买了一颗蚯蚓当宠物。", "explanation": "这里应该用〈条〉。蚯蚓身体细长，应用量词“条”；“颗”用于圆粒状的东西。"}, {"text": "医生说这种寄生虫叫蚯蚓，寄生在小肠里。", "explanation": "这里应该用〈蛔虫〉。寄生在小肠里的是蛔虫；蚯蚓生活在土里，不寄生在人体内。"}, {"text": "蚯蚓结的茧可以用来抽丝。", "explanation": "这里应该用〈蚕〉。能结茧、用来抽丝的是蚕；蚯蚓不结茧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蚯蚓", "is_correct": true, "explanation": "正确：蚯蚓是细长的小虫，可以放在花盆的土里，与句子相符。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是大片的水体，不可能出现在花盆里。"}, {"text": "公路", "is_correct": false, "explanation": "语义：公路是路面，不能出现在花盆里。"}, {"text": "鲸鱼", "is_correct": false, "explanation": "体貌：鲸鱼体型巨大，装不进花盆，与句中的小虫子体型不符。"}], "explanations": {"蚯蚓": "正确：蚯蚓是细长的小虫，可以放在花盆的土里，与句子相符。", "河": "语义：河是大片的水体，不可能出现在花盆里。", "公路": "语义：公路是路面，不能出现在花盆里。", "鲸鱼": "体貌：鲸鱼体型巨大，装不进花盆，与句中的小虫子体型不符。"}, "sentence_index": 6, "correct_answer": "蚯蚓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蚯蚓有毒，咬人很疼，要小心。", "explanation": "这里应该用〈蜈蚣〉。有毒、会咬人的是蜈蚣；蚯蚓没有毒，也不咬人。"}, {"text": "蚯蚓背着壳，慢慢爬过墙。", "explanation": "这里应该用〈蜗牛〉。背着壳慢慢爬过墙的是蜗牛；蚯蚓没有壳。"}, {"text": "蚯蚓会吸血，附在腿上不容易掉。", "explanation": "这里应该用〈蚂蟥〉。吸血、附在腿上不容易掉的是蚂蟥；蚯蚓不吸血。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草地上有一颗蚯蚓，身子软软的。", "corrected_sentence": "草地上有一条蚯蚓，身子软软的。", "error_description": "量词错误：蚯蚓身体细长，应用量词“条”，不能用“颗”（“颗”用于圆粒状的东西）。正确说法是“一条蚯蚓”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "园丁在花园里挖到一条软软地蚯蚓。", "corrected_sentence": "园丁在花园里挖到一条软软的蚯蚓。", "error_description": "结构助词错误：修饰名词“蚯蚓”要用结构助词“的”，不能用“地”（“地”用于修饰动词）。正确说法是“一条软软的蚯蚓”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
