INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21184, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "肠道是身体里一条长长的管道，食物在里面消化。", "primary_collocate": null, "pronunciation": "cháng dào", "ipa": "ʈʂʰɑŋ˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "吃进嘴里的食物最后会到肠道。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩肚子疼，可能是肠道出了问题。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肠道很长，大人的有好几米。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果里的纤维能帮肠道工作。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝太多冷水，肠道会不舒服。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肠道把食物里的营养吸收了。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃坏了东西，肠道很难受。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用小机器看了看我的肠道。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保持好心情，肠道也会更健康。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肠道里的食物慢慢往下走。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "腸道", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体里食物消化的长管道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddda3849-c2ef-4d42-b931-c11a2d196bc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肠道", "is_correct": true, "explanation": "正确：吃进嘴里的食物经过胃之后，最后会到肠道，与句子相符。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不属于消化系统，吃进嘴里的食物不会到眼睛。"}, {"text": "大海", "is_correct": false, "explanation": "语义：食物不会流入大海，句子讲的是人体的消化过程。"}, {"text": "嘴巴", "is_correct": false, "explanation": "搭配：食物是从嘴巴吃进去的，“最后会到嘴巴”逻辑不通，不能与“最后”搭配。"}], "explanations": {"肠道": "正确：吃进嘴里的食物经过胃之后，最后会到肠道，与句子相符。", "眼睛": "语义：眼睛不属于消化系统，吃进嘴里的食物不会到眼睛。", "大海": "语义：食物不会流入大海，句子讲的是人体的消化过程。", "嘴巴": "搭配：食物是从嘴巴吃进去的，“最后会到嘴巴”逻辑不通，不能与“最后”搭配。"}, "sentence_index": 0, "correct_answer": "肠道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生在他的身体里找到了一座肠道。", "explanation": "这里应该用〈段〉。肠道是长管子，量词用“段”；“座”用于山、桥、楼等大型建筑。"}, {"text": "肠道能储存胆汁，帮助消化脂肪。", "explanation": "这里应该用〈胆囊〉。储存胆汁、经导管流入肠道的是胆囊；肠道本身不储存胆汁。"}, {"text": "肠道连接嘴和胃。", "explanation": "这里应该用〈食道〉。连接嘴和胃的是食道；肠道位于胃的下方，不连接嘴和胃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肠道", "is_correct": true, "explanation": "正确：吃坏东西引起的不适在消化道，句中指的是肠道难受。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：吃坏东西引起的不适在消化系统，不会让耳朵难受。"}, {"text": "手指", "is_correct": false, "explanation": "语义：吃坏东西不会直接让手指难受，句中讲的是消化系统的不适。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“很难受”说的是人或身体部位，书包不能“难受”。"}], "explanations": {"肠道": "正确：吃坏东西引起的不适在消化道，句中指的是肠道难受。", "耳朵": "语义：吃坏东西引起的不适在消化系统，不会让耳朵难受。", "手指": "语义：吃坏东西不会直接让手指难受，句中讲的是消化系统的不适。", "书包": "搭配：“很难受”说的是人或身体部位，书包不能“难受”。"}, "sentence_index": 6, "correct_answer": "肠道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "肠道是空气进入肺的通道。", "explanation": "这里应该用〈气管〉。空气经过气管进入肺；肠道是消化管，不通向肺。"}, {"text": "肠道把血液送到全身。", "explanation": "这里应该用〈血管〉。输送血液的是血管；肠道是消化管，不输送血液。"}, {"text": "肠道把尿液送到膀胱。", "explanation": "这里应该用〈输尿管〉。把尿液送到膀胱的是输尿管；肠道不输送尿液。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块肠道又长又细。", "corrected_sentence": "这段肠道又长又细。", "error_description": "量词错误：肠道是长管状器官，应用量词“段”，不能用“块”。正确说法是“这段肠道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生说他要切掉一座肠道。", "corrected_sentence": "医生说他要切掉一段肠道。", "error_description": "量词错误：肠道是长管状器官，应用量词“段”，不能用“座”（“座”用于山、桥、楼等）。正确说法是“一段肠道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
