INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21186, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "关得严严实实的，不让东西出来或进去。", "primary_collocate": null, "pronunciation": "mì bì shì", "ipa": "mi˥˩ pi˥˩ ʂʐ̩˥˩", "syllable_count": 3, "sentences": [{"text": "这个密闭式饭盒，汤不会洒出来。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "密闭式的瓶子可以放在书包里。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的零食装在密闭式盒子里。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "密闭式的箱子防水，也防灰尘。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一个密闭式的茶叶罐。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间密闭式仓库没有窗户。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "密闭式的杯盖让热茶更久不凉。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠进不去密闭式粮桶。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验用的密闭式容器，空气进不去。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的米放在密闭式桶里。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "关得严实、东西进出不了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7a62cd1-2301-4b86-9410-1ff8ff7165a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密闭式", "is_correct": true, "explanation": "正确。密闭式饭盒关得严实，汤不会洒出来。"}, {"text": "开口式", "is_correct": false, "explanation": "语义：开口饭盒盖不住，汤会洒出来，与“不会洒出来”矛盾。"}, {"text": "镂空式", "is_correct": false, "explanation": "语义：镂空饭盒会漏汤，与“汤不会洒出来”矛盾。"}, {"text": "敞口式", "is_correct": false, "explanation": "搭配：“饭盒”一般有盖，“敞口式饭盒”与常见用法不符。"}], "explanations": {"密闭式": "正确。密闭式饭盒关得严实，汤不会洒出来。", "开口式": "语义：开口饭盒盖不住，汤会洒出来，与“不会洒出来”矛盾。", "镂空式": "语义：镂空饭盒会漏汤，与“汤不会洒出来”矛盾。", "敞口式": "搭配：“饭盒”一般有盖，“敞口式饭盒”与常见用法不符。"}, "sentence_index": 0, "correct_answer": "密闭式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个密闭式的广场，市民可以在里面散步。", "explanation": "这里应该用〈露天〉。密闭式指严密封闭、与外界隔绝，广场是露天空间，不能用“密闭”。"}, {"text": "这扇密闭式的门，每天都有上百人进出。", "explanation": "这里应该用〈敞开〉。密闭式的门关得严实、不让东西进出，与“每天上百人进出”矛盾，要用“敞开”。"}, {"text": "这种密闭式的布袋，能让蔬菜慢慢呼吸。", "explanation": "这里应该用〈透气〉。密闭式的布袋东西进不去，蔬菜呼吸需要空气流通，应该用“透气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3fe9057-f578-4751-9274-1fbd25223cef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密闭式", "is_correct": true, "explanation": "正确。密闭式杯盖严密封闭，能保温，所以热茶更久不凉。"}, {"text": "冷藏式", "is_correct": false, "explanation": "语义：冷藏式杯盖会让热茶变凉，与“更久不凉”矛盾。"}, {"text": "散热式", "is_correct": false, "explanation": "语义：散热式杯盖散热快，热茶不会更久不凉。"}, {"text": "薄片式", "is_correct": false, "explanation": "搭配：“薄片式”多用于形容食物或材料，不用来修饰杯盖。"}], "explanations": {"密闭式": "正确。密闭式杯盖严密封闭，能保温，所以热茶更久不凉。", "冷藏式": "语义：冷藏式杯盖会让热茶变凉，与“更久不凉”矛盾。", "散热式": "语义：散热式杯盖散热快，热茶不会更久不凉。", "薄片式": "搭配：“薄片式”多用于形容食物或材料，不用来修饰杯盖。"}, "sentence_index": 6, "correct_answer": "密闭式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个密闭式的饮料罐，汽水很快就会漏出来。", "explanation": "这里应该用〈敞口〉。密闭式的罐子封闭不漏，与“汽水很快漏出来”矛盾，要用“敞口”。"}, {"text": "这个密闭式的粮桶，老鼠很容易就能钻进去。", "explanation": "这里应该用〈有缝隙〉。密闭式的粮桶关得严实，老鼠进不去，与“老鼠很容易钻进去”矛盾，要用“有缝隙”。"}, {"text": "这个密闭式的香料瓶，香味能飘满整个厨房。", "explanation": "这里应该用〈开口〉。密闭式的瓶子关得严实，香味散不出来，与“飘满整个厨房”矛盾，要用“开口”的瓶子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3fe9057-f578-4751-9274-1fbd25223cef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个保温桶密闭式的，热水不会漏出来。", "corrected_sentence": "这个保温桶是密闭式的，热水不会漏出来。", "error_description": "错误形式：“保温桶密闭式的”；正确形式：“保温桶是密闭式的”。作谓语时“密闭式的”前要有“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3fe9057-f578-4751-9274-1fbd25223cef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家的饼干盒很密闭式的，能保存很久。", "corrected_sentence": "我家的饼干盒是密闭式的，能保存很久。", "error_description": "错误形式：“很密闭式的”；正确形式：“是密闭式的”。“密闭式”是类别性质的词，不能用“很”修饰，作谓语要用“是……的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3fe9057-f578-4751-9274-1fbd25223cef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
