INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21188, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21188, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里的一种东西，能帮助小朋友长个子。", "primary_collocate": null, "pronunciation": "shēng zhǎng jī sù", "ipa": "ʂɤŋ˥ ʈʂɑŋ˨˩˦ tɕi˥ su˥˩", "syllable_count": 4, "sentences": [{"text": "生长激素能让小朋友长高。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明个子矮，医生查了他的生长激素。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早点睡觉，身体里的生长激素才会多。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药里有生长激素。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长得慢，可能和生长激素有关。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体里没有足够的生长激素，个子就长不高。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉的时候，生长激素最活跃。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸带女儿去医院测生长激素。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多运动也能让生长激素变多。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生长激素是身体自己做出来的。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生長激素", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体里帮助小朋友长个子的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddda3849-c2ef-4d42-b931-c11a2d196bc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21188, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生长激素", "is_correct": true, "explanation": "生长激素：作主语，指身体里能帮助小朋友长个子的物质，符合句意。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能让小朋友长高，不符合句意。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不能让小朋友长高，不符合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车与身体生长无关，不能使人长高。"}], "explanations": {"生长激素": "生长激素：作主语，指身体里能帮助小朋友长个子的物质，符合句意。", "玩具": "语义：玩具不能让小朋友长高，不符合句意。", "电视": "语义：电视不能让小朋友长高，不符合句意。", "汽车": "语义：汽车与身体生长无关，不能使人长高。"}, "sentence_index": 0, "correct_answer": "生长激素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一只生长激素。", "explanation": "这里应该用〈针〉。「只」用于动物等，注射药剂要用〈针〉。"}, {"text": "医生给他打了一张生长激素。", "explanation": "这里应该用〈针〉。「张」用于纸、桌子等扁平的东西，打针要用〈针〉。"}, {"text": "这种药里有一朵生长激素。", "explanation": "这里应该用〈针〉或〈支〉。「朵」用于花等，不能用来计量注射药剂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生长激素", "is_correct": true, "explanation": "生长激素：作主语，指身体自己产生、睡觉时最活跃的物质，符合句意。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不会在睡觉时活跃，与句意矛盾。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能“活跃”，与句意不符。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“活跃”多用于人体、细胞等，不用于形容窗帘。"}], "explanations": {"生长激素": "生长激素：作主语，指身体自己产生、睡觉时最活跃的物质，符合句意。", "课本": "语义：课本不会在睡觉时活跃，与句意矛盾。", "冰箱": "语义：冰箱是家用电器，不能“活跃”，与句意不符。", "窗帘": "搭配：“活跃”多用于人体、细胞等，不用于形容窗帘。"}, "sentence_index": 6, "correct_answer": "生长激素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一座生长激素。", "explanation": "这里应该用〈针〉。「座」用于山、桥等大型建筑，不能用来计量药剂。"}, {"text": "他的药箱里放着一条生长激素。", "explanation": "这里应该用〈针〉或〈支〉。「条」用于细长的东西，注射用的生长激素要用〈针〉。"}, {"text": "他买了一把生长激素。", "explanation": "这里应该用〈针〉。「把」用于有柄的器具，计量注射剂要用〈针〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他需要定期注射一只生长激素。", "corrected_sentence": "他需要定期注射一针生长激素。", "error_description": "错误形式「一只生长激素」，正确形式「一针生长激素」。「只」不用于注射药剂，要用「针」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生开了一块生长激素。", "corrected_sentence": "医生开了一支生长激素。", "error_description": "错误形式「一块生长激素」，正确形式「一支生长激素」。「块」用于块状的东西，注射药剂要用「支」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
