INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21190, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种黄色的、很值钱的金属。", "primary_collocate": null, "pronunciation": "jīn zi", "ipa": "tɕin˥ tsɿ", "syllable_count": 2, "sentences": [{"text": "他在沙子里找到了金子。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金子是黄色的，银子是白色的。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小孩第一次看见真的金子。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说金子比铁贵很多。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头里面有金子吗？", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行里放着很多金子。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金子放久了也不会变色。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用金子给妈妈做了一条链子。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把金子藏在院子里。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时挖过金子。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块金子", "label": "量词"}, {"form": "一堆金子", "label": "量词"}], "register": "口语", "sense_fingerprint": "黄色的值钱金属", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9725243-d8db-4d53-b783-229059d8c9b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21190, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "金子", "is_correct": true, "explanation": "正确：金子（jīn zi）指黄金。"}, {"text": "金字", "is_correct": false, "explanation": "第二音节声调不同（zi 轻声与 zì 第四声），意思是金色的字，如金字招牌。"}, {"text": "金丝", "is_correct": false, "explanation": "第二音节声母不同（z／s，zi 与 sī），意思是金色的细丝，如金丝眼镜。"}, {"text": "金质", "is_correct": false, "explanation": "第二音节声母与声调不同（z／zh，zi 与 zhì），意思是金质，如金质奖章。"}], "explanations": {"金子": "正确：金子（jīn zi）指黄金。", "金字": "第二音节声调不同（zi 轻声与 zì 第四声），意思是金色的字，如金字招牌。", "金丝": "第二音节声母不同（z／s，zi 与 sī），意思是金色的细丝，如金丝眼镜。", "金质": "第二音节声母与声调不同（z／zh，zi 与 zhì），意思是金质，如金质奖章。"}, "sentence_index": null, "correct_answer": "金子"}, "level_3": {"options": [{"text": "金子", "is_correct": true, "explanation": "正确：金子是埋在沙子里可以被找到的黄色金属。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的气体，不能在沙子里“找到”。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“找到”后面接的是具体的东西，“感情”是抽象的心理状态，不能说“在沙子里找到了感情”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是数值或感觉，不是可以在沙子里找到的物体。"}], "explanations": {"金子": "正确：金子是埋在沙子里可以被找到的黄色金属。", "空气": "语义：空气是无形的气体，不能在沙子里“找到”。", "感情": "搭配：“找到”后面接的是具体的东西，“感情”是抽象的心理状态，不能说“在沙子里找到了感情”。", "温度": "语义：温度是数值或感觉，不是可以在沙子里找到的物体。"}, "sentence_index": 0, "correct_answer": "金子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "钢是一种很硬的金子。", "explanation": "这里应该用〈金属〉。金子专指黄金，说“一种很硬的……”这类泛指时要用〈金属〉，钢是合金。"}, {"text": "这套房子位于金子地段。", "explanation": "这里应该用〈黄金〉。“黄金地段”是固定说法，不说“金子地段”。"}, {"text": "他把金子穿在脚上去跑步。", "explanation": "这里应该用〈鞋〉。金子是金属，不能穿在脚上，穿在脚上的是鞋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21190, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "金子", "is_correct": true, "explanation": "正确：金子（jīn zi）指黄金。"}, {"text": "镜子", "is_correct": false, "explanation": "jīn（第一声）与 jìng（第四声）韵尾不同（n／ng），声调也不同，意思是镜子。"}, {"text": "亲子", "is_correct": false, "explanation": "jīn 与 qīn 声母不同（j／q），意思是亲子，即父母与子女。"}, {"text": "金字", "is_correct": false, "explanation": "第二音节声调不同（zi 轻声与 zì 第四声），意思是金色的字，如金字招牌。"}, {"text": "金纸", "is_correct": false, "explanation": "第二音节声母与声调不同（zi 与 zhǐ，z／zh），意思是烧纸用的金色纸。"}], "explanations": {"金子": "正确：金子（jīn zi）指黄金。", "镜子": "jīn（第一声）与 jìng（第四声）韵尾不同（n／ng），声调也不同，意思是镜子。", "亲子": "jīn 与 qīn 声母不同（j／q），意思是亲子，即父母与子女。", "金字": "第二音节声调不同（zi 轻声与 zì 第四声），意思是金色的字，如金字招牌。", "金纸": "第二音节声母与声调不同（zi 与 zhǐ，z／zh），意思是烧纸用的金色纸。"}, "sentence_index": null, "correct_answer": "金子"}, "level_3": {"options": [{"text": "金子", "is_correct": true, "explanation": "正确：金子是稳定的金属，放久了也不会变色。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“放久了”要求可以存放的物品，“天气”不能被存放。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，不能被“放久”，也谈不上“变色”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是词语，不能被放置，也不会变色。"}], "explanations": {"金子": "正确：金子是稳定的金属，放久了也不会变色。", "天气": "搭配：“放久了”要求可以存放的物品，“天气”不能被存放。", "时间": "语义：时间是抽象概念，不能被“放久”，也谈不上“变色”。", "名字": "语义：名字是词语，不能被放置，也不会变色。"}, "sentence_index": 6, "correct_answer": "金子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "金子是一种很好吃的水果。", "explanation": "这里应该用〈苹果〉。金子是金属，不是水果，不能吃。"}, {"text": "他在厨房里煮了一锅金子。", "explanation": "这里应该用〈饭〉。金子是金属，不能煮来吃，应说「煮了一锅饭」。"}, {"text": "他每天喝很多金子。", "explanation": "这里应该用〈水〉。金子是金属，不能当饮品喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只金子是黄色的。", "corrected_sentence": "这块金子是黄色的。", "error_description": "错误：金子是块状材料，量词应用“块”。“只”一般用于动物或成对物件中的一个，不用于这类块状金属。正确说法为“这块金子是黄色的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用金子藏进了院子里的箱子。", "corrected_sentence": "他把金子藏进了院子里的箱子。", "error_description": "错误：处置式要用“把”引出被处置的“金子”，“用”不能这样引出。正确说法为“他把金子藏进了院子里的箱子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
