INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21192, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "非常非常小的生物，用眼睛看不见。", "primary_collocate": null, "pronunciation": "wēi shēng wù", "ipa": "wei̯˥ ʂɤŋ˥ u˥˩", "syllable_count": 3, "sentences": [{"text": "微生物非常小，我们用眼睛看不见。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酸奶里有很多有用的微生物。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地里住着很多微生物。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用显微镜看水里的微生物。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的微生物对人有好处，有的会让人生病。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物放久了，上面会长出微生物。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "微生物让牛奶变成了酸奶。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗手可以洗掉手上的很多微生物。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海里也有微生物，它们小得看不见。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种微生物只在热水里生活。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "微生物学", "label": "复合"}], "register": "中性", "sense_fingerprint": "极小、肉眼看不见的生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a956c441-19d3-4000-954b-c5a96b39ceec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微生物", "is_correct": true, "explanation": "“微生物”指极小的生物，符合“非常小、用眼睛看不见”的描述。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象体型巨大，与句中“非常小”的描述相矛盾。"}, {"text": "高山", "is_correct": false, "explanation": "语义：高山体积庞大，与“用眼睛看不见”相矛盾。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“小说”不是实体，不能说“用眼睛看不见”。"}], "explanations": {"微生物": "“微生物”指极小的生物，符合“非常小、用眼睛看不见”的描述。", "大象": "体貌：大象体型巨大，与句中“非常小”的描述相矛盾。", "高山": "语义：高山体积庞大，与“用眼睛看不见”相矛盾。", "小说": "搭配：“小说”不是实体，不能说“用眼睛看不见”。"}, "sentence_index": 0, "correct_answer": "微生物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜空中有很多微生物，一闪一闪的。", "explanation": "这里应该用〈星星〉。星星在夜空中一闪一闪地发光，“微生物”要用显微镜才能看见，不会在夜空中闪烁。"}, {"text": "她看着我，脸上带着微生物。", "explanation": "这里应该用〈微笑〉。脸上的表情要用“微笑”，“微生物”指极小的生物。"}, {"text": "这种微生物可以用来做玻璃。", "explanation": "这里应该用〈矿物〉。玻璃由矿物原料制成，微生物不能用来做玻璃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微生物", "is_correct": true, "explanation": "“微生物”能让牛奶发酵变成酸奶，符合句意。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不能使牛奶发酵变成酸奶，句意不通。"}, {"text": "锤子", "is_correct": false, "explanation": "语义：锤子不能使牛奶发生这样的变化，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“让”后的主语须能对牛奶施加作用，石头不能对牛奶施加这种作用。"}], "explanations": {"微生物": "“微生物”能让牛奶发酵变成酸奶，符合句意。", "汽油": "语义：汽油不能使牛奶发酵变成酸奶，句意不通。", "锤子": "语义：锤子不能使牛奶发生这样的变化，句意不通。", "石头": "配价：“让”后的主语须能对牛奶施加作用，石头不能对牛奶施加这种作用。"}, "sentence_index": 6, "correct_answer": "微生物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种微生物会叫，还会跑。", "explanation": "这里应该用〈动物〉。微生物极小，肉眼看不见，不会叫，也不会跑。"}, {"text": "这种微生物很硬，可以盖房子。", "explanation": "这里应该用〈岩石〉。岩石坚硬，可以盖房子；微生物没有这些特点。"}, {"text": "这种微生物很甜，孩子们都爱吃。", "explanation": "这里应该用〈水果〉。水果有甜味，可以吃；微生物肉眼看不见，不能当食物吃，这里不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只微生物，只能用显微镜看见。", "corrected_sentence": "这是一种微生物，只能用显微镜看见。", "error_description": "量词错误：“微生物”一般按种类来数，用量词“种”，不说“一只微生物”，应说“一种微生物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖水里有很多微生物们。", "corrected_sentence": "湖水里有很多微生物。", "error_description": "“们”不能和“很多”等表示数量的词一起用。前面已经有“很多”，后面就不能再加“们”，应说“很多微生物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21194, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失去", "is_correct": true, "explanation": "「失去」与「拥有」相反，指不再拥有某物。"}, {"text": "跑步", "is_correct": false, "explanation": "「跑步」指身体运动，与「拥有」没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "「写字」指书写活动，与「拥有」没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "「睡觉」指休息的动作，与「拥有」没有反义关系。"}], "correct_answer": "失去", "explanations": {"失去": "「失去」与「拥有」相反，指不再拥有某物。", "跑步": "「跑步」指身体运动，与「拥有」没有反义关系。", "写字": "「写字」指书写活动，与「拥有」没有反义关系。", "睡觉": "「睡觉」指休息的动作，与「拥有」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21194, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失去", "is_correct": true, "explanation": "「失去」与「拥有」相反，指不再拥有某物。"}, {"text": "游泳", "is_correct": false, "explanation": "「游泳」是体育运动，与「拥有」没有反义关系。"}, {"text": "咳嗽", "is_correct": false, "explanation": "「咳嗽」指身体的症状，与「拥有」没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "「跳舞」指身体动作，与「拥有」没有反义关系。"}], "correct_answer": "失去", "explanations": {"失去": "「失去」与「拥有」相反，指不再拥有某物。", "游泳": "「游泳」是体育运动，与「拥有」没有反义关系。", "咳嗽": "「咳嗽」指身体的症状，与「拥有」没有反义关系。", "跳舞": "「跳舞」指身体动作，与「拥有」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21194, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有某样东西在自己这里。", "primary_collocate": null, "pronunciation": "yōng yǒu", "ipa": "yʊŋ˥ iou˨˩˦", "syllable_count": 2, "sentences": [{"text": "我拥有一本很旧的词典。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他现在拥有一辆新自行车。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明拥有很多玩具。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拥有一张去北京的票。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷拥有一块小小的地。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫拥有一个软软的小窝。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的钥匙只有他一个人拥有。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟拥有一台旧电脑。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拥有的东西不多。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拥有两个手机。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拥有了", "label": "体标"}, {"form": "拥有着", "label": "体标"}, {"form": "拥有过", "label": "体标"}], "register": "中性", "sense_fingerprint": "某样东西属于自己、在自己手里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9725243-d8db-4d53-b783-229059d8c9b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21194, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拥有", "is_correct": true, "explanation": "拥有（yōng yǒu）：有某样东西在自己这里，即本词条的读音与意思。"}, {"text": "应有", "is_correct": false, "explanation": "应有（yīng yǒu）与拥有（yōng yǒu）韵母不同：ing 与 ong，意思是「应该有的」。"}, {"text": "公有", "is_correct": false, "explanation": "公有（gōng yǒu）与拥有（yōng yǒu）声母不同：g 与 y，意思是共同所有。"}, {"text": "空有", "is_correct": false, "explanation": "空有（kōng yǒu）与拥有（yōng yǒu）声母不同：k 与 y，意思是徒有、白白有。"}], "explanations": {"拥有": "拥有（yōng yǒu）：有某样东西在自己这里，即本词条的读音与意思。", "应有": "应有（yīng yǒu）与拥有（yōng yǒu）韵母不同：ing 与 ong，意思是「应该有的」。", "公有": "公有（gōng yǒu）与拥有（yōng yǒu）声母不同：g 与 y，意思是共同所有。", "空有": "空有（kōng yǒu）与拥有（yōng yǒu）声母不同：k 与 y，意思是徒有、白白有。"}, "sentence_index": null, "correct_answer": "拥有"}, "level_3": {"options": [{"text": "拥有", "is_correct": true, "explanation": "「拥有」表示某物在自己手中，「一本很旧的词典」可以被领有，句子通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能接词典作宾语，「吃一本很旧的词典」不成立。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」不能接词典作宾语，「喝一本很旧的词典」不成立。"}, {"text": "具备", "is_correct": false, "explanation": "搭配：「具备」后接能力、条件等抽象事物，不说「具备一本词典」。"}], "explanations": {"拥有": "「拥有」表示某物在自己手中，「一本很旧的词典」可以被领有，句子通顺。", "吃": "搭配：「吃」不能接词典作宾语，「吃一本很旧的词典」不成立。", "喝": "搭配：「喝」不能接词典作宾语，「喝一本很旧的词典」不成立。", "具备": "搭配：「具备」后接能力、条件等抽象事物，不说「具备一本词典」。"}, "sentence_index": 0, "correct_answer": "拥有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间里拥有一股奇怪的味道。", "explanation": "这里应该用〈有〉。拥有表示人领有某物，味道不是被领有的东西，应说「房间里有一股奇怪的味道」。"}, {"text": "全班同学都拥有他的建议。", "explanation": "这里应该用〈拥护〉。「拥有」表示领有，建议不能被领有，表示支持应说「拥护他的建议」。"}, {"text": "我拥有了一声巨响。", "explanation": "这里应该用〈听见〉。「拥有」表示领有，声音不能被领有，应说「听见一声巨响」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥有", "is_correct": true, "explanation": "「只有他一个人拥有」表示只有他拥有这些钥匙，句子通顺。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」与钥匙没有关系，「只有他一个人唱这家店的钥匙」讲不通。"}, {"text": "切", "is_correct": false, "explanation": "搭配：「切」不能接钥匙作宾语，「切这家店的钥匙」不成立。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」不能接钥匙作宾语，「煮这家店的钥匙」不成立。"}], "explanations": {"拥有": "「只有他一个人拥有」表示只有他拥有这些钥匙，句子通顺。", "唱": "语义：「唱」与钥匙没有关系，「只有他一个人唱这家店的钥匙」讲不通。", "切": "搭配：「切」不能接钥匙作宾语，「切这家店的钥匙」不成立。", "煮": "搭配：「煮」不能接钥匙作宾语，「煮这家店的钥匙」不成立。"}, "sentence_index": 6, "correct_answer": "拥有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们拥有了一次讨论。", "explanation": "这里应该用〈进行〉。讨论是活动，不能被领有，应说「进行一次讨论」。"}, {"text": "她拥有两场比赛。", "explanation": "这里应该用〈参加〉。比赛是活动，不能被领有，应说「参加两场比赛」。"}, {"text": "车站拥有了一件事。", "explanation": "这里应该用〈发生〉。事件是发生的，不能被车站领有，应说「车站发生了一件事」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很拥有两本词典。", "corrected_sentence": "我拥有两本词典。", "error_description": "错误在于「拥有」前多加了程度副词「很」。「很」不能修饰动词「拥有」，正确说法是「我拥有两本词典」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她拥有两只电脑。", "corrected_sentence": "她拥有两台电脑。", "error_description": "错误在于量词。「电脑」应用量词「台」，「只」多用于动物、成对的物件等，不能修饰「电脑」。正确说法是「她拥有两台电脑」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
