INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21198, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房子外面的小院子。", "primary_collocate": null, "pronunciation": "tíng yuàn", "ipa": "tʰiŋ˧˥ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我家的庭院里有一棵大树。", "target_word": "庭院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，庭院里开满了花。", "target_word": "庭院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天早上在庭院里浇花。", "target_word": "庭院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座庭院不大，但是很干净。", "target_word": "庭院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在庭院里玩球。", "target_word": "庭院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "庭院的门口放着两盆红花。", "target_word": "庭院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我们坐在庭院里吃饭。", "target_word": "庭院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的房子有一个漂亮的庭院。", "target_word": "庭院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，庭院里很安静。", "target_word": "庭院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "庭院中间有一张石桌。", "target_word": "庭院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "庭院：房子外面的小院子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8c9982-2261-4a26-bafc-a41b87d5771d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21198, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "庭院", "is_correct": true, "explanation": "庭院 tíng yuàn 指房子外面的小院子，是本义。"}, {"text": "情愿", "is_correct": false, "explanation": "情愿 qíng yuàn 与 tíng yuàn 的声母不同（q 与 t），意思是心甘情愿。"}, {"text": "停演", "is_correct": false, "explanation": "停演 tíng yǎn 第二个音节韵头不同（yǎn 是 i，yuàn 是 ü），声调也不同，意思是停止演出。"}, {"text": "挺远", "is_correct": false, "explanation": "挺远 tǐng yuǎn 两个音节的声调都与 tíng yuàn 不同，意思是相当远。"}], "explanations": {"庭院": "庭院 tíng yuàn 指房子外面的小院子，是本义。", "情愿": "情愿 qíng yuàn 与 tíng yuàn 的声母不同（q 与 t），意思是心甘情愿。", "停演": "停演 tíng yǎn 第二个音节韵头不同（yǎn 是 i，yuàn 是 ü），声调也不同，意思是停止演出。", "挺远": "挺远 tǐng yuǎn 两个音节的声调都与 tíng yuàn 不同，意思是相当远。"}, "sentence_index": null, "correct_answer": "庭院"}, "level_3": {"options": [{"text": "庭院", "is_correct": true, "explanation": "庭院指房子外面的小院子，可以种树，与「一棵大树」相合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房里放不下一棵大树，与后面的「一棵大树」相冲突。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包装不下一棵大树，句意不通。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：「我家的」一般修饰家中之物，地铁不是私人财产，不能说「我家的地铁」。"}], "explanations": {"庭院": "庭院指房子外面的小院子，可以种树，与「一棵大树」相合。", "厨房": "语义：厨房里放不下一棵大树，与后面的「一棵大树」相冲突。", "书包": "语义：书包装不下一棵大树，句意不通。", "地铁": "搭配：「我家的」一般修饰家中之物，地铁不是私人财产，不能说「我家的地铁」。"}, "sentence_index": 0, "correct_answer": "庭院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个庭院有两间卧室，交通方便。", "explanation": "这里应该用〈公寓〉。庭院是房子外面的小院子，不是住房，不能说它有卧室。"}, {"text": "爸爸每天开着庭院去上班。", "explanation": "这里应该用〈汽车〉。庭院是房子外面的小院子，不是交通工具，不能开着去上班。"}, {"text": "我家的庭院是一座三层的楼房，有电梯。", "explanation": "这里应该用〈住宅〉。庭院是露天的小院子，不是楼房，不能说它有三层、有电梯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庭院", "is_correct": true, "explanation": "庭院是露天的院子，可以在里面吃饭，与「坐在…里吃饭」相合。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：人不能坐在口袋里吃饭，句意不通。"}, {"text": "衣柜", "is_correct": false, "explanation": "语义：人不能坐进衣柜里吃饭，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：「坐在…里」要求可以容纳人的场所，窗户不能作为「里」的场所。"}], "explanations": {"庭院": "庭院是露天的院子，可以在里面吃饭，与「坐在…里吃饭」相合。", "口袋": "语义：人不能坐在口袋里吃饭，句意不通。", "衣柜": "语义：人不能坐进衣柜里吃饭，句意不通。", "窗户": "搭配：「坐在…里」要求可以容纳人的场所，窗户不能作为「里」的场所。"}, "sentence_index": 6, "correct_answer": "庭院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妈妈在庭院上班，她是医生。", "explanation": "这里应该用〈医院〉。庭院不是工作场所，医生上班的地方是医院。"}, {"text": "妈妈每天早上去庭院买菜。", "explanation": "这里应该用〈菜市场〉。庭院是房子外面的院子，不是买菜的地方。"}, {"text": "他每天坐火车去庭院接人。", "explanation": "这里应该用〈车站〉。庭院不是交通场所，火车不能开到庭院去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家有一棵小庭院。", "corrected_sentence": "我们家有一座小庭院。", "error_description": "错误形式是「一棵小庭院」，正确形式是「一座小庭院」。「棵」用于树木，庭院应该用「座」或「个」计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末孩子们在庭院上玩耍。", "corrected_sentence": "周末孩子们在庭院里玩耍。", "error_description": "错误形式是「庭院上玩耍」，正确形式是「庭院里玩耍」。庭院是围合的院落，表示在其内部应用「里」；「上」多用于开阔的平面场所，如「草地上」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆解", "is_correct": true, "explanation": "正确：“拆解”与“构建”相反，指把整体拆开。"}, {"text": "维护", "is_correct": false, "explanation": "与“构建”没有反义关系，“维护”指保持完好。"}, {"text": "设计", "is_correct": false, "explanation": "与“构建”没有反义关系，“设计”指事先规划。"}, {"text": "观察", "is_correct": false, "explanation": "与“构建”没有反义关系，“观察”指仔细地看。"}], "correct_answer": "拆解", "explanations": {"拆解": "正确：“拆解”与“构建”相反，指把整体拆开。", "维护": "与“构建”没有反义关系，“维护”指保持完好。", "设计": "与“构建”没有反义关系，“设计”指事先规划。", "观察": "与“构建”没有反义关系，“观察”指仔细地看。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆毁", "is_correct": true, "explanation": "正确：“拆毁”与“构建”相反，指把建成的东西拆掉。"}, {"text": "检查", "is_correct": false, "explanation": "与“构建”没有反义关系，“检查”指仔细查看是否有问题。"}, {"text": "记录", "is_correct": false, "explanation": "与“构建”没有反义关系，“记录”指把信息写下来。"}, {"text": "研究", "is_correct": false, "explanation": "与“构建”没有反义关系，“研究”指深入探讨。"}], "correct_answer": "拆毁", "explanations": {"拆毁": "正确：“拆毁”与“构建”相反，指把建成的东西拆掉。", "检查": "与“构建”没有反义关系，“检查”指仔细查看是否有问题。", "记录": "与“构建”没有反义关系，“记录”指把信息写下来。", "研究": "与“构建”没有反义关系，“研究”指深入探讨。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西搭在一起做出一个新的。", "primary_collocate": null, "pronunciation": "gòu jiàn", "ipa": "kou˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "公司想构建一个新网站。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在构建新的学习平台。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起构建了一个小木屋。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用积木构建了一座城堡。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮我们构建知识体系。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司花了三年构建新系统。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间的信任要慢慢构建。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府计划构建一个新的交通网。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师先构建了这个软件的框架。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在游戏里构建了一座城市。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "构建了", "label": "体标"}, {"form": "构建着", "label": "体标"}, {"form": "構建", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把各部分组合起来，建成新的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d81d48-6f38-42b1-91d4-5cab678d6582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：网站是无形的，不能被“吃”。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆等交通工具，不说“驾驶网站”。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”用于动物，不说“喂养网站”。"}, {"text": "构建", "is_correct": true, "explanation": "正确：“构建一个新网站”指搭建，与语境相符。"}], "explanations": {"吃": "语义：网站是无形的，不能被“吃”。", "驾驶": "搭配：“驾驶”的对象是车辆等交通工具，不说“驾驶网站”。", "喂养": "搭配：“喂养”用于动物，不说“喂养网站”。", "构建": "正确：“构建一个新网站”指搭建，与语境相符。"}, "sentence_index": 0, "correct_answer": "构建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服务员构建了一杯咖啡。", "explanation": "这里应该用〈冲〉或〈泡〉。咖啡是冲泡出来的，不说“构建”。"}, {"text": "妈妈构建了一个蛋糕。", "explanation": "这里应该用〈制作〉。蛋糕是做出来的食物，不说“构建”。"}, {"text": "他构建了一首诗。", "explanation": "这里应该用〈写〉。诗是写出来的，不说“构建”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烤", "is_correct": false, "explanation": "语义：信任是抽象的感情，不能被“烤”。"}, {"text": "扛", "is_correct": false, "explanation": "搭配：“扛”多用于重物，不与“信任”搭配。"}, {"text": "冻", "is_correct": false, "explanation": "语义：“冻”指温度降低使物体变硬，不用于抽象的信任。"}, {"text": "构建", "is_correct": true, "explanation": "正确：“慢慢构建信任”指逐步建立，与语境相符。"}], "explanations": {"烤": "语义：信任是抽象的感情，不能被“烤”。", "扛": "搭配：“扛”多用于重物，不与“信任”搭配。", "冻": "语义：“冻”指温度降低使物体变硬，不用于抽象的信任。", "构建": "正确：“慢慢构建信任”指逐步建立，与语境相符。"}, "sentence_index": 6, "correct_answer": "构建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民构建了一片小麦。", "explanation": "这里应该用〈种植〉。农作物要说“种植”，不说“构建”。"}, {"text": "陶工构建了一个花瓶。", "explanation": "这里应该用〈烧制〉。陶瓷器皿是烧制出来的，不说“构建”。"}, {"text": "画家构建了一幅画。", "explanation": "这里应该用〈画〉。画是画出来的，“构建”多用于较大的系统或整体结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把新系统构建了好。", "corrected_sentence": "他们把新系统构建好了。", "error_description": "补语位置错误：结果补语“好”应紧接动词“构建”，句末再用“了”，应说“构建好了”，不能说“构建了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们明天构建了一个小网站。", "corrected_sentence": "他们明天构建一个小网站。", "error_description": "体标错误：“了”表示已经完成，不能与表示将来的“明天”同用，应说“明天构建一个小网站”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
