INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21206, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物理是研究东西为什么动、为什么热、为什么掉下来的学问。", "primary_collocate": null, "pronunciation": "wù lǐ", "ipa": "u⁵¹ li²¹⁴", "syllable_count": 2, "sentences": [{"text": "我今天下午有物理课。", "target_word": "物理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他最喜欢的课是物理。", "target_word": "物理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "物理老师给我们做了一个实验。", "target_word": "物理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "物理很难，但是很有意思。", "target_word": "物理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的物理和数学都很好。", "target_word": "物理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "苹果为什么会掉下来？这是物理问题。", "target_word": "物理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟长大后想学物理。", "target_word": "物理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们用物理知识解释了彩虹。", "target_word": "物理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本物理书里有很多图。", "target_word": "物理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考试前，他复习了物理。", "target_word": "物理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：研究物质、运动、热、力等现象的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083b86a6-9f7b-4d1f-ab6f-174ff48943e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21206, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物理", "is_correct": true, "explanation": "正确：物理是研究物质、运动、热、力等现象的学科。"}, {"text": "无理", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，“无理”意思是没有道理。"}, {"text": "物力", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，“物力”意思是物资和人力。"}, {"text": "屋里", "is_correct": false, "explanation": "wù（第四声）与 wū（第一声）声调不同，“屋里”意思是房间里面。"}], "explanations": {"物理": "正确：物理是研究物质、运动、热、力等现象的学科。", "无理": "wù（第四声）与 wú（第二声）声调不同，“无理”意思是没有道理。", "物力": "lǐ（第三声）与 lì（第四声）声调不同，“物力”意思是物资和人力。", "屋里": "wù（第四声）与 wū（第一声）声调不同，“屋里”意思是房间里面。"}, "sentence_index": null, "correct_answer": "物理"}, "level_3": {"options": [{"text": "物理", "is_correct": true, "explanation": "正确：物理是一门学科，可以作“课”的内容，符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不是学科，不能作“课”的名称。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不是课程，句子不通。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“有……课”要接学科名称，“眼镜”不能与“课”搭配。"}], "explanations": {"物理": "正确：物理是一门学科，可以作“课”的内容，符合语境。", "冰箱": "语义：“冰箱”是家用电器，不是学科，不能作“课”的名称。", "感冒": "语义：“感冒”是疾病，不是课程，句子不通。", "眼镜": "搭配：“有……课”要接学科名称，“眼镜”不能与“课”搭配。"}, "sentence_index": 0, "correct_answer": "物理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天学了一把物理。", "explanation": "这里应该用〈门〉。学科用“门”作量词，不用“把”。"}, {"text": "他的物理很好，每天能跑十公里。", "explanation": "此句把学科“物理”用来指身体能力，词义不符；这里应该用〈体力〉。"}, {"text": "这个学期，我学了三只物理。", "explanation": "这里应该用〈门〉。学科用“门”作量词，“只”用于动物，不能用于学科。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物理", "is_correct": true, "explanation": "正确：“学”后接学科名称，“物理”符合语境。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不是可以学习的对象，“想学空气”说不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不是可以学习的学科或技能，句子不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“学”的对象应是学科或技能，不能与“天空”搭配。"}], "explanations": {"物理": "正确：“学”后接学科名称，“物理”符合语境。", "空气": "语义：“空气”不是可以学习的对象，“想学空气”说不通。", "房子": "语义：“房子”不是可以学习的学科或技能，句子不通。", "天空": "搭配：“学”的对象应是学科或技能，不能与“天空”搭配。"}, "sentence_index": 6, "correct_answer": "物理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试前，他把物理吃了。", "explanation": "语义：“物理”是学科名称，不能作“吃”的对象，应说“复习物理”。"}, {"text": "我昨天在超市买了三斤物理。", "explanation": "语义：“物理”是学科，不是商品，不能用“斤”计量买卖，这里的用法不成立。"}, {"text": "这个物理很重，我们搬不动。", "explanation": "语义：“物理”不是具体的物体，不能说“重”和“搬”，这里的用法不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的弟弟喜欢物理们。", "corrected_sentence": "我的弟弟喜欢物理。", "error_description": "“物理”是不可数的学科名称，不能加“们”表示复数。错误形式“物理们”，正确形式为“物理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹很喜欢物理过。", "corrected_sentence": "我妹妹很喜欢物理。", "error_description": "“物理”是名词，后面不能加体标“过”。错误形式“喜欢物理过”，正确形式为“喜欢物理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
