INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21208, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西分成一层一层的。", "primary_collocate": null, "pronunciation": "fēn céng", "ipa": "fən˥ tsʰəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "孩子把彩色的糖果分层摆进玻璃瓶里，很好看。", "target_word": "分层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做千层糕时，要把米粉和红糖分层放好。", "target_word": "分层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把土和沙子分层放进花盆里。", "target_word": "分层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河底的泥沙常常自己分层，重的在下面。", "target_word": "分层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水和油放在一起，慢慢就会分层。", "target_word": "分层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把旧文件分层放进了抽屉里。", "target_word": "分层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子里的果汁和牛奶分层了，很好看。", "target_word": "分层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里的东西要分层放，才好找。", "target_word": "分层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅把蛋糕分层，一层奶油一层水果。", "target_word": "分层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗好的衣服要分层放进箱子里。", "target_word": "分层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分层了", "label": "完成体"}, {"form": "分层过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把东西或物质分成上下一层一层地放置或排列", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3242d957-0d44-43bf-84d5-365f64ae4fa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21208, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分层", "is_correct": true, "explanation": "分层：一层一层地摆放糖果，与“摆进玻璃瓶里”的句意相符。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”不表示摆放的方式，“装饰摆进”不成立。"}, {"text": "拍照", "is_correct": false, "explanation": "语义：“拍照”与把糖果摆进瓶里的动作不相容，句意不成立。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”不是摆放糖果的方式，句意不成立。"}], "explanations": {"分层": "分层：一层一层地摆放糖果，与“摆进玻璃瓶里”的句意相符。", "装饰": "搭配：“装饰”不表示摆放的方式，“装饰摆进”不成立。", "拍照": "语义：“拍照”与把糖果摆进瓶里的动作不相容，句意不成立。", "打扫": "语义：“打扫”不是摆放糖果的方式，句意不成立。"}, "sentence_index": 0, "correct_answer": "分层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要分层对错。", "explanation": "这里应该用〈区分〉。分层指把东西分成一层一层，不能用来分辨对错。"}, {"text": "工人把这根长木头分层成三段。", "explanation": "这里应该用〈分割〉。分层指把东西分成一层一层的，不能用来指把长木头切成几段。"}, {"text": "他们昨天分层了。", "explanation": "这里应该用〈分手〉。分层指东西分成层次，不能用于人际关系的分开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分层", "is_correct": true, "explanation": "分层：果汁和牛奶按密度分成上下层，“很好看”的语境成立。"}, {"text": "烧焦", "is_correct": false, "explanation": "语义：烧焦的果汁和牛奶不好看，与“很好看”的语境相矛盾。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”只能用于金属，不能用于果汁和牛奶。"}, {"text": "腐烂", "is_correct": false, "explanation": "语义：腐烂的果汁和牛奶不好看，与“很好看”的语境相矛盾。"}], "explanations": {"分层": "分层：果汁和牛奶按密度分成上下层，“很好看”的语境成立。", "烧焦": "语义：烧焦的果汁和牛奶不好看，与“很好看”的语境相矛盾。", "生锈": "搭配：“生锈”只能用于金属，不能用于果汁和牛奶。", "腐烂": "语义：腐烂的果汁和牛奶不好看，与“很好看”的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "分层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板把工作分层给我们。", "explanation": "这里应该用〈分配〉。分层指分成层次，不能用于分配任务。"}, {"text": "我们俩在这件事上有分层。", "explanation": "这里应该用〈分歧〉。分层指把东西分成一层一层的，不能用来表示意见不同。"}, {"text": "我们一起分层快乐。", "explanation": "这里应该用〈分享〉。快乐不能分层，只能分享。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把书架上的零食分层了摆好了。", "corrected_sentence": "他把书架上的零食分层摆好了。", "error_description": "了的位置错误：“分层”后面不应加“了”，整个动作的完成只用句末的一个“了”。应为“分层摆好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "衣服要分层了放好才整齐。", "corrected_sentence": "衣服要分层放好才整齐。", "error_description": "体标错误：助动词“要”之后的“分层”不能再接“了”，删去“了”即为“衣服要分层放好才整齐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
