INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "存放东西的地方，比如放粮食的屋子。", "primary_collocate": null, "pronunciation": "cāng", "ipa": "tsʰɑŋ˥", "syllable_count": 1, "sentences": [{"text": "爷爷的仓里放着很多农具。", "target_word": "仓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓里黑黑的，只有一扇小窗。", "target_word": "仓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走进仓里，找出一袋大米。", "target_word": "仓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "仓门锁着，我们进不去。", "target_word": "仓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个仓是用来放麦子的。", "target_word": "仓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天到了，仓里存满了过冬的粮食。", "target_word": "仓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫躲在仓里睡觉。", "target_word": "仓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把工具放回仓里。", "target_word": "仓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈从仓里拿出一袋面粉。", "target_word": "仓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "仓里太潮，粮食容易坏。", "target_word": "仓", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "粮仓", "label": "复合词"}, {"form": "仓库", "label": "复合词"}, {"form": "仓房", "label": "复合词"}, {"form": "倉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "仓：名词，存放东西的屋子，尤指放粮食的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9725243-d8db-4d53-b783-229059d8c9b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21212, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仓", "is_correct": true, "explanation": "仓（cāng）指存放粮食、货物的屋子，是正确答案。"}, {"text": "藏", "is_correct": false, "explanation": "cáng（第二声）与 cāng（第一声）声调不同，意思是隐藏。"}, {"text": "脏", "is_correct": false, "explanation": "zāng 与 cāng 声母不同（z 与 c），意思是脏污。"}, {"text": "参", "is_correct": false, "explanation": "cān 与 cāng 韵母不同（n 与 ng），意思是参加。"}], "explanations": {"仓": "仓（cāng）指存放粮食、货物的屋子，是正确答案。", "藏": "cáng（第二声）与 cāng（第一声）声调不同，意思是隐藏。", "脏": "zāng 与 cāng 声母不同（z 与 c），意思是脏污。", "参": "cān 与 cāng 韵母不同（n 与 ng），意思是参加。"}, "sentence_index": null, "correct_answer": "仓"}, "level_3": {"options": [{"text": "仓", "is_correct": true, "explanation": "正确：“仓”指存放农具等东西的屋子，与“放着很多农具”相合。"}, {"text": "杯", "is_correct": false, "explanation": "语义：杯子太小，装不下“很多农具”。"}, {"text": "缸", "is_correct": false, "explanation": "搭配：缸多用来盛水或腌菜，不说“缸里放着农具”。"}, {"text": "碗", "is_correct": false, "explanation": "语义：碗的容量太小，放不下“很多农具”。"}], "explanations": {"仓": "正确：“仓”指存放农具等东西的屋子，与“放着很多农具”相合。", "杯": "语义：杯子太小，装不下“很多农具”。", "缸": "搭配：缸多用来盛水或腌菜，不说“缸里放着农具”。", "碗": "语义：碗的容量太小，放不下“很多农具”。"}, "sentence_index": 0, "correct_answer": "仓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天在仓里洗澡。", "explanation": "这里应该用〈浴室〉。仓指存放东西的屋子，不是洗澡的地方。"}, {"text": "老师在仓里给学生上数学课。", "explanation": "这里应该用〈教室〉。仓指存放东西的屋子，不能用来上课。"}, {"text": "爸爸开着仓去上班。", "explanation": "这里应该用〈汽车〉。仓是存放东西的屋子，不能开着去上班，开车要说汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21212, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "仓", "is_correct": true, "explanation": "仓（cāng）指存放粮食、货物的屋子，是正确答案。"}, {"text": "康", "is_correct": false, "explanation": "kāng 与 cāng 声母不同（k 与 c），意思是健康。"}, {"text": "昌", "is_correct": false, "explanation": "chāng 与 cāng 声母不同（ch 与 c），意思是昌盛。"}, {"text": "餐", "is_correct": false, "explanation": "cān 与 cāng 韵母不同（n 与 ng），意思是餐饮。"}], "explanations": {"仓": "仓（cāng）指存放粮食、货物的屋子，是正确答案。", "康": "kāng 与 cāng 声母不同（k 与 c），意思是健康。", "昌": "chāng 与 cāng 声母不同（ch 与 c），意思是昌盛。", "餐": "cān 与 cāng 韵母不同（n 与 ng），意思是餐饮。"}, "sentence_index": null, "correct_answer": "仓"}, "level_3": {"options": [{"text": "仓", "is_correct": true, "explanation": "正确：“仓”是存放东西的屋子，小猫躲在里面睡觉合情合理。"}, {"text": "水", "is_correct": false, "explanation": "语义：水里不能让小猫躲着睡觉。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：窗户不是可以躲进去的空间，不说“躲在窗户里”。"}, {"text": "肚子", "is_correct": false, "explanation": "语义：肚子是身体部位，小猫不可能躲进去睡觉。"}], "explanations": {"仓": "正确：“仓”是存放东西的屋子，小猫躲在里面睡觉合情合理。", "水": "语义：水里不能让小猫躲着睡觉。", "窗户": "搭配：窗户不是可以躲进去的空间，不说“躲在窗户里”。", "肚子": "语义：肚子是身体部位，小猫不可能躲进去睡觉。"}, "sentence_index": 6, "correct_answer": "仓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天给仓浇水。", "explanation": "这里应该用〈花〉。仓是存放东西的屋子，不能浇水；浇水的是植物。"}, {"text": "他早上去遛仓。", "explanation": "这里应该用〈狗〉。遛是牵着动物散步，仓不能遛。"}, {"text": "我最爱吃仓。", "explanation": "这里应该用〈米饭〉。仓是存放东西的屋子，不能吃，吃的是食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村口的里仓放着几袋粮食。", "corrected_sentence": "村口的仓里放着几袋粮食。", "error_description": "错误：“里仓”。正确：“仓里”。方位词“里”要紧跟在名词后面，说“仓里”，不能说“里仓”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村东头有一把旧仓。", "corrected_sentence": "村东头有一座旧仓。", "error_description": "错误：“一把旧仓”。正确：“一座旧仓”。“把”用于有柄的物件，仓是房屋，应该用“座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a697a941-5101-495e-80df-38764b7ec94d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
