INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21216, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "盖是放在东西上面的一个东西，比如锅盖。", "primary_collocate": null, "pronunciation": "gài", "ipa": "kai˥˩", "syllable_count": 1, "sentences": [{"text": "这个锅有一个大盖。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤好了，请把锅的盖打开。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子的盖掉在地上了。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个饭盒的盖坏了。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个红色的盖是我的。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个塑料箱的盖很大。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖太小，所以放不上去。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把汤锅的盖拿开了。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给锅配一个新盖。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水壶的盖是塑料做的。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个盖", "label": "量词"}, {"form": "盖子", "label": "复合"}, {"form": "蓋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "盖：放在锅、杯等东西上面的盖子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1bd4ef5-97b2-41c8-b5f8-10c80ead5322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21216, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盖", "is_correct": true, "explanation": "正确：盖 gài，指锅、杯等东西上面的盖子。"}, {"text": "怪", "is_correct": false, "explanation": "guài（第四声）比 gài 多一个介音 u，意思是奇怪。"}, {"text": "害", "is_correct": false, "explanation": "hài（第四声）与 gài 声母不同（h 与 g），意思是伤害。"}, {"text": "干", "is_correct": false, "explanation": "gàn（第四声）与 gài 韵母不同（an 与 ai），意思是做、干。"}], "explanations": {"盖": "正确：盖 gài，指锅、杯等东西上面的盖子。", "怪": "guài（第四声）比 gài 多一个介音 u，意思是奇怪。", "害": "hài（第四声）与 gài 声母不同（h 与 g），意思是伤害。", "干": "gàn（第四声）与 gài 韵母不同（an 与 ai），意思是做、干。"}, "sentence_index": null, "correct_answer": "盖"}, "level_3": {"options": [{"text": "盖", "is_correct": true, "explanation": "正确：“盖”指锅的盖子，“大盖”即较大的锅盖，符合语境。"}, {"text": "门", "is_correct": false, "explanation": "语义：锅上没有“门”这一部件，“大门”不能用来说锅的部件。"}, {"text": "窗", "is_correct": false, "explanation": "语义：锅身上没有“窗”，“有一个大窗”这种说法不成立。"}, {"text": "鼻子", "is_correct": false, "explanation": "语义：“鼻子”是人体部位，锅没有鼻子。"}], "explanations": {"盖": "正确：“盖”指锅的盖子，“大盖”即较大的锅盖，符合语境。", "门": "语义：锅上没有“门”这一部件，“大门”不能用来说锅的部件。", "窗": "语义：锅身上没有“窗”，“有一个大窗”这种说法不成立。", "鼻子": "语义：“鼻子”是人体部位，锅没有鼻子。"}, "sentence_index": 0, "correct_answer": "盖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的饭盒有一根盖，坏了。", "explanation": "量词错误：盖子应用量词“个”，“根”用于细长的东西，不能用来数饭盒的盖子。"}, {"text": "那个饭盒有一座盖，坏了。", "explanation": "量词错误：盖子应用量词“个”，“座”用于房屋、山等大型的东西，不能用来数饭盒的盖子。"}, {"text": "这个饭盒有一条盖，坏了。", "explanation": "量词错误：盖子应用量词“个”，“条”用于细长的东西，不能用来数饭盒的盖子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967dff1b-b05c-477d-a642-65fecbdc50c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21216, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "盖", "is_correct": true, "explanation": "正确：盖 gài，指锅、杯等东西上面的盖子。"}, {"text": "改", "is_correct": false, "explanation": "gǎi（第三声）与 gài（第四声）声调不同，意思是改变。"}, {"text": "带", "is_correct": false, "explanation": "dài（第四声）与 gài 声母不同（d 与 g），意思是带领或带子。"}, {"text": "告", "is_correct": false, "explanation": "gào（第四声）与 gài 韵母不同（ao 与 ai），意思是告诉。"}, {"text": "该", "is_correct": false, "explanation": "gāi（第一声）与 gài 只差声调，意思是应该。"}], "explanations": {"盖": "正确：盖 gài，指锅、杯等东西上面的盖子。", "改": "gǎi（第三声）与 gài（第四声）声调不同，意思是改变。", "带": "dài（第四声）与 gài 声母不同（d 与 g），意思是带领或带子。", "告": "gào（第四声）与 gài 韵母不同（ao 与 ai），意思是告诉。", "该": "gāi（第一声）与 gài 只差声调，意思是应该。"}, "sentence_index": null, "correct_answer": "盖"}, "level_3": {"options": [{"text": "盖", "is_correct": true, "explanation": "正确：“盖太小”指锅盖太小，所以放不到锅上，符合语境。"}, {"text": "山", "is_correct": false, "explanation": "语义：山本身很大，说“山太小”与常识矛盾，句子不通。"}, {"text": "天", "is_correct": false, "explanation": "语义：“天太小，所以放不上去”不符合常识，句子不通。"}, {"text": "嘴", "is_correct": false, "explanation": "语义：“嘴”是人体器官，“嘴太小，所以放不上去”说不通。"}], "explanations": {"盖": "正确：“盖太小”指锅盖太小，所以放不到锅上，符合语境。", "山": "语义：山本身很大，说“山太小”与常识矛盾，句子不通。", "天": "语义：“天太小，所以放不上去”不符合常识，句子不通。", "嘴": "语义：“嘴”是人体器官，“嘴太小，所以放不上去”说不通。"}, "sentence_index": 6, "correct_answer": "盖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的水壶有一颗盖，很小。", "explanation": "量词错误：盖子应用量词“个”，“颗”用于小而圆的颗粒状东西，不能用来数水壶的盖子。"}, {"text": "我买的篮子有一棵盖，很大。", "explanation": "量词错误：盖子应用量词“个”，“棵”用于树木、植物，不能用来数篮子的盖子。"}, {"text": "这个水壶有一扇盖，是塑料做的。", "explanation": "量词错误：盖子应用量词“个”，“扇”用于门、窗，不能用来数水壶的盖子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967dff1b-b05c-477d-a642-65fecbdc50c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那口大锅有两条盖。", "corrected_sentence": "那口大锅有两个盖。", "error_description": "量词错误：“盖”应用量词“个”，说“两个盖”；“条”用于细长的东西，不能用来数锅盖。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967dff1b-b05c-477d-a642-65fecbdc50c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我找到了两个杯子的盖们。", "corrected_sentence": "我找到了两个杯子的盖。", "error_description": "复数错误：“盖”是物件，不能加“们”，应为“两个杯子的盖”，不能说“盖们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967dff1b-b05c-477d-a642-65fecbdc50c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
