INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21218, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发展中的一个部分，就像你搭积木时，搭完一块再搭下一块。", "primary_collocate": null, "pronunciation": "jiē duàn", "ipa": "tɕjɛ˥ twan˥˩", "syllable_count": 2, "sentences": [{"text": "学习汉语有不同的阶段。", "target_word": "阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作已经到了最后阶段。", "target_word": "阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在这个阶段需要多睡觉。", "target_word": "阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先完成第一阶段的任务。", "target_word": "阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学阶段，他的成绩很好。", "target_word": "阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个阶段的考试比上个阶段难。", "target_word": "阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛进入了最重要的阶段。", "target_word": "阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第二阶段从下个月开始。", "target_word": "阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他现在处在学习的新阶段。", "target_word": "阶段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的建造分为三个阶段。", "target_word": "阶段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "階段", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情发展过程中的一个部分或时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662c7823-51e1-46b7-b4e3-759c04a652e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阶段", "is_correct": true, "explanation": "“阶段”指事情发展中的一个部分，学习汉语有不同的阶段，填入后句意通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，与学习进程的不同部分无关，“不同的颜色”不能用来说学习。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”指居住或工作的空间，不能指学习的时期。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”是穿在脚上的东西，“学习汉语有不同的鞋子”说不通。"}], "explanations": {"阶段": "“阶段”指事情发展中的一个部分，学习汉语有不同的阶段，填入后句意通顺。", "颜色": "语义：“颜色”指色彩，与学习进程的不同部分无关，“不同的颜色”不能用来说学习。", "房间": "语义：“房间”指居住或工作的空间，不能指学习的时期。", "鞋子": "语义：“鞋子”是穿在脚上的东西，“学习汉语有不同的鞋子”说不通。"}, "sentence_index": 0, "correct_answer": "阶段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的数学阶段是九十分。", "explanation": "这里应该用〈成绩〉。“阶段”指事情发展中的一段时期，不能用来表示分数，考试的分数要说“成绩”。"}, {"text": "我们完成了一场阶段的任务。", "explanation": "量词错误：“阶段”应用量词“个”，“场”用于比赛、演出等，不能用于阶段。"}, {"text": "这张票的阶段是明天。", "explanation": "这里应该用〈日期〉。“阶段”指事情的一部分，表示具体某一天要用“日期”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阶段", "is_correct": true, "explanation": "“阶段”指事情发展中的一个部分，比赛进入了最重要的阶段，填入后句意通顺。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”是音乐作品，比赛不能“进入”歌曲，句子说的是比赛的发展部分。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指气候状况，不是比赛发展的一部分，“最重要的天气”没有意义。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“进入”不能与“衣服”搭配，比赛进入的是发展的阶段，不是衣物。"}], "explanations": {"阶段": "“阶段”指事情发展中的一个部分，比赛进入了最重要的阶段，填入后句意通顺。", "歌曲": "语义：“歌曲”是音乐作品，比赛不能“进入”歌曲，句子说的是比赛的发展部分。", "天气": "语义：“天气”指气候状况，不是比赛发展的一部分，“最重要的天气”没有意义。", "衣服": "搭配：“进入”不能与“衣服”搭配，比赛进入的是发展的阶段，不是衣物。"}, "sentence_index": 6, "correct_answer": "阶段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个楼梯有十二个阶段。", "explanation": "这里应该用〈台阶〉。楼梯的每一级要用“台阶”，“阶段”指事情发展的时期。"}, {"text": "这位运动员的阶段在全国排第一。", "explanation": "这里应该用〈等级〉。“等级”用于排名和高低，“阶段”指事情发展的时期，不能用来排名。"}, {"text": "他的阶段是十八岁。", "explanation": "这里应该用〈年龄〉。“年龄”表示人的岁数，“阶段”不能用数字表示岁数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只阶段结束了，我们休息一下。", "corrected_sentence": "这个阶段结束了，我们休息一下。", "error_description": "量词错误：“阶段”应用量词“个”，写成“只”不对，“只”多用于动物或成对的部位。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛已经进入了第二的阶段。", "corrected_sentence": "比赛已经进入了第二阶段。", "error_description": "“的”位置错误：“第二”直接修饰“阶段”，中间不能加“的”，应说“第二阶段”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间断", "is_correct": true, "explanation": "“间断”与“连续”意义相反，指中间有停顿、不连贯。"}, {"text": "灿烂", "is_correct": false, "explanation": "与“连续”无关：“灿烂”形容光彩耀眼，不涉及是否中断。"}, {"text": "柔软", "is_correct": false, "explanation": "与“连续”无关：“柔软”形容质地松软，不是“连续”的反义。"}, {"text": "稳定", "is_correct": false, "explanation": "与“连续”无关：“稳定”指不动荡、不变化，不是“连续”的反义。"}], "correct_answer": "间断", "explanations": {"间断": "“间断”与“连续”意义相反，指中间有停顿、不连贯。", "灿烂": "与“连续”无关：“灿烂”形容光彩耀眼，不涉及是否中断。", "柔软": "与“连续”无关：“柔软”形容质地松软，不是“连续”的反义。", "稳定": "与“连续”无关：“稳定”指不动荡、不变化，不是“连续”的反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间断", "is_correct": true, "explanation": "“间断”与“连续”意义相反，指中间有停顿、不连贯。"}, {"text": "严格", "is_correct": false, "explanation": "与“连续”无关：“严格”形容要求高、不宽松，不涉及是否中断。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“连续”无关：“陡峭”形容坡度大，不是“连续”的反义。"}, {"text": "悠闲", "is_correct": false, "explanation": "与“连续”无关：“悠闲”形容从容不忙，不表示有无中断。"}], "correct_answer": "间断", "explanations": {"间断": "“间断”与“连续”意义相反，指中间有停顿、不连贯。", "严格": "与“连续”无关：“严格”形容要求高、不宽松，不涉及是否中断。", "陡峭": "与“连续”无关：“陡峭”形容坡度大，不是“连续”的反义。", "悠闲": "与“连续”无关：“悠闲”形容从容不忙，不表示有无中断。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一个东西接着另一个东西，中间没有停。", "primary_collocate": null, "pronunciation": "lián xù", "ipa": "ljɛn˧˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "山路上连续有好几个大弯。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车窗外连续闪过一排路灯。", "target_word": "连续", "complexity_tier": "T3", "furigana": "chē chuāng wài lián xù shǎn guò yī pái lù dēng", "sentence_source": "generated"}, {"text": "这部电视剧连续播了二十集。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车连续经过三个小站。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路边连续出现了几家饭馆。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他连续说了十分钟，一直没停。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话连续响了五次，没人接。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天空中连续飞过几架飞机。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她连续吃了三个包子，还想吃。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鼓声连续响了很久。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "连续性", "label": "复合"}, {"form": "连续剧", "label": "复合"}, {"form": "連續", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个接着一个、中间不停", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f100bb76-d1fe-41e2-a9a4-3bd009c02759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连续", "is_correct": true, "explanation": "“连续”在此表示弯道一个接一个地出现，中间没有间断，与“好几个大弯”相符。"}, {"text": "笔直", "is_correct": false, "explanation": "语义：“笔直”指没有弯曲，与“好几个大弯”直接矛盾。"}, {"text": "平坦", "is_correct": false, "explanation": "语义：“平坦”指路面没有起伏，与“大弯”的描述矛盾。"}, {"text": "宽阔", "is_correct": false, "explanation": "搭配：“宽阔”多修饰路面或场地的宽度，不用来说明弯道的数量和出现方式。"}], "explanations": {"连续": "“连续”在此表示弯道一个接一个地出现，中间没有间断，与“好几个大弯”相符。", "笔直": "语义：“笔直”指没有弯曲，与“好几个大弯”直接矛盾。", "平坦": "语义：“平坦”指路面没有起伏，与“大弯”的描述矛盾。", "宽阔": "搭配：“宽阔”多修饰路面或场地的宽度，不用来说明弯道的数量和出现方式。"}, "sentence_index": 0, "correct_answer": "连续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条铁路把两个站点连续起来了。", "explanation": "这里应该用〈连接〉。连续只说事物接续、不中断，不能用来说把两处接在一起。"}, {"text": "两根电线杆之间连续着十米的距离。", "explanation": "这里应该用〈间隔〉。连续说事物接着出现、中间不停，不能用来说两物之间相隔的距离；两物之间相隔多远要用〈间隔〉。"}, {"text": "铁路在这里连续着，一条通往北京，一条通往上海。", "explanation": "这里应该用〈分岔〉。连续说事物接着出现、中间不停，铁路在此分成两条要用〈分岔〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连续", "is_correct": true, "explanation": "“连续”在此表示电话一次接一次地响，中间没有停，与“响了五次”相符。"}, {"text": "静默", "is_correct": false, "explanation": "语义：“静默”指没有声音，与“响了五次”直接矛盾。"}, {"text": "懒散", "is_correct": false, "explanation": "搭配：“懒散”形容人的做事态度，不能修饰电话的响声。"}, {"text": "迟缓", "is_correct": false, "explanation": "搭配：“迟缓”形容动作或反应慢，不用来说电话响的方式。"}], "explanations": {"连续": "“连续”在此表示电话一次接一次地响，中间没有停，与“响了五次”相符。", "静默": "语义：“静默”指没有声音，与“响了五次”直接矛盾。", "懒散": "搭配：“懒散”形容人的做事态度，不能修饰电话的响声。", "迟缓": "搭配：“迟缓”形容动作或反应慢，不用来说电话响的方式。"}, "sentence_index": 6, "correct_answer": "连续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鼓声连续响了一下，很快就停了。", "explanation": "这里应该用〈短暂〉。连续表示中间不停地接着出现，只响一下就停要用〈短暂〉。"}, {"text": "鼓声和舞步很连续，大家都跟着跳。", "explanation": "这里应该用〈联系〉。连续不能表示事物之间有关系；鼓声与舞步相关要用〈联系〉。"}, {"text": "这面鼓很连续，很好听。", "explanation": "这里应该用〈悦耳〉。连续说的是不中断的次序，不能用来评价鼓声好听与否；评价声音要用〈悦耳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车队连续了三个收费站。", "corrected_sentence": "车队连续经过了三个收费站。", "error_description": "错误在“连续”之后漏了动词“经过”。连续是形容词，不能直接带宾语，应说“连续经过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "连续了三个晚上排练都很辛苦。", "corrected_sentence": "连续三个晚上排练都很辛苦。", "error_description": "体标错误：“连续”在这里直接修饰时间数量“三个晚上”，作状语时不能带“了”，应删去“了”，说“连续三个晚上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
