INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中间的那一层。", "primary_collocate": null, "pronunciation": "zhōng céng", "ipa": "ʈʂʊŋ˥ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "书架的中层放满了小说。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱的中层有牛奶和鸡蛋。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛋糕的中层夹着很多水果。", "target_word": "中层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座塔的中层有一家小店。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林的中层住着很多小鸟。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把杯子放在柜子的中层。", "target_word": "中层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的上层很热，中层有点凉，下层最冷。", "target_word": "中层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子分三层，糖放在中层。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山的中层常常有云。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "床是上下三层的，我睡中层。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "中層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体上中下三层里中间的一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f100bb76-d1fe-41e2-a9a4-3bd009c02759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中层", "is_correct": true, "explanation": "“中层”指书架中间的一层，可以放满书，与句意相符。"}, {"text": "把手", "is_correct": false, "explanation": "语义：把手不是能放书的空间，“放满了小说”说不通。"}, {"text": "脚轮", "is_correct": false, "explanation": "搭配：“放满”要求有可以容纳物品的空间，脚轮不能被放满。"}, {"text": "背板", "is_correct": false, "explanation": "语义：背板是书架后面的板子，不是可以放书的层，不能“放满了小说”。"}], "explanations": {"中层": "“中层”指书架中间的一层，可以放满书，与句意相符。", "把手": "语义：把手不是能放书的空间，“放满了小说”说不通。", "脚轮": "搭配：“放满”要求有可以容纳物品的空间，脚轮不能被放满。", "背板": "语义：背板是书架后面的板子，不是可以放书的层，不能“放满了小说”。"}, "sentence_index": 0, "correct_answer": "中层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我坐在教室的中层，前后都是同学。", "explanation": "这里应该用〈中间〉。中层指空间中的一层，不指教室里的座位；表示位置在中间要用〈中间〉。"}, {"text": "比赛进入中层了，选手都很紧张。", "explanation": "这里应该用〈中期〉。中层指空间中的一层或组织层级，不表示时间阶段，表示进程要用〈中期〉。"}, {"text": "她的女儿在中层读书，成绩很好。", "explanation": "这里应该用〈中学〉。中层指空间中的一层或层级，不指学校阶段；表示初中、高中要用〈中学〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中层", "is_correct": true, "explanation": "“中层”位于上层与下层之间，温度居中，所以“有点凉”，与句意相符。"}, {"text": "上层", "is_correct": false, "explanation": "语义：“上层”在句中已指热的那一层，“上层很热”与“上层有点凉”自相矛盾。"}, {"text": "底部", "is_correct": false, "explanation": "搭配：“底部”与句末的“下层”指同一位置，并列使用时句意重复且不通。"}, {"text": "顶部", "is_correct": false, "explanation": "语义：“顶部”与前文“上层很热”指同一位置，句意矛盾。"}], "explanations": {"中层": "“中层”位于上层与下层之间，温度居中，所以“有点凉”，与句意相符。", "上层": "语义：“上层”在句中已指热的那一层，“上层很热”与“上层有点凉”自相矛盾。", "底部": "搭配：“底部”与句末的“下层”指同一位置，并列使用时句意重复且不通。", "顶部": "语义：“顶部”与前文“上层很热”指同一位置，句意矛盾。"}, "sentence_index": 6, "correct_answer": "中层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本小说的中层很精彩，大家都很喜欢。", "explanation": "这里应该用〈中段〉。中层指物体中间的一层，不指作品的中间部分。"}, {"text": "他很中层，大家都喜欢和他玩。", "explanation": "这里应该用〈随和〉。中层是名词，不能用来形容人的性格。"}, {"text": "他的中层很疼，可能是胃不舒服。", "explanation": "这里应该用〈腹部〉。中层指物体中间的一层，不指人体部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个盒子的一只中层放着糖果。", "corrected_sentence": "这个盒子的中层放着糖果。", "error_description": "量词错误：“中层”指盒子里的一层，不能用量词“只”。“只”多用于动物或成对物件中的单个，此处应去掉“一只”，直接说“这个盒子的中层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冰箱中层地饮料都很凉。", "corrected_sentence": "冰箱中层的饮料都很凉。", "error_description": "错误在“的”与“地”：“中层”修饰名词“饮料”，应用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
