INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个小地方或者一块地方。", "primary_collocate": null, "pronunciation": "qū", "ipa": "tɕʰy˥", "syllable_count": 1, "sentences": [{"text": "这个区是孩子玩的地方。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家不要进左边那个区。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里分成三个区。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果在哪个区？我找不到。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面那个区正在修路。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在后面的那个区。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区只有老人可以进。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书放在另一个区了。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你到第二区排队。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左边这个区有很多树。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "区域", "label": "复合"}, {"form": "區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "划分出来的一小块地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c34999df-c2a8-41e6-84de-552383229488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21224, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "区", "is_correct": true, "explanation": "区读 qū（第一声），指一小块划分出来的地方。"}, {"text": "去", "is_correct": false, "explanation": "qù（第四声）与 qū（第一声）声调不同，意思是前往。"}, {"text": "居", "is_correct": false, "explanation": "jū 与 qū 声母不同（j 与 q），意思是居住。"}, {"text": "秋", "is_correct": false, "explanation": "qiū 比 qū 多一个 i 介音，意思是秋天。"}, {"text": "娶", "is_correct": false, "explanation": "qǔ（第三声）与 qū（第一声）声调不同，意思是娶妻。"}], "explanations": {"区": "区读 qū（第一声），指一小块划分出来的地方。", "去": "qù（第四声）与 qū（第一声）声调不同，意思是前往。", "居": "jū 与 qū 声母不同（j 与 q），意思是居住。", "秋": "qiū 比 qū 多一个 i 介音，意思是秋天。", "娶": "qǔ（第三声）与 qū（第一声）声调不同，意思是娶妻。"}, "sentence_index": null, "correct_answer": "区"}, "level_3": {"options": [{"text": "区", "is_correct": true, "explanation": "区指一小块划分出来的地方，“这个区是孩子玩的地方”通顺，符合语境。"}, {"text": "票", "is_correct": false, "explanation": "语义：票是凭证，不是孩子玩耍的地方。"}, {"text": "汤", "is_correct": false, "explanation": "语义：汤是食物，与“孩子玩的地方”不相符。"}, {"text": "课", "is_correct": false, "explanation": "搭配：“课”指课程，不能作为“玩的地方”的中心语，两者搭配不成立。"}], "explanations": {"区": "区指一小块划分出来的地方，“这个区是孩子玩的地方”通顺，符合语境。", "票": "语义：票是凭证，不是孩子玩耍的地方。", "汤": "语义：汤是食物，与“孩子玩的地方”不相符。", "课": "搭配：“课”指课程，不能作为“玩的地方”的中心语，两者搭配不成立。"}, "sentence_index": 0, "correct_answer": "区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最擅长的区是英语。", "explanation": "这里的“区”被用成了学科领域的意思。区指一小块地方，不指擅长的学科，这里应说〈领域〉。"}, {"text": "这个区是一个国家，有自己的国王。", "explanation": "这里的“区”被用成了国家的意思。区只指一小块地方，不指独立的国家，这里应说〈国家〉。"}, {"text": "这个区是一个问句。", "explanation": "这里的“区”被用成了语法单位的意思。区指一小块地方，不是语法单位，这里应说〈句子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21224, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "区", "is_correct": true, "explanation": "区读 qū（第一声），指一小块划分出来的地方。"}, {"text": "取", "is_correct": false, "explanation": "qǔ（第三声）与 qū（第一声）声调不同，意思是拿取。"}, {"text": "趣", "is_correct": false, "explanation": "qù（第四声）与 qū（第一声）声调不同，意思是趣味。"}, {"text": "需", "is_correct": false, "explanation": "xū 与 qū 声母不同（x 与 q），意思是需要。"}, {"text": "渠", "is_correct": false, "explanation": "qú（第二声）与 qū（第一声）声调不同，意思是水渠。"}], "explanations": {"区": "区读 qū（第一声），指一小块划分出来的地方。", "取": "qǔ（第三声）与 qū（第一声）声调不同，意思是拿取。", "趣": "qù（第四声）与 qū（第一声）声调不同，意思是趣味。", "需": "xū 与 qū 声母不同（x 与 q），意思是需要。", "渠": "qú（第二声）与 qū（第一声）声调不同，意思是水渠。"}, "sentence_index": null, "correct_answer": "区"}, "level_3": {"options": [{"text": "区", "is_correct": true, "explanation": "区指一小块地方，“只有老人可以进”说明的正是这块地方，符合语境。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是照明用具，不能让人进入。"}, {"text": "书", "is_correct": false, "explanation": "语义：书是书籍，不是可以进入的地方。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“花”一般不指可以进入的场所，与“进”的搭配不成立。"}], "explanations": {"区": "区指一小块地方，“只有老人可以进”说明的正是这块地方，符合语境。", "灯": "语义：灯是照明用具，不能让人进入。", "书": "语义：书是书籍，不是可以进入的地方。", "花": "搭配：“花”一般不指可以进入的场所，与“进”的搭配不成立。"}, "sentence_index": 6, "correct_answer": "区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个区很甜。", "explanation": "这里的“区”被当成了食物。区指一小块地方，不指食品，这里应说〈食物〉。"}, {"text": "这个区又大又高，像一座楼。", "explanation": "这里应该用〈楼〉。区指一小块地方，不是建筑物，不能说“又大又高”。"}, {"text": "这个区是我的弟弟，很可爱。", "explanation": "这里应该用〈小朋友〉。区指一小块地方，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只区是给孩子玩的地方。", "corrected_sentence": "那个区是给孩子玩的地方。", "error_description": "“那只区”中量词用错：区应搭配量词“个”，“只”用于动物，不能计量区域。正确形式为“那个区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个里区有很多树。", "corrected_sentence": "这个区里有很多树。", "error_description": "“里区”语序错误：方位词“里”应放在处所名词之后，应说“区里”。正确形式为“这个区里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
