INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21226, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两个东西中间的一片地方。", "primary_collocate": null, "pronunciation": "guò dù dài", "ipa": "kuo˥˩ tu˥˩ tai˥˩", "syllable_count": 3, "sentences": [{"text": "操场和教学楼之间有一片过渡带，种着花。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子和马路中间留了一片过渡带。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块过渡带不大，只有三米宽。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个球场中间的过渡带，常常没有人。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的菜地和邻居家的地中间有一片过渡带。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把车停在两条路中间的过渡带上。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过渡带上长满了草，孩子们爱在这里玩。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河和公路之间的过渡带，是一片小树林。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跑进了两个院子中间的过渡带。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片过渡带把花园分成了两半。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "過渡帶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "过渡带：两个东西中间的一片空地或地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f100bb76-d1fe-41e2-a9a4-3bd009c02759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21226, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过渡带", "is_correct": true, "explanation": "正确：“过渡带”指操场与教学楼之间的一小片地方，“一片”可以搭配。"}, {"text": "教学楼", "is_correct": false, "explanation": "语义：教学楼是建筑，不能位于两者之间充当空地。"}, {"text": "围墙", "is_correct": false, "explanation": "语义：围墙是用来隔开的墙，不能种花，也不是两者之间的空地。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌不会种花，也不能位于操场与教学楼之间。"}], "explanations": {"过渡带": "正确：“过渡带”指操场与教学楼之间的一小片地方，“一片”可以搭配。", "教学楼": "语义：教学楼是建筑，不能位于两者之间充当空地。", "围墙": "语义：围墙是用来隔开的墙，不能种花，也不是两者之间的空地。", "课桌": "语义：课桌不会种花，也不能位于操场与教学楼之间。"}, "sentence_index": 0, "correct_answer": "过渡带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把过渡带放进了书包里。", "explanation": "这里应该用〈课本〉。过渡带是两物中间的一片地方，不能放进书包。"}, {"text": "妈妈给我买了一件新过渡带。", "explanation": "这里应该用〈衣服〉。过渡带是地方，不能买来穿。"}, {"text": "过渡带叫了一声，跑开了。", "explanation": "这里应该用〈小狗〉。过渡带是一片地方，不会叫，也不会跑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过渡带", "is_correct": true, "explanation": "正确：“过渡带”是地面，“上”表示在其表面，可以长草。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会长草，孩子们也不会在上面玩。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包上不会长满草，句意不通。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：表示场所用“里”，“教室上”不成立。"}], "explanations": {"过渡带": "正确：“过渡带”是地面，“上”表示在其表面，可以长草。", "冰箱": "语义：冰箱不会长草，孩子们也不会在上面玩。", "书包": "语义：书包上不会长满草，句意不通。", "教室": "搭配：表示场所用“里”，“教室上”不成立。"}, "sentence_index": 6, "correct_answer": "过渡带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把过渡带一口吃掉了。", "explanation": "这里应该用〈面包〉。过渡带指两物中间的一片地方，不是可以吃的东西。"}, {"text": "院子中间竖着一道过渡带。", "explanation": "这里应该用〈栅栏〉。“竖”用于栅栏这类立起的物体，过渡带是平铺的地带，不能竖起。"}, {"text": "客厅中间挂着过渡带。", "explanation": "“挂”用于画、布这类能悬挂的物件，过渡带是地带，不能挂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两栋宿舍楼中间有一棵过渡带，种着花草。", "corrected_sentence": "两栋宿舍楼中间有一片过渡带，种着花草。", "error_description": "量词错误：“过渡带”指一小片地方，应用“片”，不能用“棵”（“棵”用于树木）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小猫躲进了两块草地中间过渡带。", "corrected_sentence": "小猫躲进了两块草地中间的过渡带。", "error_description": "缺少“的”：“两块草地中间”修饰“过渡带”，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
