INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21228, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得可以用了。", "primary_collocate": null, "pronunciation": "shú huà", "ipa": "ʂu˧˥ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "农民用肥料熟化这块新地。", "target_word": "熟化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在熟化一批新肥料。", "target_word": "熟化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用几个月熟化了这些堆肥。", "target_word": "熟化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想先把这块荒地熟化，再种果树。", "target_word": "熟化", "complexity_tier": "T3", "furigana": "shú huà", "sentence_source": "generated"}, {"text": "要熟化土地，先把石头捡走。", "target_word": "熟化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把荒地熟化了三年，才种上菜。", "target_word": "熟化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些粪肥还没熟化，不能直接施在菜地里。", "target_word": "熟化", "complexity_tier": "T3", "furigana": "shú huà", "sentence_source": "generated"}, {"text": "这片荒滩要先熟化，才能种粮食。", "target_word": "熟化", "complexity_tier": "T3", "furigana": "shú huà", "sentence_source": "generated"}, {"text": "这家工厂专门熟化各种原料。", "target_word": "熟化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过熟化的肥料，可以放心用。", "target_word": "熟化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "熟化了", "label": "体标"}, {"form": "熟化过", "label": "体标"}], "register": "书面", "sense_fingerprint": "使东西变得成熟、可以用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f100bb76-d1fe-41e2-a9a4-3bd009c02759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21228, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "熟化", "is_correct": true, "explanation": "正确：熟化（shú huà），指使物质经处理变得可以用了。"}, {"text": "俗话", "is_correct": false, "explanation": "sú 与 shú 声母不同（s / sh），俗话指流传已久的通俗谚语。"}, {"text": "书画", "is_correct": false, "explanation": "shū（第一声）与 shú（第二声）声调不同，书画指书法和绘画。"}, {"text": "实话", "is_correct": false, "explanation": "shí 与 shú 韵母不同（i / u），实话指真实的话。"}, {"text": "赎回", "is_correct": false, "explanation": "第二个音节 huí（第二声）与 huà（第四声）韵母和声调都不同，赎回指用钱换回抵押的东西。"}], "explanations": {"熟化": "正确：熟化（shú huà），指使物质经处理变得可以用了。", "俗话": "sú 与 shú 声母不同（s / sh），俗话指流传已久的通俗谚语。", "书画": "shū（第一声）与 shú（第二声）声调不同，书画指书法和绘画。", "实话": "shí 与 shú 韵母不同（i / u），实话指真实的话。", "赎回": "第二个音节 huí（第二声）与 huà（第四声）韵母和声调都不同，赎回指用钱换回抵押的东西。"}, "sentence_index": null, "correct_answer": "熟化"}, "level_3": {"options": [{"text": "熟化", "is_correct": true, "explanation": "正确：“熟化”表示使土地经处理变得可以耕种，与“新地”搭配。"}, {"text": "测量", "is_correct": false, "explanation": "语义：肥料不能用来测量土地的面积。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫是清除脏物，与改良土地无关。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修针对房屋，不用于改良土地。"}], "explanations": {"熟化": "正确：“熟化”表示使土地经处理变得可以耕种，与“新地”搭配。", "测量": "语义：肥料不能用来测量土地的面积。", "打扫": "语义：打扫是清除脏物，与改良土地无关。", "装修": "语义：装修针对房屋，不用于改良土地。"}, "sentence_index": 0, "correct_answer": "熟化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们正在熟化新房子。", "explanation": "这里应该用〈装修〉。熟化指使物质经处理变得可用，房屋的内外改造要说装修。"}, {"text": "园丁熟化这棵苹果树。", "explanation": "这里应该用〈修剪〉。熟化用于物质的处理，给果树剪枝要说修剪。"}, {"text": "妈妈熟化了这件衣服。", "explanation": "这里应该用〈洗涤〉。熟化不用于衣物的清洗，清洗衣服要说洗涤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熟化", "is_correct": true, "explanation": "正确：“熟化”表示粪肥经处理后才能施用，与“还没”呼应。"}, {"text": "上色", "is_correct": false, "explanation": "语义：粪肥不需要上色，句意无法成立。"}, {"text": "乘坐", "is_correct": false, "explanation": "搭配：“乘坐”的对象是人或交通工具，不能用于粪肥。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：粪肥不是文字，无法翻译。"}], "explanations": {"熟化": "正确：“熟化”表示粪肥经处理后才能施用，与“还没”呼应。", "上色": "语义：粪肥不需要上色，句意无法成立。", "乘坐": "搭配：“乘坐”的对象是人或交通工具，不能用于粪肥。", "翻译": "语义：粪肥不是文字，无法翻译。"}, "sentence_index": 6, "correct_answer": "熟化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她经过熟化，性格变得沉稳了。", "explanation": "熟化只用于经加工使物质可用的过程，不用于描述人的成熟。"}, {"text": "这只鸡熟化得很快。", "explanation": "熟化用于物质，不用于描写动物的生长。"}, {"text": "这辆汽车熟化得很快。", "explanation": "熟化用于经加工使物质可用的过程，汽车机件的磨合不能说熟化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块荒地需要很熟化三年才能种。", "corrected_sentence": "这块荒地需要熟化三年才能种。", "error_description": "程度副词错误：“很”只修饰形容词或少数状态动词，不能修饰动作动词“熟化”，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这堆粪肥已经慢慢得熟化了。", "corrected_sentence": "这堆粪肥已经慢慢地熟化了。", "error_description": "助词错误：“慢慢”作状语修饰动词“熟化”，应该用“地”，不能用补语标志“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffe5fcd-3220-4fa9-aca2-11eae818e63e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
