INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21234, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "最高的那一层楼。", "primary_collocate": null, "pronunciation": "dǐng céng", "ipa": "tiŋ˨˩˦ tsʰəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我家住在顶层，夏天很热。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯可以直接到顶层。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼的顶层有一家咖啡店。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顶层的房子便宜，但是要爬很多楼梯。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨很大，顶层的房间会漏水。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在顶层的窗前看着远处。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场的顶层是电影院。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们爬了二十层，终于到了顶层。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从顶层往下看，车像小玩具。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顶层的邻居晚上总是很安静。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "頂層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "顶层：楼房最高的一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5767e3cf-4ef0-4302-87d2-21171c97c702') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "顶层", "is_correct": true, "explanation": "正确：顶层指楼房最高的一层，可以住人，与“夏天很热”的语境相符。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是电器，不是可以住人的地方，“我家住在空调”句意不通。"}, {"text": "邻居", "is_correct": false, "explanation": "配价：“住在”后要接处所，“邻居”是人，不能作为住的地方。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，不能作为住的地方，与句子的居住语境不符。"}], "explanations": {"顶层": "正确：顶层指楼房最高的一层，可以住人，与“夏天很热”的语境相符。", "空调": "语义：空调是电器，不是可以住人的地方，“我家住在空调”句意不通。", "邻居": "配价：“住在”后要接处所，“邻居”是人，不能作为住的地方。", "书桌": "语义：书桌是家具，不能作为住的地方，与句子的居住语境不符。"}, "sentence_index": 0, "correct_answer": "顶层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旗杆的顶层挂着一面红旗。", "explanation": "这里应该用〈顶端〉。顶层指楼房等分层建筑的最高一层，细长物体的最高处要说顶端。"}, {"text": "我们爬到了山的顶层，看到了日出。", "explanation": "这里应该用〈山顶〉。顶层只用于分层建筑，山的最高处要说山顶。"}, {"text": "这顶帽子的顶层绣着一朵小花。", "explanation": "这里应该用〈顶部〉。顶层指分层建筑的最高一层，帽子这类物品的上部要说顶部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '284e6d2a-0e7c-47c0-840f-71f44bcd6f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顶层", "is_correct": true, "explanation": "正确：顶层指最高一层，商场的顶层可以是电影院，句意通顺。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯是运送乘客的设备，不能是一家电影院，句意不通。"}, {"text": "收银台", "is_correct": false, "explanation": "语义：收银台是结账的地方，不是放映电影的场所，与“电影院”不符。"}, {"text": "顾客", "is_correct": false, "explanation": "配价：“是电影院”要求主语是场所，“顾客”是人，不能充当场所。"}], "explanations": {"顶层": "正确：顶层指最高一层，商场的顶层可以是电影院，句意通顺。", "电梯": "语义：电梯是运送乘客的设备，不能是一家电影院，句意不通。", "收银台": "语义：收银台是结账的地方，不是放映电影的场所，与“电影院”不符。", "顾客": "配价：“是电影院”要求主语是场所，“顾客”是人，不能充当场所。"}, "sentence_index": 6, "correct_answer": "顶层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼一共有二十个顶层。", "explanation": "这里应该用〈楼层〉。顶层只指一栋楼最高的那一层，不能用来计数整栋楼的层数。"}, {"text": "他躺在床上，看着房间的顶层。", "explanation": "这里应该用〈天花板〉。顶层指楼房的最高一层，屋内上方要说天花板。"}, {"text": "太阳就在我们的顶层。", "explanation": "这里应该用〈头顶〉。顶层只指分层建筑的最高一层，人或物的上方不说顶层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '284e6d2a-0e7c-47c0-840f-71f44bcd6f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家住在那栋楼的一只顶层。", "corrected_sentence": "我家住在那栋楼的顶层。", "error_description": "量词错误：顶层是一层楼，不能用〈只〉（动物及小件物品的量词）修饰，应删去“一只”，直接说“那栋楼的顶层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '284e6d2a-0e7c-47c0-840f-71f44bcd6f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一直坐电梯顶层。", "corrected_sentence": "我们一直坐电梯到顶层。", "error_description": "补语缺失：表示到达某处要用“到”引出，应说“坐电梯到顶层”，不能省去“到”说“坐电梯顶层”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '284e6d2a-0e7c-47c0-840f-71f44bcd6f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
