INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21242, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "深远影响的意思是，一件事情的结果在很久以后还会让别人感觉到。", "primary_collocate": null, "pronunciation": "shēn yuǎn yǐng xiǎng", "ipa": "ʂən˥ ɥɛn˨˩ iŋ˨˩ ɕjɑŋ˨˩", "syllable_count": 4, "sentences": [{"text": "小时候的经历对我有深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书对很多人有深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个好习惯会有深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的决定会产生深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件小事却有深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个发明对我们的生活有深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次旅行对她产生了深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个选择会有深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次地震带来了深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的话对我有深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深远的影响", "label": "变体"}], "register": "书面", "sense_fingerprint": "深远影响：一件事的结果过很久仍能被人感觉到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '315084ee-027b-4238-8c77-6176fc5e8545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深远影响", "is_correct": true, "explanation": "“小时候的经历对我有深远影响”：深远影响指事情在很久以后仍被感觉到的作用，符合句意。"}, {"text": "最近的变化", "is_correct": false, "explanation": "语义：“最近”与“小时候”时间相反，而且是变化，不是长期的影响。"}, {"text": "眼前的利益", "is_correct": false, "explanation": "语义：“眼前的利益”是当下的好处，与“小时候的经历”的长远作用不符。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“对……有”之后不接“体积”，“体积”不是经历能产生作用的对象。"}], "explanations": {"深远影响": "“小时候的经历对我有深远影响”：深远影响指事情在很久以后仍被感觉到的作用，符合句意。", "最近的变化": "语义：“最近”与“小时候”时间相反，而且是变化，不是长期的影响。", "眼前的利益": "语义：“眼前的利益”是当下的好处，与“小时候的经历”的长远作用不符。", "体积": "搭配：“对……有”之后不接“体积”，“体积”不是经历能产生作用的对象。"}, "sentence_index": 0, "correct_answer": "深远影响"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家终于得出了深远影响。", "explanation": "这里应该用〈结论〉。得出的是结论或答案，深远影响是结果，不能被得出。"}, {"text": "大会通过了深远影响。", "explanation": "这里应该用〈决议〉。通过的是决议或方案，深远影响不能被通过。"}, {"text": "他们制定了深远影响。", "explanation": "这里应该用〈计划〉。制定的是计划或规则，深远影响不能被制定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深远影响", "is_correct": true, "explanation": "“那次旅行对她产生了深远影响”：深远影响是长期才显现的作用，与“产生”搭配自然。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“产生”的对象是影响、变化，不能是身高。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“产生”的对象是影响、变化，不能是体重。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：早餐不能作为“产生”的结果。"}], "explanations": {"深远影响": "“那次旅行对她产生了深远影响”：深远影响是长期才显现的作用，与“产生”搭配自然。", "身高": "搭配：“产生”的对象是影响、变化，不能是身高。", "体重": "搭配：“产生”的对象是影响、变化，不能是体重。", "早餐": "搭配：早餐不能作为“产生”的结果。"}, "sentence_index": 6, "correct_answer": "深远影响"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆提供了深远影响。", "explanation": "这里应该用〈资料〉。提供的是资料或服务，深远影响不能被提供。"}, {"text": "他认真听取了深远影响。", "explanation": "这里应该用〈意见〉。听取的是意见或汇报，深远影响不能被听取。"}, {"text": "他打破了深远影响。", "explanation": "这里应该用〈纪录〉。打破的是纪录或沉默，深远影响不能被打破。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件小事对我深远影响。", "corrected_sentence": "这件小事对我有深远影响。", "error_description": "缺少动词“有”：“深远影响”前少了“有”，应说“这件小事对我有深远影响”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本电影对年轻人有深远影响。", "corrected_sentence": "这部电影对年轻人有深远影响。", "error_description": "量词错误：“电影”的量词是“部”，不能用“本”（“本”用于书）。错误在“本”，应说“这部电影对年轻人有深远影响”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
