INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21244, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种很多蔬菜和养动物的地方。", "primary_collocate": null, "pronunciation": "nóng chǎng", "ipa": "nʊŋ˧˥ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "爷爷在郊外有一个大农场。", "target_word": "农场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去农场看牛和羊。", "target_word": "农场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个农场种着很多蔬菜。", "target_word": "农场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在农场里喂小鸡。", "target_word": "农场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在农场工作了十年。", "target_word": "农场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场的早上很安静，空气也很好。", "target_word": "农场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们农场里的牛每天产很多牛奶。", "target_word": "农场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去过那个农场吗？", "target_word": "农场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场里有一条小河，旁边是果树。", "target_word": "农场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开城市，搬到农场生活。", "target_word": "农场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "农场主", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "种庄稼蔬菜、养牲畜的农业场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4208b8-fa3e-439a-94ca-4737d9934ac5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机是随身的通讯工具，不能说在郊外有一个大的“手机”。"}, {"text": "农场", "is_correct": true, "explanation": "“农场”指种植和养殖的场所，可以在郊外被拥有，与句意相符。"}, {"text": "地铁站", "is_correct": false, "explanation": "搭配：“有”后接的应是可以拥有的场地或建筑，“地铁站”是公共设施，不搭配。"}, {"text": "卫星", "is_correct": false, "explanation": "语义：卫星是天体或人造的太空器，不能在郊外被人拥有。"}], "explanations": {"手机": "语义：手机是随身的通讯工具，不能说在郊外有一个大的“手机”。", "农场": "“农场”指种植和养殖的场所，可以在郊外被拥有，与句意相符。", "地铁站": "搭配：“有”后接的应是可以拥有的场地或建筑，“地铁站”是公共设施，不搭配。", "卫星": "语义：卫星是天体或人造的太空器，不能在郊外被人拥有。"}, "sentence_index": 0, "correct_answer": "农场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在农场里生产汽车。", "explanation": "这里应该用〈工厂〉。农场用于种植和养殖，不用来生产汽车。"}, {"text": "他去农场取钱。", "explanation": "这里应该用〈银行〉。取钱要去银行，农场不是金融机构。"}, {"text": "我每天早上在农场上数学课。", "explanation": "这里应该用〈学校〉。农场是种植和养殖的地方，不是上课的场所，上课要去学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不能在里面养牛产奶。"}, {"text": "农场", "is_correct": true, "explanation": "“农场”指种植和养殖的场所，与“我们……里的牛”相符。"}, {"text": "书房", "is_correct": false, "explanation": "搭配：“书房”一般不与养牛、产奶搭配，句子不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，里面不能有牛每天产奶。"}], "explanations": {"教室": "语义：教室是上课的地方，不能在里面养牛产奶。", "农场": "“农场”指种植和养殖的场所，与“我们……里的牛”相符。", "书房": "搭配：“书房”一般不与养牛、产奶搭配，句子不通。", "冰箱": "语义：冰箱是家用电器，里面不能有牛每天产奶。"}, "sentence_index": 6, "correct_answer": "农场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去农场买火车票。", "explanation": "这里应该用〈车站〉。火车票要在车站或售票处买，农场不卖火车票。"}, {"text": "法官在农场判案。", "explanation": "这里应该用〈法院〉。判案要在法院进行，农场不能用来判案。"}, {"text": "学生去农场借书。", "explanation": "这里应该用〈图书馆〉。借书要去图书馆，农场没有借书的功能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姑妈在北方经营一只农场。", "corrected_sentence": "姑妈在北方经营一个农场。", "error_description": "“农场”的量词错误。“只”用于动物，不用于农场，应使用“个”，写作“一个农场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些农场们都在北方。", "corrected_sentence": "这些农场都在北方。", "error_description": "“农场”不能加“们”表示复数。“们”只用于人，应写作“这些农场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
