INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21246, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手把东西从上面拿下来。", "primary_collocate": null, "pronunciation": "zhāi xià lai", "ipa": "ʈʂai̯˥ ɕja˥˩ lai̯", "syllable_count": 3, "sentences": [{"text": "墙上的旧画太脏了，我想把它摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门上的牌子歪了，请你把它摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年后，爸爸把门口的灯笼摘下来了。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风筝挂在树上了，他用竹竿把它摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天花板上的气球，弟弟踩着椅子摘下来了。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的镜子松了，爷爷站在凳子上把它摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圣诞节过后，我们把树上的彩灯摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年到了，爸爸把墙上的旧日历摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高处的相框落满了灰，你踩着凳子摘下来擦一擦。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帽子挂在高高的钩子上，请帮我摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摘下来了", "label": "体标"}, {"form": "摘不下来", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "摘下来：用手把挂着的东西从上面取下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a50759fb-3f82-4d2e-b11e-78657eb50899') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21246, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摘下来", "is_correct": true, "explanation": "正确。摘下来读 zhāi xià lai（“来”轻声），指用手把东西从上面拿下来。"}, {"text": "拆下来", "is_correct": false, "explanation": "chāi（拆）与 zhāi（摘）声母不同（ch 与 zh），意思是把连着的东西拆下来。"}, {"text": "筛下来", "is_correct": false, "explanation": "shāi（筛）与 zhāi（摘）声母不同（sh 与 zh），意思是筛出来。"}, {"text": "栽下来", "is_correct": false, "explanation": "zāi（栽）与 zhāi（摘）声母不同（z 与 zh），意思是栽倒、摔下来。"}], "explanations": {"摘下来": "正确。摘下来读 zhāi xià lai（“来”轻声），指用手把东西从上面拿下来。", "拆下来": "chāi（拆）与 zhāi（摘）声母不同（ch 与 zh），意思是把连着的东西拆下来。", "筛下来": "shāi（筛）与 zhāi（摘）声母不同（sh 与 zh），意思是筛出来。", "栽下来": "zāi（栽）与 zhāi（摘）声母不同（z 与 zh），意思是栽倒、摔下来。"}, "sentence_index": null, "correct_answer": "摘下来"}, "level_3": {"options": [{"text": "摘下来", "is_correct": true, "explanation": "正确。“我想把它摘下来”说的是把挂在墙上的旧画取下，与语境相符。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”只用于食物，不能用于墙上的画。"}, {"text": "拉长", "is_correct": false, "explanation": "语义：“拉长”指使变长，与“太脏了想取下”的语境不符。"}, {"text": "吹跑", "is_correct": false, "explanation": "语义：“吹跑”指被风刮走，不是把挂着的画取下。"}], "explanations": {"摘下来": "正确。“我想把它摘下来”说的是把挂在墙上的旧画取下，与语境相符。", "吃掉": "搭配：“吃掉”只用于食物，不能用于墙上的画。", "拉长": "语义：“拉长”指使变长，与“太脏了想取下”的语境不符。", "吹跑": "语义：“吹跑”指被风刮走，不是把挂着的画取下。"}, "sentence_index": 0, "correct_answer": "摘下来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把汤从锅里摘下来。", "explanation": "这里应该用〈盛出来〉。摘用于取下挂着或附着的东西，汤要盛出来。"}, {"text": "司机把车上的货摘下来了。", "explanation": "这里应该用〈卸下来〉。摘用于取下挂着的东西，把货物从车上搬下要说卸下来。"}, {"text": "他把掉在地上的苹果摘下来，放进篮子里。", "explanation": "这里应该用〈捡起来〉。摘用于从枝头或挂着的东西上取下，掉在地上的苹果要捡起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摘下来", "is_correct": true, "explanation": "正确。“把树上的彩灯摘下来”说的是圣诞节后把挂在树上的彩灯取下，与语境相符。"}, {"text": "浇水", "is_correct": false, "explanation": "语义：彩灯不需要浇水，与圣诞节后收起彩灯的语境矛盾。"}, {"text": "戴上", "is_correct": false, "explanation": "搭配：“戴”多用于帽子、眼镜等，不说戴彩灯。"}, {"text": "咬断", "is_correct": false, "explanation": "语义：“咬断”指用牙齿弄断，与取下彩灯的动作不符。"}], "explanations": {"摘下来": "正确。“把树上的彩灯摘下来”说的是圣诞节后把挂在树上的彩灯取下，与语境相符。", "浇水": "语义：彩灯不需要浇水，与圣诞节后收起彩灯的语境矛盾。", "戴上": "搭配：“戴”多用于帽子、眼镜等，不说戴彩灯。", "咬断": "语义：“咬断”指用牙齿弄断，与取下彩灯的动作不符。"}, "sentence_index": 6, "correct_answer": "摘下来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把一大块面包摘下来，切成片。", "explanation": "这里应该用〈切下来〉。摘用于从挂着的东西上取下，把面包切开要说切下来。"}, {"text": "他把地上的箱子摘下来，搬进了屋里。", "explanation": "这里应该用〈搬起来〉。摘下来用于取下高处挂着的东西，地上的箱子要搬起来。"}, {"text": "妈妈把水从井里摘下来，倒进了桶里。", "explanation": "这里应该用〈打上来〉。摘下来用于取下挂着的东西，从井里取水要说打上来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把墙上的铃铛了摘下来了。", "corrected_sentence": "他把墙上的铃铛摘下来了。", "error_description": "错误：“了”插在“把”字宾语与动词“摘”之间，动词前不能用“了”；应删去，正确为“摘下来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗口的风铃挂得太高，妹妹踩着凳子它摘下来。", "corrected_sentence": "窗口的风铃挂得太高，妹妹踩着凳子把它摘下来。", "error_description": "错误：“它”是被摘的东西，应作宾语，放在“摘”前面（如“把它摘下来”）；直接说“它摘下来”，“它”会被当成施事，不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21248, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出口", "is_correct": true, "explanation": "出口与进口相对，指把本国商品卖到国外，是词典收录的反义词。"}, {"text": "跳", "is_correct": false, "explanation": "跳与“进口”没有反义关系，不能构成一对反义词。"}, {"text": "读", "is_correct": false, "explanation": "读与“进口”没有反义关系，不能构成一对反义词。"}, {"text": "跑", "is_correct": false, "explanation": "跑与“进口”没有反义关系，不能构成一对反义词。"}], "correct_answer": "出口", "explanations": {"出口": "出口与进口相对，指把本国商品卖到国外，是词典收录的反义词。", "跳": "跳与“进口”没有反义关系，不能构成一对反义词。", "读": "读与“进口”没有反义关系，不能构成一对反义词。", "跑": "跑与“进口”没有反义关系，不能构成一对反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21248, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出口", "is_correct": true, "explanation": "出口与进口相对，指把本国商品卖到国外，是词典收录的反义词。"}, {"text": "写", "is_correct": false, "explanation": "写与“进口”没有反义关系，不能构成一对反义词。"}, {"text": "看", "is_correct": false, "explanation": "看与“进口”没有反义关系，不能构成一对反义词。"}, {"text": "睡", "is_correct": false, "explanation": "睡与“进口”没有反义关系，不能构成一对反义词。"}], "correct_answer": "出口", "explanations": {"出口": "出口与进口相对，指把本国商品卖到国外，是词典收录的反义词。", "写": "写与“进口”没有反义关系，不能构成一对反义词。", "看": "看与“进口”没有反义关系，不能构成一对反义词。", "睡": "睡与“进口”没有反义关系，不能构成一对反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21248, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从别的国家买东西进来。", "primary_collocate": null, "pronunciation": "jìn kǒu", "ipa": "tɕin˥˩ kʰoʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个国家进口很多水果。", "target_word": "进口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的牛奶是从外国进口的。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的公司专门进口红酒。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国每年进口很多石油。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为太贵，他们不进口这种车了。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的咖啡豆都是进口的。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本从国外进口大米。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天本地不产菜，只能进口。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们从法国进口了一批葡萄酒。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些玩具是进口的，价钱很高。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进口了", "label": "完成体"}, {"form": "进口过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "进口：从外国买入商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e424837-2e8c-4c86-b782-2097d65b46d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21248, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进口", "is_correct": true, "explanation": "进口（jìn kǒu）：从国外买入商品，本句的正确答案。"}, {"text": "紧扣", "is_correct": false, "explanation": "紧扣（jǐn kòu）与进口（jìn kǒu）两个音节的声调都不同，意思是紧紧扣住。"}, {"text": "亲口", "is_correct": false, "explanation": "亲口（qīn kǒu）与进口（jìn kǒu）声母不同（q 与 j），意思是亲自开口。"}, {"text": "心口", "is_correct": false, "explanation": "心口（xīn kǒu）与进口（jìn kǒu）声母不同（x 与 j），意思是胸口。"}, {"text": "信口", "is_correct": false, "explanation": "信口（xìn kǒu）与进口（jìn kǒu）声母不同（x 与 j），意思是随口说。"}], "explanations": {"进口": "进口（jìn kǒu）：从国外买入商品，本句的正确答案。", "紧扣": "紧扣（jǐn kòu）与进口（jìn kǒu）两个音节的声调都不同，意思是紧紧扣住。", "亲口": "亲口（qīn kǒu）与进口（jìn kǒu）声母不同（q 与 j），意思是亲自开口。", "心口": "心口（xīn kǒu）与进口（jìn kǒu）声母不同（x 与 j），意思是胸口。", "信口": "信口（xìn kǒu）与进口（jìn kǒu）声母不同（x 与 j），意思是随口说。"}, "sentence_index": null, "correct_answer": "进口"}, "level_3": {"options": [{"text": "进口", "is_correct": true, "explanation": "进口：从国外买入商品，与“这个国家”和“水果”搭配，句意通顺。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮料，不能说“喝水果”，句子不通。"}, {"text": "鼓励", "is_correct": false, "explanation": "搭配：“鼓励”的宾语应是人，不能说“鼓励水果”。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的宾语应是问题或话题，不能说“讨论水果”。"}], "explanations": {"进口": "进口：从国外买入商品，与“这个国家”和“水果”搭配，句意通顺。", "喝": "语义：“喝”的对象是饮料，不能说“喝水果”，句子不通。", "鼓励": "搭配：“鼓励”的宾语应是人，不能说“鼓励水果”。", "讨论": "搭配：“讨论”的宾语应是问题或话题，不能说“讨论水果”。"}, "sentence_index": 0, "correct_answer": "进口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个周末都去批发市场进口蔬菜。", "explanation": "这里应该用〈进货〉。进口指从国外买入商品，从国内批发市场买要说进货。"}, {"text": "商店每个月从本市的仓库进口一批新鲜水果。", "explanation": "这里应该用〈购进〉。进口指从国外买入货物，从本市仓库买入要说购进。"}, {"text": "学校每学期都去书店进口教材。", "explanation": "这里应该用〈采购〉。进口的货物来自国外，去国内书店买教材要说采购。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进口", "is_correct": true, "explanation": "进口：从国外买入商品，与“从国外”搭配，句意通顺。"}, {"text": "赚", "is_correct": false, "explanation": "搭配：“赚”的宾语应是钱或利润，不能说“赚大米”。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指在土地里栽培，与“从国外”矛盾，句子不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗的动作，与“从国外”矛盾，句意不通。"}], "explanations": {"进口": "进口：从国外买入商品，与“从国外”搭配，句意通顺。", "赚": "搭配：“赚”的宾语应是钱或利润，不能说“赚大米”。", "种植": "语义：“种植”指在土地里栽培，与“从国外”矛盾，句子不通。", "洗": "语义：“洗”是清洗的动作，与“从国外”矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "进口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司把大量茶叶进口到国外。", "explanation": "这里应该用〈出口〉。进口指从国外买入，把国内茶叶卖到国外要说出口。"}, {"text": "电脑需要先进口数据才能运行。", "explanation": "这里应该用〈输入〉。进口只用于从国外买进的货物，把数据送进电脑要说输入。"}, {"text": "学生们进口教室，开始上课。", "explanation": "这里应该用〈进入〉。进口只表示从国外买入货物，不能表示走进房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂从德国进口了很多只机器。", "corrected_sentence": "这家工厂从德国进口了很多台机器。", "error_description": "量词错误：机器要用“台”计量，“只”用于动物或成对的东西，应说“很多台机器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去年从意大利进口了过一批橄榄油。", "corrected_sentence": "我们去年从意大利进口过一批橄榄油。", "error_description": "错误：“进口”后面不能同时用“了”和“过”。正确的是“进口过”，表示经历过，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
