INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很大的水流，像大河一样。", "primary_collocate": null, "pronunciation": "hóng liú", "ipa": "xʊŋ˧˥ lioʊ˧˥", "syllable_count": 2, "sentences": [{"text": "洪流从山上冲下来，声音很大。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，河里出现了一股洪流。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥下的洪流又急又猛。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪流冲走了河边的小树。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪流淹没了路边的田地。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在高处，看着洪流往下游流去。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天雪化了，山里有洪流冲下来。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪流冲过了大坝，下游的人都很紧张。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们离洪流远一点，太危险了。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪流像一条黄龙，一直向东流。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股洪流", "label": "量词"}], "register": "书面", "sense_fingerprint": "洪流·很大的水流，如大河", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab2749-257c-4c70-be8d-c6367b76fc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洪流", "is_correct": true, "explanation": "正确：洪流指很大的水流，从山上冲下来且声音很大，符合语境。"}, {"text": "微风", "is_correct": false, "explanation": "语义：微风轻柔，不会从山上冲下来，更不会声音很大。"}, {"text": "棉絮", "is_correct": false, "explanation": "搭配：“冲下来”用于水流、石块，不用于棉絮。"}, {"text": "信件", "is_correct": false, "explanation": "语义：信件是纸质的书写物，不能从山上冲下来。"}], "explanations": {"洪流": "正确：洪流指很大的水流，从山上冲下来且声音很大，符合语境。", "微风": "语义：微风轻柔，不会从山上冲下来，更不会声音很大。", "棉絮": "搭配：“冲下来”用于水流、石块，不用于棉絮。", "信件": "语义：信件是纸质的书写物，不能从山上冲下来。"}, "sentence_index": 0, "correct_answer": "洪流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条洪流很清，可以直接喝。", "explanation": "这里应该用〈清泉〉。洪流湍急浑浊，不能说“很清，可以直接喝”；清澈可饮的水要说〈清泉〉。"}, {"text": "洪流平静地躺在河床上。", "explanation": "这里应该用〈湖水〉。洪流汹涌湍急，不会“平静地躺”；平静的水才用〈湖水〉来形容。"}, {"text": "洪流安静地流过了村子。", "explanation": "这里应该用〈溪流〉。洪流湍急汹涌，不能说“安静地流”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洪流", "is_correct": true, "explanation": "正确：春天雪化后，山里的洪流冲下来，符合语境。"}, {"text": "白云", "is_correct": false, "explanation": "语义：白云飘在天上，不会从山里冲下来。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔是文具，不能从山里冲下来。"}, {"text": "纸张", "is_correct": false, "explanation": "搭配：“冲下来”不能用于纸张。"}], "explanations": {"洪流": "正确：春天雪化后，山里的洪流冲下来，符合语境。", "白云": "语义：白云飘在天上，不会从山里冲下来。", "粉笔": "语义：粉笔是文具，不能从山里冲下来。", "纸张": "搭配：“冲下来”不能用于纸张。"}, "sentence_index": 6, "correct_answer": "洪流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洪流轻轻地流进了村子。", "explanation": "这里应该用〈溪水〉。洪流湍急汹涌，不能说“轻轻地流进”。"}, {"text": "洪流从山上飘了下来。", "explanation": "这里应该用〈雾〉。洪流湍急有力，不能说“飘下来”；轻飘的东西才用“飘”，如〈雾〉。"}, {"text": "洪流叮咚地流着。", "explanation": "这里应该用〈清泉〉。“叮咚”形容清脆的水声，洪流的声音是轰鸣，不说“叮咚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个洪流从山谷里冲了下来。", "corrected_sentence": "一股洪流从山谷里冲了下来。", "error_description": "量词错误：洪流应用量词“股”，不说“个”。正确应为“一股洪流从山谷里冲了下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暴雨过后，洪流从山上冲下了来。", "corrected_sentence": "暴雨过后，洪流从山上冲了下来。", "error_description": "趋向补语错误：「冲下来」是复合趋向补语，「了」应放在「下来」之前，应说「冲了下来」，不说「冲下了来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21258, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "讨厌", "is_correct": true, "explanation": "正确。“讨厌”表示对某人或某事感到厌烦，与“喜欢”构成反义关系。"}, {"text": "学习", "is_correct": false, "explanation": "“学习”指获取知识或技能，与“喜欢”的意思没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意慢走，与“喜欢”不构成反义。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”指入睡休息，与“喜欢”不是反义关系。"}], "correct_answer": "讨厌", "explanations": {"讨厌": "正确。“讨厌”表示对某人或某事感到厌烦，与“喜欢”构成反义关系。", "学习": "“学习”指获取知识或技能，与“喜欢”的意思没有反义关系。", "散步": "“散步”指随意慢走，与“喜欢”不构成反义。", "睡觉": "“睡觉”指入睡休息，与“喜欢”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21258, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "讨厌", "is_correct": true, "explanation": "正确。“讨厌”表示对某人或某事感到厌恶，与“喜欢”构成反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "“吃饭”指进食，与“喜欢”不是反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”指书写文字，与“喜欢”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”指快速移动双腿，与“喜欢”不构成反义。"}], "correct_answer": "讨厌", "explanations": {"讨厌": "正确。“讨厌”表示对某人或某事感到厌恶，与“喜欢”构成反义关系。", "吃饭": "“吃饭”指进食，与“喜欢”不是反义关系。", "写字": "“写字”指书写文字，与“喜欢”没有反义关系。", "跑步": "“跑步”指快速移动双腿，与“喜欢”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21258, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对某人或某事感到高兴。", "primary_collocate": null, "pronunciation": "xǐ huan", "ipa": "ɕi˨˩ xuan", "syllable_count": 2, "sentences": [{"text": "我喜欢吃苹果。", "target_word": "喜欢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她很喜欢小狗。", "target_word": "喜欢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你喜欢什么颜色？", "target_word": "喜欢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟不喜欢早上起床。", "target_word": "喜欢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我最喜欢周末去公园玩。", "target_word": "喜欢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢听音乐，也喜欢唱歌。", "target_word": "喜欢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师喜欢爱学习的学生。", "target_word": "喜欢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不喜欢太甜的东西。", "target_word": "喜欢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们都喜欢这位新老师。", "target_word": "喜欢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你喜欢哪一个季节？", "target_word": "喜欢", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "喜欢过", "label": "体标"}, {"form": "喜欢上", "label": "补语"}], "register": "中性", "sense_fingerprint": "对人或事物有好感，感到愉快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5fcf5b-556e-47e4-b003-813f3f632225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喜欢", "is_correct": true, "explanation": "正确。“喜欢”表示对某物有好感，符合“我喜欢吃苹果”的语境。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器或器物，不能说“修理吃苹果”。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是表面或器物，不能说“擦吃苹果”。"}, {"text": "叹", "is_correct": false, "explanation": "语义：“叹”表示叹息、感叹，与“吃苹果”这个动作毫无关系，句子不通。"}], "explanations": {"喜欢": "正确。“喜欢”表示对某物有好感，符合“我喜欢吃苹果”的语境。", "修理": "搭配：“修理”的对象是机器或器物，不能说“修理吃苹果”。", "擦": "搭配：“擦”的对象是表面或器物，不能说“擦吃苹果”。", "叹": "语义：“叹”表示叹息、感叹，与“吃苹果”这个动作毫无关系，句子不通。"}, "sentence_index": 0, "correct_answer": "喜欢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喜欢明天别下雨。", "explanation": "这里应该用〈希望〉。“喜欢”表示对人或事物有好感，对未来的事情表达期盼要用“希望”，应说“我希望明天别下雨”。"}, {"text": "他一看到蛇就很喜欢，吓得直往后退。", "explanation": "这里应该用〈害怕〉。“喜欢”表示对人或事物有好感，见到蛇后退缩是恐惧，要用“害怕”。"}, {"text": "我很喜欢这次失误，结果整个方案都要重做。", "explanation": "这里应该用〈讨厌〉。“喜欢”表示好感，对造成麻烦的失误表示反感要用“讨厌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喜欢", "is_correct": true, "explanation": "正确。“喜欢”表示老师对学生有好感，符合句子语境。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用于“学生”，“老师煮学生”说不通。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：“打开”的对象是门、书、盒子等物品，不能用于“学生”。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”指给人或动物送食物，不能用来表示“老师对学生”的态度。"}], "explanations": {"喜欢": "正确。“喜欢”表示老师对学生有好感，符合句子语境。", "煮": "搭配：“煮”的对象是食物，不能用于“学生”，“老师煮学生”说不通。", "打开": "搭配：“打开”的对象是门、书、盒子等物品，不能用于“学生”。", "喂": "搭配：“喂”指给人或动物送食物，不能用来表示“老师对学生”的态度。"}, "sentence_index": 6, "correct_answer": "喜欢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被老师批评了，心里很喜欢。", "explanation": "这里应该用〈难受〉。“喜欢”表示对人或事物的好感，被批评后的心情要用“难受”，不能说“喜欢”。"}, {"text": "我很喜欢把钥匙弄丢了。", "explanation": "这里应该用〈后悔〉。“喜欢”表示好感，对弄丢东西的懊悔要用“后悔”，不能说“喜欢”。"}, {"text": "这次比赛输了，我很喜欢。", "explanation": "这里应该用〈失望〉。“喜欢”表示好感，比赛失利后的心情要用“失望”，不能说“喜欢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很喜欢的唱歌。", "corrected_sentence": "她很喜欢唱歌。", "error_description": "结构助词误用：“喜欢”后直接加“的”，句子不成立；“喜欢”后应直接接宾语，说“她很喜欢唱歌”，不说“她很喜欢的唱歌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前喜欢了那个歌手。", "corrected_sentence": "我以前喜欢过那个歌手。", "error_description": "体标错误：“喜欢”是表示心理状态的动词，说以前有过的经历要用“过”，不能用“了”；应说“以前喜欢过那个歌手”，不说“以前喜欢了那个歌手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
