INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21262, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用钱买东西或用掉东西。", "primary_collocate": null, "pronunciation": "xiāo fèi", "ipa": "ɕjɑʊ˥˥ fei˥˩", "syllable_count": 2, "sentences": [{"text": "他每个月消费三千元。", "target_word": "消费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人喜欢在网上消费。", "target_word": "消费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店太贵，我不想在这里消费。", "target_word": "消费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，人们消费得比平时多。", "target_word": "消费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不会乱消费，每个月都存钱。", "target_word": "消费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市每天消费很多水和电。", "target_word": "消费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在咖啡店消费了五十元，就得到一张卡。", "target_word": "消费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生没有工作，主要靠家里的钱消费。", "target_word": "消费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来这里消费的客人，可以免费停车。", "target_word": "消费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这个月消费得太多，钱不够用了。", "target_word": "消费", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消费了", "label": "体标"}, {"form": "消费过", "label": "体标"}, {"form": "消费者", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，指花钱买东西，或把物品、资源用掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd55c2c29-17cd-4734-b3f1-6a6d294a15a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21262, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "消费", "is_correct": true, "explanation": "正确：消费 xiāo fèi，意思是用钱买东西或用掉东西。"}, {"text": "小费", "is_correct": false, "explanation": "xiǎo fèi（第三声）与 xiāo fèi（第一声）声调不同，意思是给服务人员的额外钱。"}, {"text": "交费", "is_correct": false, "explanation": "jiāo fèi 与 xiāo fèi 声母不同（j 与 x），意思是缴纳费用。"}, {"text": "缴费", "is_correct": false, "explanation": "jiǎo fèi 与 xiāo fèi 声母和声调不同（j 与 x，三声与一声），意思是交纳费用。"}], "explanations": {"消费": "正确：消费 xiāo fèi，意思是用钱买东西或用掉东西。", "小费": "xiǎo fèi（第三声）与 xiāo fèi（第一声）声调不同，意思是给服务人员的额外钱。", "交费": "jiāo fèi 与 xiāo fèi 声母不同（j 与 x），意思是缴纳费用。", "缴费": "jiǎo fèi 与 xiāo fèi 声母和声调不同（j 与 x，三声与一声），意思是交纳费用。"}, "sentence_index": null, "correct_answer": "消费"}, "level_3": {"options": [{"text": "消费", "is_correct": true, "explanation": "正确：“消费”表示花钱买东西，与“每个月”“三千元”相符。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“写三千元”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能与钱数搭配。"}, {"text": "去", "is_correct": false, "explanation": "配价：“去”后接处所，不接钱数，“去三千元”不成立。"}], "explanations": {"消费": "正确：“消费”表示花钱买东西，与“每个月”“三千元”相符。", "写": "搭配：“写”的对象是文字，不能说“写三千元”。", "唱": "搭配：“唱”的对象是歌曲，不能与钱数搭配。", "去": "配价：“去”后接处所，不接钱数，“去三千元”不成立。"}, "sentence_index": 0, "correct_answer": "消费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我消费了一整天才修好电脑。", "explanation": "这里应该用〈花费〉。消费用于用钱买东西或用掉物品，花在一段时间上要说花费。"}, {"text": "跑步会消费很多体力。", "explanation": "这里应该用〈消耗〉。消费指用钱或用掉物品，体力、能量的耗损要说消耗。"}, {"text": "请消费这把剪刀。", "explanation": "这里应该用〈使用〉。消费指花钱或把东西用掉，剪刀可以反复使用，不是用掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消费", "is_correct": true, "explanation": "正确：“消费”指在店里花钱买东西，与“五十元”“得到一张卡”相符。"}, {"text": "逛", "is_correct": false, "explanation": "搭配：“逛”是闲走，不能直接接钱数。"}, {"text": "游", "is_correct": false, "explanation": "配价：“游”是不及物动词，后面不能带“五十元”作宾语。"}, {"text": "等", "is_correct": false, "explanation": "搭配：“等”后接时间或人，不能说“等了五十元”。"}], "explanations": {"消费": "正确：“消费”指在店里花钱买东西，与“五十元”“得到一张卡”相符。", "逛": "搭配：“逛”是闲走，不能直接接钱数。", "游": "配价：“游”是不及物动词，后面不能带“五十元”作宾语。", "等": "搭配：“等”后接时间或人，不能说“等了五十元”。"}, "sentence_index": 6, "correct_answer": "消费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "别消费钱，要学会节约。", "explanation": "这里应该用〈浪费〉。消费是正常地花钱买东西，钱白白花掉要说浪费，“消费钱”不成立。"}, {"text": "他吃得很快，消费得也很快。", "explanation": "这里应该用〈消化〉。消费指用钱买东西，食物在体内的吸收要说消化。"}, {"text": "这块硬盘能消费很多照片。", "explanation": "这里应该用〈储存〉。消费指用掉钱或物品，硬盘保存数据要说储存。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上个月消费着三百元。", "corrected_sentence": "我上个月消费了三百元。", "error_description": "错误：“消费着三百元”，“着”表示动作持续，此处是已完成的消费，应用“了”。正确：“消费了三百元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐平时消费很得少。", "corrected_sentence": "姐姐平时消费得很少。", "error_description": "错误在补语的位置：“得”引出补语，“很”应放在补语的形容词前，应说“消费得很少”，不能说“消费很得少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
