INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21264, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "饮用咖啡这种饮料。", "primary_collocate": null, "pronunciation": "hē kā fēi", "ipa": "xɤ˥ kʰa˥ fei̯˥", "syllable_count": 3, "sentences": [{"text": "我每天早上喝咖啡。", "target_word": "喝咖啡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不喜欢晚上喝咖啡。", "target_word": "喝咖啡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们去那家店喝咖啡吧。", "target_word": "喝咖啡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸一边看报纸一边喝咖啡。", "target_word": "喝咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝咖啡以后，我睡不着觉。", "target_word": "喝咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喝咖啡的时候不放糖。", "target_word": "喝咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常和朋友喝咖啡聊天。", "target_word": "喝咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说你不要多喝咖啡。", "target_word": "喝咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐在窗边喝咖啡。", "target_word": "喝咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正在办公室里喝咖啡。", "target_word": "喝咖啡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "喝咖啡：喝咖啡这种饮料的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e424837-2e8c-4c86-b782-2097d65b46d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喝咖啡", "is_correct": true, "explanation": "正确：“喝咖啡”是每天早上常见的动作，句意自然。"}, {"text": "吸咖啡", "is_correct": false, "explanation": "搭配：“吸”一般用于烟、空气，不说吸咖啡。"}, {"text": "咬咖啡", "is_correct": false, "explanation": "搭配：“咬”的对象要能咬，咖啡不能咬。"}, {"text": "喝墨水", "is_correct": false, "explanation": "语义：墨水不能喝，句子不符合常识。"}], "explanations": {"喝咖啡": "正确：“喝咖啡”是每天早上常见的动作，句意自然。", "吸咖啡": "搭配：“吸”一般用于烟、空气，不说吸咖啡。", "咬咖啡": "搭配：“咬”的对象要能咬，咖啡不能咬。", "喝墨水": "语义：墨水不能喝，句子不符合常识。"}, "sentence_index": 0, "correct_answer": "喝咖啡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上喝咖啡，喝得大醉。", "explanation": "这里应该用〈喝酒〉。“喝咖啡”指饮用咖啡，喝到大醉要用“喝酒”。"}, {"text": "妈妈每天早上喝咖啡给我们。", "explanation": "这里应该用〈煮〉。“喝咖啡”表示自己喝，不能表示为别人准备饮品。"}, {"text": "那家店每天喝咖啡。", "explanation": "这里应该用〈卖〉。“喝咖啡”的主语要是人，店铺不能“喝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝咖啡", "is_correct": true, "explanation": "正确：“周末和朋友喝咖啡聊天”是常见的说法，句意通顺。"}, {"text": "摔咖啡", "is_correct": false, "explanation": "搭配：“摔”的对象是物体撞击，不能说摔咖啡。"}, {"text": "修咖啡", "is_correct": false, "explanation": "搭配：“修”的对象是坏掉的东西，不能说修咖啡。"}, {"text": "喝石头", "is_correct": false, "explanation": "语义：石头不能喝，句子说不通。"}], "explanations": {"喝咖啡": "正确：“周末和朋友喝咖啡聊天”是常见的说法，句意通顺。", "摔咖啡": "搭配：“摔”的对象是物体撞击，不能说摔咖啡。", "修咖啡": "搭配：“修”的对象是坏掉的东西，不能说修咖啡。", "喝石头": "语义：石头不能喝，句子说不通。"}, "sentence_index": 6, "correct_answer": "喝咖啡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用开水喝咖啡。", "explanation": "这里应该用〈泡〉。“喝咖啡”是饮用的动作，制作咖啡要用“泡”。"}, {"text": "他用咖啡机喝咖啡。", "explanation": "这里应该用〈煮〉。“喝咖啡”是饮用的动作，用咖啡机做咖啡要说“煮咖啡”。"}, {"text": "服务员给客人喝咖啡。", "explanation": "这里应该用〈倒〉。“喝咖啡”是自己饮用，把咖啡倒给别人要说“给客人倒咖啡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天早上喝咖啡，一只就够了。", "corrected_sentence": "他每天早上喝咖啡，一杯就够了。", "error_description": "量词错误：咖啡要用“杯”计量，“只”用于动物或成对的东西，应说“一杯就够了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他喝咖啡喝很快。", "corrected_sentence": "他喝咖啡喝得很快。", "error_description": "补语错误：表示动作程度的补语前要加“得”，“喝很快”应改为“喝得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
