INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21268, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种可以喝的棕色饮料，有点苦，能让人不困。", "primary_collocate": null, "pronunciation": "kā fēi", "ipa": "kʰa˥ feɪ˥", "syllable_count": 2, "sentences": [{"text": "我每天早上喝一杯咖啡。", "target_word": "咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯咖啡有点苦，我想加点糖。", "target_word": "咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚喝了咖啡，我现在一点也不困。", "target_word": "咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员，请给我一杯热咖啡，不要牛奶。", "target_word": "咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不让孩子喝咖啡，因为晚上会睡不着。", "target_word": "咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种咖啡的味道很香，也不太苦。", "target_word": "咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边看书，一边喝着咖啡。", "target_word": "咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡太烫了，你等一会儿再喝。", "target_word": "咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去超市买了一包咖啡和两瓶牛奶。", "target_word": "咖啡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加班的时候，同事们都喝咖啡提神。", "target_word": "咖啡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一杯咖啡", "label": "量词"}, {"form": "咖啡豆", "label": "复合"}, {"form": "咖啡馆", "label": "复合"}], "register": "中性", "sense_fingerprint": "棕色、微苦、能提神的饮料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911ce2b6-7d1d-4794-8ddb-56c9662d33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21268, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咖啡", "is_correct": true, "explanation": "正确：咖啡是可以喝的饮料，与“一杯”搭配，符合句意。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不能喝，与“每天早上喝”冲突。"}, {"text": "洗发水", "is_correct": false, "explanation": "语义：洗发水不能喝，与“喝”的对象不符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“一杯”用于可盛放的液体，空气不能用杯子计量。"}], "explanations": {"咖啡": "正确：咖啡是可以喝的饮料，与“一杯”搭配，符合句意。", "汽油": "语义：汽油不能喝，与“每天早上喝”冲突。", "洗发水": "语义：洗发水不能喝，与“喝”的对象不符。", "空气": "搭配：“一杯”用于可盛放的液体，空气不能用杯子计量。"}, "sentence_index": 0, "correct_answer": "咖啡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天太热了，他用咖啡浇花。", "explanation": "这里应该用〈水〉。咖啡是给人喝的饮料，浇花要用水。"}, {"text": "孩子正在长身体，我每天给他一杯咖啡补钙。", "explanation": "这里应该用〈牛奶〉。补钙应喝牛奶，咖啡不含钙，不能用来补钙。"}, {"text": "我太困了，想喝杯咖啡好好睡一觉。", "explanation": "这里应该用〈热牛奶〉。咖啡能让人不困，不能帮助睡觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咖啡", "is_correct": true, "explanation": "正确：咖啡是可以喝的饮料，符合“一边喝着”。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水不能喝，与“喝着”冲突。"}, {"text": "胶水", "is_correct": false, "explanation": "语义：胶水不能喝，句意冲突。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“喝”的对象要是液体，“书”不能喝。"}], "explanations": {"咖啡": "正确：咖啡是可以喝的饮料，符合“一边喝着”。", "墨水": "语义：墨水不能喝，与“喝着”冲突。", "胶水": "语义：胶水不能喝，句意冲突。", "书": "搭配：“喝”的对象要是液体，“书”不能喝。"}, "sentence_index": 6, "correct_answer": "咖啡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这瓶咖啡颜色鲜红，倒进杯子里很好看。", "explanation": "这里应该用〈番茄汁〉。咖啡是棕色的，不会颜色鲜红。"}, {"text": "他把咖啡倒进鱼缸里，给小鱼喂食。", "explanation": "这里应该用〈鱼食〉。咖啡是饮料，不能给鱼当食物，喂鱼应说鱼食。"}, {"text": "孩子晚上睡不着，妈妈给他泡了一杯咖啡，让他快点睡觉。", "explanation": "这里应该用〈花茶〉。咖啡能让人提神，不能用来帮助入睡，睡前助眠应说花茶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下午我买了一条咖啡，放在桌上。", "corrected_sentence": "下午我买了一杯咖啡，放在桌上。", "error_description": "量词错误：咖啡应用“杯”计量，“条”用于细长的物件，不能用于咖啡。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一边看书，一边喝着一本咖啡。", "corrected_sentence": "他一边看书，一边喝着一杯咖啡。", "error_description": "量词错误：“本”用于书，咖啡应用“杯”计量，说“一杯咖啡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
