INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21270, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情最后变成的样子。", "primary_collocate": null, "pronunciation": "jié guǒ", "ipa": "tɕjɛ˧˥ kwɔ˨˩˦", "syllable_count": 2, "sentences": [{"text": "比赛的结果让大家很高兴。", "target_word": "结果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查结果明天才能出来。", "target_word": "结果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个结果我没想到。", "target_word": "结果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一定要接受这个结果。", "target_word": "结果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生告诉我检查的结果。", "target_word": "结果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结果什么时候公布？", "target_word": "结果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管结果怎么样，我都会去试。", "target_word": "结果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次实验的结果和以前不一样。", "target_word": "结果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等了很久，等来的却是坏结果。", "target_word": "结果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不知道最后的结果是什么。", "target_word": "结果", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "事情发展到最后的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d78632b-8856-4b08-affc-b5331421b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结果", "is_correct": true, "explanation": "正确：「结果」指比赛最后的情况，可以让大家高兴。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」指身体的重量，与比赛的结果无关。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」描述人的体形，不能用来指比赛的情况。"}, {"text": "温度", "is_correct": false, "explanation": "语义：「温度」指冷热程度，与比赛的结果无关。"}], "explanations": {"结果": "正确：「结果」指比赛最后的情况，可以让大家高兴。", "体重": "语义：「体重」指身体的重量，与比赛的结果无关。", "身材": "体貌：「身材」描述人的体形，不能用来指比赛的情况。", "温度": "语义：「温度」指冷热程度，与比赛的结果无关。"}, "sentence_index": 0, "correct_answer": "结果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的结果很快。", "explanation": "这里应该用〈速度〉。结果指事情最后的样子，车的快慢要说速度。"}, {"text": "他一下午结果了三道题。", "explanation": "这里应该用〈解答〉。“结果”作动词多指植物结果，或指了结性命，做题要说解答。"}, {"text": "这个机器有很多结果。", "explanation": "这里应该用〈功能〉。结果指事情最后的样子，机器的用途要说功能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结果", "is_correct": true, "explanation": "正确：「结果」指事情最后的样子，可以说“不管结果怎么样”。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：「脚步」指走路的步子，与“去试”无关，不能说“不管脚步怎么样”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：「天空」不能作为“去试”的对象，句子意思说不通。"}, {"text": "容貌", "is_correct": false, "explanation": "体貌：「容貌」指人的外表，不能用“去试”来说。"}], "explanations": {"结果": "正确：「结果」指事情最后的样子，可以说“不管结果怎么样”。", "脚步": "语义：「脚步」指走路的步子，与“去试”无关，不能说“不管脚步怎么样”。", "天空": "语义：「天空」不能作为“去试”的对象，句子意思说不通。", "容貌": "体貌：「容貌」指人的外表，不能用“去试”来说。"}, "sentence_index": 6, "correct_answer": "结果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只狗的结果很可爱。", "explanation": "这里应该用〈外表〉。结果指事情最后的样子，动物的外貌要说外表。"}, {"text": "这套房子的结果很便宜。", "explanation": "这里应该用〈房租〉。结果指事情最后的样子，房子的租金要说房租。"}, {"text": "她的结果很苗条。", "explanation": "这里应该用〈身材〉。结果指事情最后的样子，人的体型要说身材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试有一次好结果。", "corrected_sentence": "这次考试有一个好结果。", "error_description": "错误在量词“次”。“结果”应该用量词“个”，“一次”表示次数，不能用来修饰结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次检查的结果明天就能来出。", "corrected_sentence": "这次检查的结果明天就能出来。", "error_description": "错误在补语的顺序。“出来”是固定的趋向补语，说结果公布；“来出”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
