INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21272, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21272, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "出口就是可以走出去的门或路。", "primary_collocate": null, "pronunciation": "chū kǒu", "ipa": "ʈʂʰu˥ kʰou˨˩˦", "syllable_count": 2, "sentences": [{"text": "电影结束了，大家从出口慢慢走出去。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的出口在左边，入口在右边。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，地铁站的出口在哪儿？", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "着火时，请从最近的出口离开。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商店只有一个出口，人很多。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在体育馆的出口等你。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走错了路，找不到公园的出口。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进去的门叫入口，出去的门叫出口。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出口前面站着很多人，我们走不出去。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁二号出口旁边有一家咖啡店。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "出去的门或通道，与入口相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96644a94-d766-4004-bc27-ec755acabdc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”不是观众散场时走出的地方，与电影院的场景不符。"}, {"text": "出口", "is_correct": true, "explanation": "“出口”指可以走出去的门或通道，与“从……走出去”相合，填入正确。"}, {"text": "售票处", "is_correct": false, "explanation": "语义：“售票处”是买票的地方，电影结束后大家不会从那里走出去。"}, {"text": "柜台", "is_correct": false, "explanation": "搭配：“柜台”是营业的设备，不能作为人走出去的通道，与“从……走出去”不搭配。"}], "explanations": {"厨房": "语义：“厨房”不是观众散场时走出的地方，与电影院的场景不符。", "出口": "“出口”指可以走出去的门或通道，与“从……走出去”相合，填入正确。", "售票处": "语义：“售票处”是买票的地方，电影结束后大家不会从那里走出去。", "柜台": "搭配：“柜台”是营业的设备，不能作为人走出去的通道，与“从……走出去”不搭配。"}, "sentence_index": 0, "correct_answer": "出口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这扇门是进去用的，所以标着出口。", "explanation": "这里应该用〈入口〉。“出口”指出去的门，进去的门要说入口。"}, {"text": "他把旧房子出口了，搬到了城外。", "explanation": "这里应该用〈出售〉。“出口”指把货物运到国外卖，卖房子不能用出口。"}, {"text": "这个房间有一只出口，很窄。", "explanation": "这里不能用〈只〉。“出口”是地方，量词应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是可以去寻找的地方，“找不到公园的天空”不通。"}, {"text": "出口", "is_correct": true, "explanation": "“出口”指公园里可以走出去的门或通道，找不到的正是它，填入正确。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：“音乐”是声音艺术，不能作为园内的地点被找不到，句意不合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“找不到”后面常接地点或路线，“公园的颜色”不能组成可以寻找的对象。"}], "explanations": {"天空": "语义：“天空”不是可以去寻找的地方，“找不到公园的天空”不通。", "出口": "“出口”指公园里可以走出去的门或通道，找不到的正是它，填入正确。", "音乐": "语义：“音乐”是声音艺术，不能作为园内的地点被找不到，句意不合。", "颜色": "搭配：“找不到”后面常接地点或路线，“公园的颜色”不能组成可以寻找的对象。"}, "sentence_index": 6, "correct_answer": "出口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于找到了工作的出口。", "explanation": "这里应该用〈出路〉。“出口”只指具体的门或通道，比喻意义要说出路。"}, {"text": "这栋楼有一条出口，很宽。", "explanation": "这里不能用〈条〉。“出口”是地方，量词应该用〈个〉。"}, {"text": "我们公司今年从国外出口了很多机器。", "explanation": "这里应该用〈进口〉。“出口”指把货物运往国外卖出，从国外买进要说进口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个车站的一只出口在西边，很好找。", "corrected_sentence": "这个车站的一个出口在西边，很好找。", "error_description": "量词错误：“出口”应该用量词“个”，不能用“只”，“只”通常用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地下通道的出口了在东边，很好找。", "corrected_sentence": "地下通道的出口在东边，很好找。", "error_description": "助词错误：名词“出口”后面不能加“了”，正确的说法是“出口在东边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21274, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21274, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "工业", "is_correct": true, "explanation": "正确答案。工业是与农业相对的产业，二者是反义词。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋是自然地理事物，与农业没有反义关系。"}, {"text": "医院", "is_correct": false, "explanation": "医院指医疗机构，与农业没有反义关系。"}, {"text": "钢琴", "is_correct": false, "explanation": "钢琴是乐器，与农业没有反义关系。"}], "correct_answer": "工业", "explanations": {"工业": "正确答案。工业是与农业相对的产业，二者是反义词。", "海洋": "海洋是自然地理事物，与农业没有反义关系。", "医院": "医院指医疗机构，与农业没有反义关系。", "钢琴": "钢琴是乐器，与农业没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21274, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "农民伯伯种粮食和养动物的活儿。", "primary_collocate": null, "pronunciation": "nóng yè", "ipa": "nʊŋ˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的农业很发达。", "target_word": "农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业需要很多水，天气也很重要。", "target_word": "农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大学学的是农业，毕业后回了老家。", "target_word": "农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区工业少，主要靠农业生活。", "target_word": "农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天是农业最忙的季节。", "target_word": "农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业用水占了全国用水的一大半。", "target_word": "农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给农业提供了很多帮助。", "target_word": "农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代农业用机器种地，不用太多人。", "target_word": "农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年雨水多，农业收成很好。", "target_word": "农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的农业以水果种植为主。", "target_word": "农业", "complexity_tier": "T3", "furigana": "zhè gè cūn zi de nóng yè yǐ shuǐ guǒ zhòng zhí wéi zhǔ", "sentence_source": "generated"}], "morphological_forms": [{"form": "农业国", "label": "复合"}], "register": "中性", "sense_fingerprint": "种粮食、养动物的生产行业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4208b8-fa3e-439a-94ca-4737d9934ac5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21274, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "农业", "is_correct": true, "explanation": "正确答案。农业指种粮食、养动物的生产行业。"}, {"text": "农药", "is_correct": false, "explanation": "农药（nóng yào）与农业（nóng yè）只在第二个音节的韵母上不同：yào 与 yè。农药指防治病虫害的化学品。"}, {"text": "红叶", "is_correct": false, "explanation": "红叶（hóng yè）与农业只在第一个音节的声母上不同：h 与 n。红叶指变红的树叶。"}, {"text": "溶液", "is_correct": false, "explanation": "溶液（róng yè）与农业只在第一个音节的声母上不同：r 与 n。溶液指溶质溶在溶剂中形成的混合液体。"}], "explanations": {"农业": "正确答案。农业指种粮食、养动物的生产行业。", "农药": "农药（nóng yào）与农业（nóng yè）只在第二个音节的韵母上不同：yào 与 yè。农药指防治病虫害的化学品。", "红叶": "红叶（hóng yè）与农业只在第一个音节的声母上不同：h 与 n。红叶指变红的树叶。", "溶液": "溶液（róng yè）与农业只在第一个音节的声母上不同：r 与 n。溶液指溶质溶在溶剂中形成的混合液体。"}, "sentence_index": null, "correct_answer": "农业"}, "level_3": {"options": [{"text": "农业", "is_correct": true, "explanation": "正确答案。“农业”是种粮食、养动物的行业，可以说“很发达”。"}, {"text": "鸟类", "is_correct": false, "explanation": "搭配：“发达”说经济、行业、交通等，不说动物类群“很发达”。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地方，不是行业或经济，不能说“很发达”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“发达”不修饰体重，“体重很发达”不成立。"}], "explanations": {"农业": "正确答案。“农业”是种粮食、养动物的行业，可以说“很发达”。", "鸟类": "搭配：“发达”说经济、行业、交通等，不说动物类群“很发达”。", "厨房": "语义：厨房是地方，不是行业或经济，不能说“很发达”。", "体重": "搭配：“发达”不修饰体重，“体重很发达”不成立。"}, "sentence_index": 0, "correct_answer": "农业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地区的农业昨天考上了大学。", "explanation": "这里应该用〈学生〉。农业是行业，不会考上大学，考上大学的应是人。"}, {"text": "他的农业今天在厨房做饭。", "explanation": "这里应该用〈厨师〉。农业是行业，不会做饭，做饭的应是人。"}, {"text": "这个地区的农业每天种地。", "explanation": "这里应该用〈农民〉。“种地”的主语要是人，农业是行业，不能做这个动作的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21274, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "农业", "is_correct": true, "explanation": "正确答案。农业指种粮食、养动物的生产行业。"}, {"text": "农艺", "is_correct": false, "explanation": "农艺（nóng yì）与农业只在第二个音节的韵母上不同：yì 与 yè。农艺指农作物栽培的技术。"}, {"text": "从业", "is_correct": false, "explanation": "从业（cóng yè）与农业只在第一个音节的声母上不同：c 与 n。从业指参加某种职业。"}, {"text": "同业", "is_correct": false, "explanation": "同业（tóng yè）与农业只在第一个音节的声母上不同：t 与 n。同业指同一行业。"}], "explanations": {"农业": "正确答案。农业指种粮食、养动物的生产行业。", "农艺": "农艺（nóng yì）与农业只在第二个音节的韵母上不同：yì 与 yè。农艺指农作物栽培的技术。", "从业": "从业（cóng yè）与农业只在第一个音节的声母上不同：c 与 n。从业指参加某种职业。", "同业": "同业（tóng yè）与农业只在第一个音节的声母上不同：t 与 n。同业指同一行业。"}, "sentence_index": null, "correct_answer": "农业"}, "level_3": {"options": [{"text": "农业", "is_correct": true, "explanation": "正确答案。“提供帮助”的对象可以是农业这样的产业。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“提供帮助”的对象要能接受帮助，石头不能接受帮助。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是接受帮助的对象，不能说“给天气提供帮助”。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：“提供帮助”的对象要能接受帮助，钢笔是物品，不能接受帮助。"}], "explanations": {"农业": "正确答案。“提供帮助”的对象可以是农业这样的产业。", "石头": "语义：“提供帮助”的对象要能接受帮助，石头不能接受帮助。", "天气": "语义：天气不是接受帮助的对象，不能说“给天气提供帮助”。", "钢笔": "语义：“提供帮助”的对象要能接受帮助，钢笔是物品，不能接受帮助。"}, "sentence_index": 6, "correct_answer": "农业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市场上的农业很便宜。", "explanation": "这里应该用〈农产品〉。农业指行业，不是能在市场上买卖的东西；买卖的是农产品。"}, {"text": "这包农业很重。", "explanation": "这里应该用〈化肥〉。农业是行业，不是能装进袋子的东西；“包”装的应是化肥。"}, {"text": "农业在田里来回跑。", "explanation": "这里应该用〈农机〉。农业是行业，不会在田里跑；在田里来回跑的是农机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个县地农业很有名。", "corrected_sentence": "这个县的农业很有名。", "error_description": "结构助词错误：修饰名词“农业”要用“的”，不能用“地”。错误形式是“这个县地农业”，正确形式是“这个县的农业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年农业们发展得很快。", "corrected_sentence": "这些年农业发展得很快。", "error_description": "“们”不能加在“农业”后面：“们”只用于人，“农业”是抽象的行业。应删去“们”，写作“这些年农业发展得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
