INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21276, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21276, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "树是一种长得很高、有树干和叶子的植物。", "primary_collocate": null, "pronunciation": "shù", "ipa": "ʂu˥˩", "syllable_count": 1, "sentences": [{"text": "院子里有一棵很高的树。", "target_word": "树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟站在树上唱歌。", "target_word": "树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，树上的叶子都黄了。", "target_word": "树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在树下吃午饭。", "target_word": "树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在家门口种了一棵树。", "target_word": "树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树已经有一百年了。", "target_word": "树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫爬上树，下不来了。", "target_word": "树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，路边的树一直在动。", "target_word": "树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，山上的树都绿了。", "target_word": "树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在树旁边玩球。", "target_word": "树", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "树木", "label": "复合"}, {"form": "树叶", "label": "复合"}], "register": "中性", "sense_fingerprint": "有树干和树叶的高大植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4208b8-fa3e-439a-94ca-4737d9934ac5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21276, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "树", "is_correct": true, "explanation": "树（shù）是有树干和树叶的高大植物。"}, {"text": "鼠", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是老鼠。"}, {"text": "书", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是书籍。"}, {"text": "熟", "is_correct": false, "explanation": "shú（第二声）与 shù（第四声）声调不同，意思是成熟或煮好。"}, {"text": "素", "is_correct": false, "explanation": "sù 与 shù 声母不同（s 与 sh），意思是朴素或素食。"}], "explanations": {"树": "树（shù）是有树干和树叶的高大植物。", "鼠": "shǔ（第三声）与 shù（第四声）声调不同，意思是老鼠。", "书": "shū（第一声）与 shù（第四声）声调不同，意思是书籍。", "熟": "shú（第二声）与 shù（第四声）声调不同，意思是成熟或煮好。", "素": "sù 与 shù 声母不同（s 与 sh），意思是朴素或素食。"}, "sentence_index": null, "correct_answer": "树"}, "level_3": {"options": [{"text": "房子", "is_correct": false, "explanation": "搭配：“棵”用于植物，不能说“一棵很高的房子”。"}, {"text": "树", "is_correct": true, "explanation": "正确。“一棵很高的树”中，“棵”计量植物，“树”是高大的植物。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是一片场所，不是能长得很高的东西。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“棵”用于植物，墙不能说“一棵很高的墙”。"}], "explanations": {"房子": "搭配：“棵”用于植物，不能说“一棵很高的房子”。", "树": "正确。“一棵很高的树”中，“棵”计量植物，“树”是高大的植物。", "公园": "语义：公园是一片场所，不是能长得很高的东西。", "墙": "搭配：“棵”用于植物，墙不能说“一棵很高的墙”。"}, "sentence_index": 0, "correct_answer": "树"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在河边喝树。", "explanation": "这里应该用〈水〉。喝的是液体，树不能拿来喝。"}, {"text": "这张桌子是用树做的。", "explanation": "这里应该用〈木头〉。做家具的材料要说“木头”，“树”指生长着的植物。"}, {"text": "秋天，地上落满了树。", "explanation": "这里应该用〈树叶〉。落在地上的是叶子，不是整棵树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21276, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "树", "is_correct": true, "explanation": "树（shù）是有树干和树叶的高大植物。"}, {"text": "暑", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是炎热的天气。"}, {"text": "梳", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是梳子或梳理。"}, {"text": "速", "is_correct": false, "explanation": "sù 与 shù 声母不同（s 与 sh），意思是速度。"}], "explanations": {"树": "树（shù）是有树干和树叶的高大植物。", "暑": "shǔ（第三声）与 shù（第四声）声调不同，意思是炎热的天气。", "梳": "shū（第一声）与 shù（第四声）声调不同，意思是梳子或梳理。", "速": "sù 与 shù 声母不同（s 与 sh），意思是速度。"}, "sentence_index": null, "correct_answer": "树"}, "level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的，不能被爬上。"}, {"text": "树", "is_correct": true, "explanation": "正确。“爬上树”是小猫爬到树上，下不来，符合句意。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是水流，不是可以攀爬的东西。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：“爬上”只能用于可以攀登的处所，不搭配“电话”。"}], "explanations": {"空气": "语义：空气是无形的，不能被爬上。", "树": "正确。“爬上树”是小猫爬到树上，下不来，符合句意。", "河": "语义：河是水流，不是可以攀爬的东西。", "电话": "搭配：“爬上”只能用于可以攀登的处所，不搭配“电话”。"}, "sentence_index": 6, "correct_answer": "树"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们捡了很多树。", "explanation": "这里应该用〈树枝〉。捡起来的是折断的枝条，整棵树不能捡。"}, {"text": "我们用树烧了一锅饭。", "explanation": "这里应该用〈柴火〉。烧饭用的是柴火，不能把整棵树拿来烧。"}, {"text": "树上结满了红红的树。", "explanation": "这里应该用〈果实〉。树上结的是果实，树本身不能作果实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里种着两个树。", "corrected_sentence": "院子里种着两棵树。", "error_description": "错误形式：“两个树”；正确形式：“两棵树”。树是植物，量词要用“棵”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸟飞到了上树。", "corrected_sentence": "小鸟飞到了树上。", "error_description": "错误形式：“到了上树”；正确形式：“到了树上”。“到”后面要接处所词，应说“树上”；“上树”是动词短语（爬到树上），不能作地点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
