INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21284, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "果子就是可以吃的水果。", "primary_collocate": null, "pronunciation": "guǒ zi", "ipa": "kuo˨˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "桌子上有一盘新鲜的果子。", "target_word": "果子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们爱吃甜果子。", "target_word": "果子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山里的果子又红又脆。", "target_word": "果子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我给朋友买了一些果子。", "target_word": "果子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种果子可以直接吃，不用煮。", "target_word": "果子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天果子很少，价格有点贵。", "target_word": "果子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小松鼠抱着果子跑上了树。", "target_word": "果子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把果子放在冰箱里。", "target_word": "果子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想吃什么果子？", "target_word": "果子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个果子洗过了，你放心吃。", "target_word": "果子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "颗", "label": "量词"}, {"form": "果子酱", "label": "复合"}], "register": "口语", "sense_fingerprint": "可以吃的水果，日常口语说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b11de0e-cf3b-40a3-9579-0c6b07e0660f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21284, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "果子", "is_correct": true, "explanation": "正确。guǒ zi 指可以直接吃的水果。"}, {"text": "锅子", "is_correct": false, "explanation": "guō zi（第一声）与 guǒ zi（第三声）只有第一个音节声调不同，锅子指做饭用的锅。"}, {"text": "瓜子", "is_correct": false, "explanation": "guā zi（第一声）与 guǒ zi（第三声）只有第一个音节声调不同，瓜子指炒熟或腌制的葵花子、西瓜子。"}, {"text": "果汁", "is_correct": false, "explanation": "guǒ zhī 与 guǒ zi 的第二个音节声母与声调都不同（zh 与 z，第一声与轻声），果汁是饮品，不是水果本身。"}, {"text": "骨子", "is_correct": false, "explanation": "gǔ zi 与 guǒ zi 只有第一个音节的韵母不同（u 与 uo），骨子指骨头，也指事物的本质。"}], "explanations": {"果子": "正确。guǒ zi 指可以直接吃的水果。", "锅子": "guō zi（第一声）与 guǒ zi（第三声）只有第一个音节声调不同，锅子指做饭用的锅。", "瓜子": "guā zi（第一声）与 guǒ zi（第三声）只有第一个音节声调不同，瓜子指炒熟或腌制的葵花子、西瓜子。", "果汁": "guǒ zhī 与 guǒ zi 的第二个音节声母与声调都不同（zh 与 z，第一声与轻声），果汁是饮品，不是水果本身。", "骨子": "gǔ zi 与 guǒ zi 只有第一个音节的韵母不同（u 与 uo），骨子指骨头，也指事物的本质。"}, "sentence_index": null, "correct_answer": "果子"}, "level_3": {"options": [{"text": "果子", "is_correct": true, "explanation": "果子指可以吃的水果，与“新鲜的”“一盘”相符。"}, {"text": "钉子", "is_correct": false, "explanation": "语义：钉子不能吃，也不是新鲜的食物，“一盘新鲜的钉子”说不通。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“新鲜”用于食物，不说新鲜的玩具。"}, {"text": "树枝", "is_correct": false, "explanation": "语义：树枝不能当食物，“一盘新鲜的树枝”句意不通。"}], "explanations": {"果子": "果子指可以吃的水果，与“新鲜的”“一盘”相符。", "钉子": "语义：钉子不能吃，也不是新鲜的食物，“一盘新鲜的钉子”说不通。", "玩具": "搭配：“新鲜”用于食物，不说新鲜的玩具。", "树枝": "语义：树枝不能当食物，“一盘新鲜的树枝”句意不通。"}, "sentence_index": 0, "correct_answer": "果子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这学期的果子很好。", "explanation": "这里应该用〈成绩〉。“果子”指可以吃的水果，不能指学习或工作的成绩。"}, {"text": "我的表姐是一个果子。", "explanation": "这里应该用〈果农〉。“果子”指可以吃的水果，不能指种果树的人。"}, {"text": "我在饼干上抹了一层果子。", "explanation": "这里应该用〈果酱〉。“果子”就是可以吃的水果，不能像果酱那样抹在饼干上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21284, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "果子", "is_correct": true, "explanation": "正确。guǒ zi 指可以直接吃的水果。"}, {"text": "果籽", "is_correct": false, "explanation": "guǒ zǐ 与 guǒ zi 只有第二个音节声调不同（第三声与轻声），果籽指果实里的种子。"}, {"text": "谷子", "is_correct": false, "explanation": "gǔ zi 与 guǒ zi 只有第一个音节的韵母不同（u 与 uo），谷子是一种粮食作物，不是水果。"}, {"text": "箍子", "is_correct": false, "explanation": "gū zi 与 guǒ zi 第一个音节的韵母和声调都不同，箍子指套在东西外面的圈。"}], "explanations": {"果子": "正确。guǒ zi 指可以直接吃的水果。", "果籽": "guǒ zǐ 与 guǒ zi 只有第二个音节声调不同（第三声与轻声），果籽指果实里的种子。", "谷子": "gǔ zi 与 guǒ zi 只有第一个音节的韵母不同（u 与 uo），谷子是一种粮食作物，不是水果。", "箍子": "gū zi 与 guǒ zi 第一个音节的韵母和声调都不同，箍子指套在东西外面的圈。"}, "sentence_index": null, "correct_answer": "果子"}, "level_3": {"options": [{"text": "果子", "is_correct": true, "explanation": "果子指可以吃的水果，小松鼠抱着它跑上树，句意通顺。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴体积大、很重，小松鼠抱不动，也不能吃。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视太大太重，小松鼠抱不动，句意不合常理。"}, {"text": "文件", "is_correct": false, "explanation": "语义：文件是办公用的纸张资料，小松鼠不会抱着文件跑上树，句意不合常理。"}], "explanations": {"果子": "果子指可以吃的水果，小松鼠抱着它跑上树，句意通顺。", "钢琴": "语义：钢琴体积大、很重，小松鼠抱不动，也不能吃。", "电视": "语义：电视太大太重，小松鼠抱不动，句意不合常理。", "文件": "语义：文件是办公用的纸张资料，小松鼠不会抱着文件跑上树，句意不合常理。"}, "sentence_index": 6, "correct_answer": "果子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事的果子很圆满。", "explanation": "这里应该用〈结局〉。“果子”指可以吃的水果，不能指事情的结局。"}, {"text": "我午饭后习惯喝果子。", "explanation": "这里应该用〈果汁〉。“果子”是可以直接吃的水果，不能拿来喝。"}, {"text": "他的研究终于有了果子。", "explanation": "这里应该用〈成果〉。“果子”指可以吃的水果，不能指研究取得的成果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐从果园带回了一只果子。", "corrected_sentence": "姐姐从果园带回了一颗果子。", "error_description": "量词错误：“果子”应用量词“颗”（或“个”），不能用“只”。“只”多用于动物，错误形式是“一只果子”，正确形式是“一颗果子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他递给我一棵果子。", "corrected_sentence": "他递给我一个果子。", "error_description": "量词错误：“棵”用于树木、植物，果子应用“个”或“颗”，不能用“棵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
