INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21286, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很大的船，可以在海上走。", "primary_collocate": null, "pronunciation": "dà chuán", "ipa": "ta˥˩ ʈʂʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "那艘大船在海上走了三天。", "target_word": "大船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大船在海面上慢慢前进。", "target_word": "大船", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海边来了一艘白色的大船。", "target_word": "大船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐大船去了那个岛。", "target_word": "大船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子喜欢看海里的大船。", "target_word": "大船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大风来了，大船也在摇。", "target_word": "大船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想开着大船去很远的地方。", "target_word": "大船", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河太浅，大船走不了。", "target_word": "大船", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜里，大船上的灯很亮。", "target_word": "大船", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听说这艘大船去过很多国家。", "target_word": "大船", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "艘", "label": "量词"}], "register": "中性", "sense_fingerprint": "能在海上航行的很大的船", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b11de0e-cf3b-40a3-9579-0c6b07e0660f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21286, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大船", "is_correct": true, "explanation": "大船：能在海上走的很大的船，与“在海上走了三天”相符。"}, {"text": "飞船", "is_correct": false, "explanation": "语义：飞船在太空飞行，不在海上航行。"}, {"text": "飞艇", "is_correct": false, "explanation": "搭配：飞艇在空中飞，“在海上走”的说法不搭配。"}, {"text": "宇宙飞船", "is_correct": false, "explanation": "语义：宇宙飞船在太空中，不会在海上走三天。"}], "explanations": {"大船": "大船：能在海上走的很大的船，与“在海上走了三天”相符。", "飞船": "语义：飞船在太空飞行，不在海上航行。", "飞艇": "搭配：飞艇在空中飞，“在海上走”的说法不搭配。", "宇宙飞船": "语义：宇宙飞船在太空中，不会在海上走三天。"}, "sentence_index": 0, "correct_answer": "大船"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们划大船去了那个岛。", "explanation": "这里应该用〈小艇〉。大船很大，不能用手划。"}, {"text": "这辆大船上装着很多货。", "explanation": "量词错误：船只应用〈艘〉，不用〈辆〉。〈辆〉用于车辆。"}, {"text": "我们骑大船去了郊外。", "explanation": "这里应该用〈自行车〉。“骑”用于自行车等两轮车，大船不能骑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大船", "is_correct": true, "explanation": "大船：能开着去远方的大型海上船只，与“开着”搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是交通工具，“开着冰箱去很远的地方”不成立。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能开动，“开着……去”不可能。"}, {"text": "书桌", "is_correct": false, "explanation": "搭配：“开着”用于车、船、飞机等交通工具，书桌不能开。"}], "explanations": {"大船": "大船：能开着去远方的大型海上船只，与“开着”搭配。", "冰箱": "语义：冰箱不是交通工具，“开着冰箱去很远的地方”不成立。", "房子": "语义：房子不能开动，“开着……去”不可能。", "书桌": "搭配：“开着”用于车、船、飞机等交通工具，书桌不能开。"}, "sentence_index": 6, "correct_answer": "大船"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这艘大船开上了高速公路。", "explanation": "这里应该用〈汽车〉。大船只能在水上航行，不能开上公路。"}, {"text": "这艘大船飞过了太平洋。", "explanation": "这里应该用〈飞机〉。大船是水上船只，不能飞。"}, {"text": "这艘大船在铁轨上行驶。", "explanation": "这里应该用〈火车〉。大船不能在铁轨上行驶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海上突然出现了一辆大船。", "corrected_sentence": "海上突然出现了一艘大船。", "error_description": "量词错误：船只应使用量词“艘”，不能用“辆”。“辆”用于车。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们开着一张大船去了外国港口。", "corrected_sentence": "他们开着一艘大船去了外国港口。", "error_description": "量词错误：船只应使用量词“艘”，不能用“张”。“张”用于纸、桌子等有平面的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
