INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21292, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "太阳把水从东西上拿走，东西就干了。", "primary_collocate": null, "pronunciation": "shài gān", "ipa": "ʂai˥˩ kan˥", "syllable_count": 2, "sentences": [{"text": "太阳很大，地上的水很快就晒干了。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的太阳把小河晒干了。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午太阳大，衣服一会儿就晒干。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的雨水被太阳晒干了。", "target_word": "晒干", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "天气太热，池塘里的水都晒干了。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光很强，湿头发很快晒干。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种子晒干以后才能放进袋子。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来后，地面很快就晒干。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天阳光好，被子一下午就能晒干。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大太阳把树叶晒干了，一碰就碎。", "target_word": "晒干", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "晒干了", "label": "体标"}, {"form": "晒干过", "label": "体标"}], "register": "通用", "sense_fingerprint": "太阳的热把东西里的水分带走，东西变干", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b11de0e-cf3b-40a3-9579-0c6b07e0660f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晒干", "is_correct": true, "explanation": "晒干指太阳把水分带走，东西变干，与“太阳很大”相合。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：太阳很大时水不会结冰，“很快就结冰了”与语境矛盾。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：太阳很大时地上的水不会凝固，“很快就凝固了”与语境矛盾。"}, {"text": "上涨", "is_correct": false, "explanation": "语义：太阳很大时地上的水会蒸发，不会上涨。"}], "explanations": {"晒干": "晒干指太阳把水分带走，东西变干，与“太阳很大”相合。", "结冰": "语义：太阳很大时水不会结冰，“很快就结冰了”与语境矛盾。", "凝固": "语义：太阳很大时地上的水不会凝固，“很快就凝固了”与语境矛盾。", "上涨": "语义：太阳很大时地上的水会蒸发，不会上涨。"}, "sentence_index": 0, "correct_answer": "晒干"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把肉放进冰箱里晒干。", "explanation": "这里应该用〈冷冻〉。“晒干”靠阳光，冰箱里没有阳光，也不是让东西变干。"}, {"text": "他在炉子旁边把湿柴晒干。", "explanation": "这里应该用〈烘干〉。“晒干”靠太阳的热，在炉子旁边用火烤要用“烘干”。"}, {"text": "他用毛巾把脸上的水晒干。", "explanation": "这里应该用〈擦干〉。用毛巾擦脸上的水是擦，不是让水分靠阳光蒸发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晒干", "is_correct": true, "explanation": "晒干指种子晒去水分变干，才能放进袋子，与语境相合。"}, {"text": "播种", "is_correct": false, "explanation": "语义：播下去的种子不能再放进袋子，“播种以后才能放进袋子”句意不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "配价：“洗澡”是不及物动词，不能说“种子洗澡”。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：种子发芽后就不能再作种子存放，“发芽以后才能放进袋子”句意不通。"}], "explanations": {"晒干": "晒干指种子晒去水分变干，才能放进袋子，与语境相合。", "播种": "语义：播下去的种子不能再放进袋子，“播种以后才能放进袋子”句意不通。", "洗澡": "配价：“洗澡”是不及物动词，不能说“种子洗澡”。", "发芽": "语义：种子发芽后就不能再作种子存放，“发芽以后才能放进袋子”句意不通。"}, "sentence_index": 6, "correct_answer": "晒干"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用熨斗把湿衬衫晒干了。", "explanation": "这里应该用〈熨干〉。“晒干”靠阳光，用熨斗要说“熨干”。"}, {"text": "妈妈用吹风机把湿头发晒干了。", "explanation": "这里应该用〈吹干〉。“晒干”靠阳光，用吹风机要用“吹干”。"}, {"text": "厂里用低温设备把草莓晒干。", "explanation": "这里应该用〈冻干〉。“晒干”靠阳光，不用低温设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地上的水很快就晒干着。", "corrected_sentence": "地上的水很快就晒干了。", "error_description": "体标错误：“晒干”是动结式，表示已经有了结果，后面要用“了”，不能用表示持续的“着”。错误形式是“晒干着”，正确形式是“晒干了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大太阳把草地晒干得。", "corrected_sentence": "大太阳把草地晒干了。", "error_description": "结构错误：“得”须引出补语，句末“晒干得”缺少补语，结构不成立；此处应用完成体“了”，说“把草地晒干了”。错误形式是“晒干得”，正确形式是“晒干了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
