INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在店里里挑了一双袜子。", "corrected_sentence": "我在店里挑了一双袜子。", "error_description": "错误：“店里里”，多加了一个“里”。正确：“店里”。“里”已包含在“店里”之中，不能重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈店里挑了一件毛衣。", "corrected_sentence": "妈妈在店里挑了一件毛衣。", "error_description": "错误：“妈妈店里挑”，缺少介词“在”。正确：“妈妈在店里挑”。“店里”作处所状语，需用“在”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
