INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21298, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来喝水、喝牛奶的容器，上面是开口的。", "primary_collocate": null, "pronunciation": "bēi zi", "ipa": "peɪ̯˥ tsɹ̩", "syllable_count": 2, "sentences": [{"text": "我早上用杯子喝一杯牛奶。", "target_word": "杯子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子是我的，那个是你的。", "target_word": "杯子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟拿着杯子，去厨房倒水。", "target_word": "杯子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的杯子里有半杯水。", "target_word": "杯子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杯子是空的，我再去倒点水。", "target_word": "杯子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把杯子递给我，我口渴了。", "target_word": "杯子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给每个客人拿来一个杯子。", "target_word": "杯子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子口很大，很好洗。", "target_word": "杯子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家有三个杯子，都是玻璃的。", "target_word": "杯子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝完牛奶，杯子还放在桌上。", "target_word": "杯子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "上面开口、用来喝水喝牛奶的容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65ed119e-0d7b-4fd6-9dc2-f9c5d6a85cda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "筷子", "is_correct": false, "explanation": "语义：筷子不能用来盛装牛奶喝。"}, {"text": "锅", "is_correct": false, "explanation": "语义：锅是烹饪器具，不能用来喝牛奶。"}, {"text": "杯子", "is_correct": true, "explanation": "正确：“用……喝一杯牛奶”需要盛器，杯子符合句意。"}, {"text": "钥匙", "is_correct": false, "explanation": "配价：“用”引出的工具要能盛装液体，“钥匙”不能作喝牛奶的工具。"}], "explanations": {"筷子": "语义：筷子不能用来盛装牛奶喝。", "锅": "语义：锅是烹饪器具，不能用来喝牛奶。", "杯子": "正确：“用……喝一杯牛奶”需要盛器，杯子符合句意。", "钥匙": "配价：“用”引出的工具要能盛装液体，“钥匙”不能作喝牛奶的工具。"}, "sentence_index": 0, "correct_answer": "杯子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "杯子里停着一辆汽车。", "explanation": "这里应该用〈车库〉。杯子是喝水的小容器，停汽车的地方要说〈车库〉。"}, {"text": "杯子里腌着白菜。", "explanation": "这里应该用〈水缸〉。杯子装不下整棵白菜，腌菜要用〈水缸〉。"}, {"text": "杯子里养着一只小鸟。", "explanation": "这里应该用〈鸟笼〉。杯子不能用来养鸟，养鸟要用〈鸟笼〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风", "is_correct": false, "explanation": "语义：“风”不是能被拿来给客人的具体物件。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“拿来一个”后要接具体物件，“天气”不能被拿取或计量。"}, {"text": "杯子", "is_correct": true, "explanation": "正确：“拿来一个”后接可拿取的器物，杯子符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能被拿来给客人，句意不通。"}], "explanations": {"风": "语义：“风”不是能被拿来给客人的具体物件。", "天气": "搭配：“拿来一个”后要接具体物件，“天气”不能被拿取或计量。", "杯子": "正确：“拿来一个”后接可拿取的器物，杯子符合句意。", "月亮": "语义：月亮不能被拿来给客人，句意不通。"}, "sentence_index": 6, "correct_answer": "杯子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用杯子削苹果。", "explanation": "这里应该用〈水果刀〉。杯子不能用来削苹果。"}, {"text": "他用杯子擦鞋。", "explanation": "这里应该用〈鞋刷〉。杯子不能用来擦鞋。"}, {"text": "他用杯子切菜。", "explanation": "这里应该用〈菜刀〉。杯子不能用来切菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了两张杯子。", "corrected_sentence": "我买了两个杯子。", "error_description": "“杯子”的量词应为“个”或“只”，“张”用于平面物，不能用于杯子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把杯子擦干净着。", "corrected_sentence": "妈妈把杯子擦干净了。", "error_description": "“擦干净”表示动作完成并出现结果，应用“了”；“着”表示动作持续，不能用于此句，应写作“妈妈把杯子擦干净了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
