INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21300, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把水或别的液体从嘴巴里吞下去。", "primary_collocate": null, "pronunciation": "hē", "ipa": "xɤ˥", "syllable_count": 1, "sentences": [{"text": "我早上喜欢喝一杯热牛奶。", "target_word": "喝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很热，你多喝水吧。", "target_word": "喝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喝咖啡，只喝茶。", "target_word": "喝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在喝果汁。", "target_word": "喝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喝过中国的绿茶吗？", "target_word": "喝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边看书，一边喝着茶。", "target_word": "喝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭的时候我常常喝汤。", "target_word": "喝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我渴了，想喝点儿东西。", "target_word": "喝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我睡觉以前喝牛奶。", "target_word": "喝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一瓶水都喝完了。", "target_word": "喝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喝了", "label": "体标"}, {"form": "喝着", "label": "体标"}, {"form": "喝过", "label": "体标"}, {"form": "喝喝", "label": "重叠"}], "register": "口语", "sense_fingerprint": "把液体从嘴里咽下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4208b8-fa3e-439a-94ca-4737d9934ac5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喝", "is_correct": true, "explanation": "喝（hē）：把水或别的液体咽下去。"}, {"text": "河", "is_correct": false, "explanation": "hé（第二声）与 hē（第一声）声调不同，意思是河流。"}, {"text": "哈", "is_correct": false, "explanation": "hā 与 hē 韵母不同，意思是哈哈的笑声或呼气。"}, {"text": "黑", "is_correct": false, "explanation": "hēi 比 hē 多一个韵母 i，意思是黑色。"}, {"text": "贺", "is_correct": false, "explanation": "hè（第四声）与 hē（第一声）声调不同，意思是祝贺。"}], "explanations": {"喝": "喝（hē）：把水或别的液体咽下去。", "河": "hé（第二声）与 hē（第一声）声调不同，意思是河流。", "哈": "hā 与 hē 韵母不同，意思是哈哈的笑声或呼气。", "黑": "hēi 比 hē 多一个韵母 i，意思是黑色。", "贺": "hè（第四声）与 hē（第一声）声调不同，意思是祝贺。"}, "sentence_index": null, "correct_answer": "喝"}, "level_3": {"options": [{"text": "穿", "is_correct": false, "explanation": "搭配：“穿”只用于衣服鞋袜等，不能说“穿一杯热牛奶”。"}, {"text": "喝", "is_correct": true, "explanation": "正确。“喜欢喝一杯热牛奶”指把牛奶咽下去，符合句意。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象要能清洗，牛奶不能说“洗”。"}, {"text": "读", "is_correct": false, "explanation": "语义：牛奶不能用“读”，句子意思说不通。"}], "explanations": {"穿": "搭配：“穿”只用于衣服鞋袜等，不能说“穿一杯热牛奶”。", "喝": "正确。“喜欢喝一杯热牛奶”指把牛奶咽下去，符合句意。", "洗": "搭配：“洗”的对象要能清洗，牛奶不能说“洗”。", "读": "语义：牛奶不能用“读”，句子意思说不通。"}, "sentence_index": 0, "correct_answer": "喝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他饿了，喝了一块饼干。", "explanation": "这里应该用〈吃〉。饼干是固体食物，要说“吃”，不说“喝”。"}, {"text": "他站在门口喝烟。", "explanation": "这里应该用〈抽〉。吸烟要说“抽烟”，“喝”只用于液体，不能用来指吸烟。"}, {"text": "妈妈喝了一口苹果。", "explanation": "这里应该用〈咬〉。咬一口固体食物要说“咬”，“喝”只用于液体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21300, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "喝", "is_correct": true, "explanation": "喝（hē）：把水或别的液体咽下去。"}, {"text": "盒", "is_correct": false, "explanation": "hé（第二声）与 hē（第一声）声调不同，意思是盒子。"}, {"text": "嘿", "is_correct": false, "explanation": "hēi 比 hē 多一个韵母 i，意思是打招呼的感叹语。"}, {"text": "嗨", "is_correct": false, "explanation": "hāi 与 hē 韵母不同，意思是打招呼的口语。"}], "explanations": {"喝": "喝（hē）：把水或别的液体咽下去。", "盒": "hé（第二声）与 hē（第一声）声调不同，意思是盒子。", "嘿": "hēi 比 hē 多一个韵母 i，意思是打招呼的感叹语。", "嗨": "hāi 与 hē 韵母不同，意思是打招呼的口语。"}, "sentence_index": null, "correct_answer": "喝"}, "level_3": {"options": [{"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于桌面、地板等，不能说“擦汤”。"}, {"text": "喝", "is_correct": true, "explanation": "正确。“常常喝汤”指把汤咽下去，符合句意。"}, {"text": "踢", "is_correct": false, "explanation": "语义：汤是液体，不能被踢。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”的对象要能悬挂，汤不能说“挂”。"}], "explanations": {"擦": "搭配：“擦”用于桌面、地板等，不能说“擦汤”。", "喝": "正确。“常常喝汤”指把汤咽下去，符合句意。", "踢": "语义：汤是液体，不能被踢。", "挂": "搭配：“挂”的对象要能悬挂，汤不能说“挂”。"}, "sentence_index": 6, "correct_answer": "喝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小狗喝了一根骨头。", "explanation": "这里应该用〈啃〉。骨头要用“啃”，“喝”只用于液体。"}, {"text": "老人慢慢地喝着饭。", "explanation": "这里应该用〈嚼〉。饭是固体，要说“嚼”，不能说“喝”。"}, {"text": "宝宝喝着一颗糖。", "explanation": "这里应该用〈含〉。糖放在嘴里不咽下去要说“含”，不说“喝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他喝很快。", "corrected_sentence": "他喝得很快。", "error_description": "错误形式：“喝很快”；正确形式：“喝得很快”。说明动作的方式要用“得”引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喝了过这种茶。", "corrected_sentence": "我喝过这种茶。", "error_description": "错误形式：“喝了过”；正确形式：“喝过”。“过”表示曾经有过的经历，不能与“了”一起用在同一动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
