INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把种子放到土里，让它长大。", "primary_collocate": null, "pronunciation": "zhòng zhí", "ipa": "ʈʂʊŋ˥˩ ʈʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "农民在山坡上种植了很多茶树。", "target_word": "种植", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家院子里种植着几棵苹果树。", "target_word": "种植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区适合种植水稻。", "target_word": "种植", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想在阳台上种植一些辣椒。", "target_word": "种植", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷每年春天都种植玉米。", "target_word": "种植", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "种植蔬菜需要充足的阳光和水。", "target_word": "种植", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的人们种植过很多年的棉花。", "target_word": "种植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在这片荒地上种植花生。", "target_word": "种植", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校让学生在花园里种植花草。", "target_word": "种植", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方冬天太冷，不能种植香蕉。", "target_word": "种植", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种植了", "label": "体标"}, {"form": "种植着", "label": "体标"}, {"form": "种植过", "label": "体标"}, {"form": "种植业", "label": "复合"}, {"form": "种植园", "label": "复合"}], "register": "中性", "sense_fingerprint": "把种子或苗放进土里培育植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7679ce6-7410-49f6-bfdd-e5891d0d533a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "种植", "is_correct": true, "explanation": "种植：把种子放到土里，让它长大。"}, {"text": "中值", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，zhí 相同，意思是一组数的中间值。"}, {"text": "忠直", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，zhí 相同，意思是忠诚正直。"}, {"text": "中止", "is_correct": false, "explanation": "两个音节的声调都不同：zhōng（第一声）、zhǐ（第三声），意思是中途停止。"}, {"text": "宗旨", "is_correct": false, "explanation": "zōng（第一声）声母 z 与 zh 不同，zhǐ 声调不同（第三声），意思是主要的目的或原则。"}], "explanations": {"种植": "种植：把种子放到土里，让它长大。", "中值": "zhòng（第四声）与 zhōng（第一声）声调不同，zhí 相同，意思是一组数的中间值。", "忠直": "zhòng（第四声）与 zhōng（第一声）声调不同，zhí 相同，意思是忠诚正直。", "中止": "两个音节的声调都不同：zhōng（第一声）、zhǐ（第三声），意思是中途停止。", "宗旨": "zōng（第一声）声母 z 与 zh 不同，zhǐ 声调不同（第三声），意思是主要的目的或原则。"}, "sentence_index": null, "correct_answer": "种植"}, "level_3": {"options": [{"text": "种植", "is_correct": true, "explanation": "种植：把种子或苗放进土里培育植物，此处指种茶树，与“茶树”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是可食用的东西，茶树不能吃。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”的对象是文字，不能写茶树。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展品，不说“参观茶树”。"}], "explanations": {"种植": "种植：把种子或苗放进土里培育植物，此处指种茶树，与“茶树”相合。", "吃": "语义：“吃”的对象是可食用的东西，茶树不能吃。", "写": "语义：“写”的对象是文字，不能写茶树。", "参观": "搭配：“参观”的对象是场所或展品，不说“参观茶树”。"}, "sentence_index": 0, "correct_answer": "种植"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想在家里种植一些金鱼。", "explanation": "这里应该用〈养〉。种植用于植物，金鱼等动物要说养。"}, {"text": "这家工厂每天种植两千台电脑。", "explanation": "这里应该用〈制造〉。种植指把种子或苗栽进土里，工厂生产的电脑不能种植，应说制造。"}, {"text": "实验室里种植了很多细菌。", "explanation": "这里应该用〈培养〉。种植用于植物，细菌等微生物要说培养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21304, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "种植", "is_correct": true, "explanation": "种植：把种子放到土里，让它长大。"}, {"text": "中指", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，zhí（第二声）与 zhǐ（第三声）声调也不同，意思是手的中指。"}, {"text": "总值", "is_correct": false, "explanation": "zhòng 与 zǒng 的声母不同（zh 与 z），声调也不同（第四声与第三声），意思是总的价值。"}, {"text": "中职", "is_correct": false, "explanation": "zhòng 与 zhōng 声调不同（第四声与第一声），意思是中等职业学校。"}], "explanations": {"种植": "种植：把种子放到土里，让它长大。", "中指": "zhòng（第四声）与 zhōng（第一声）声调不同，zhí（第二声）与 zhǐ（第三声）声调也不同，意思是手的中指。", "总值": "zhòng 与 zǒng 的声母不同（zh 与 z），声调也不同（第四声与第三声），意思是总的价值。", "中职": "zhòng 与 zhōng 声调不同（第四声与第一声），意思是中等职业学校。"}, "sentence_index": null, "correct_answer": "种植"}, "level_3": {"options": [{"text": "种植", "is_correct": true, "explanation": "种植：把种子或苗放进土里培育植物，此处指种棉花，与“棉花”相合。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不说“喝棉花”。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理器物，棉花是作物，不能被修理。"}, {"text": "说", "is_correct": false, "explanation": "搭配：“说”的对象是话语或语言，不说“说棉花”。"}], "explanations": {"种植": "种植：把种子或苗放进土里培育植物，此处指种棉花，与“棉花”相合。", "喝": "搭配：“喝”的对象是饮品，不说“喝棉花”。", "修": "语义：“修”指修理器物，棉花是作物，不能被修理。", "说": "搭配：“说”的对象是话语或语言，不说“说棉花”。"}, "sentence_index": 6, "correct_answer": "种植"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都种植她的孩子。", "explanation": "这里应该用〈抚养〉。“种植”的对象是植物，人要说抚养。"}, {"text": "他把这本书种植在书架上。", "explanation": "这里应该用〈放〉。“种植”指把种子或苗栽进土里，书不能被种植。"}, {"text": "他在公司种植了一个电脑程序。", "explanation": "这里应该用〈编写〉。“种植”的对象是植物，电脑程序要说编写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天在菜园里种植了白菜。", "corrected_sentence": "我们明天在菜园里种植白菜。", "error_description": "“明天”表示还没发生的事，“种植”后不能用表示完成的“了”，应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在阳台上种植了蔬菜。", "corrected_sentence": "他正在阳台上种植蔬菜。", "error_description": "“正在”表示动作进行中，不与“了”同用，应删去“了”，说“正在阳台上种植蔬菜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
