INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21306, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "从哪里来", "primary_collocate": null, "pronunciation": "lái zì", "ipa": "lai˧˥ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "我的朋友来自法国。", "target_word": "来自", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你来自哪个城市？", "target_word": "来自", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些苹果来自山东。", "target_word": "来自", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她来自一个很小的村子。", "target_word": "来自", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这封信来自我的老同学。", "target_word": "来自", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们来自不同的国家，说不同的话。", "target_word": "来自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个好消息来自我哥哥。", "target_word": "来自", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们班有几个同学来自南方。", "target_word": "来自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种茶叶来自云南，很有名。", "target_word": "来自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的快乐来自家人的爱。", "target_word": "来自", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "来自于", "label": "复合"}], "register": "中性", "sense_fingerprint": "出处或来源是某地、某人或某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7679ce6-7410-49f6-bfdd-e5891d0d533a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来自", "is_correct": true, "explanation": "来自：表示人或事物的来源，与“我的朋友”“法国”搭配，符合句意。"}, {"text": "盛产", "is_correct": false, "explanation": "搭配：“盛产”要接物产，不能指人，“我的朋友盛产法国”说不通。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示迎接，不能把国家名当作人的来源，句子说不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是转换语言，不能接国家名作宾语，“翻译法国”说不通。"}], "explanations": {"来自": "来自：表示人或事物的来源，与“我的朋友”“法国”搭配，符合句意。", "盛产": "搭配：“盛产”要接物产，不能指人，“我的朋友盛产法国”说不通。", "欢迎": "语义：“欢迎”表示迎接，不能把国家名当作人的来源，句子说不通。", "翻译": "语义：“翻译”是转换语言，不能接国家名作宾语，“翻译法国”说不通。"}, "sentence_index": 0, "correct_answer": "来自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上海的朋友明天来自我家。", "explanation": "这里应该用〈来到〉。来自表示从某处而来，指起点；表示到达某处要用“来到”。"}, {"text": "李老师来自一九八〇年。", "explanation": "这里应该用〈生于〉。说某人出生在哪一年要用“生于”；“来自”表示人或事物的来源，不用来说人的出生年份。"}, {"text": "这个好消息来自我的耳朵。", "explanation": "这里应该用〈传到〉。“来自”表示事物从人或地方而来，耳朵不是消息的来源；好消息是传到耳朵里的，应说“这个好消息传到我的耳朵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产", "is_correct": false, "explanation": "语义：“生产”的对象是物品，消息不能生产人，“这个好消息生产我哥哥”说不通。"}, {"text": "赢得", "is_correct": false, "explanation": "搭配：“赢得”接比赛、奖项，不能接“哥哥”，句子说不通。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”针对可以量度的事物，消息不能测量人，句子说不通。"}, {"text": "来自", "is_correct": true, "explanation": "来自：表示消息的来源是“我哥哥”，与句意相符。"}], "explanations": {"生产": "语义：“生产”的对象是物品，消息不能生产人，“这个好消息生产我哥哥”说不通。", "赢得": "搭配：“赢得”接比赛、奖项，不能接“哥哥”，句子说不通。", "测量": "语义：“测量”针对可以量度的事物，消息不能测量人，句子说不通。", "来自": "来自：表示消息的来源是“我哥哥”，与句意相符。"}, "sentence_index": 6, "correct_answer": "来自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈来自这份礼物。", "explanation": "这里是主客颠倒。“来自”表示事物从人或地方而来，应说“这份礼物来自妈妈”，不能说“妈妈来自这份礼物”。"}, {"text": "他来自医生，每天都很忙。", "explanation": "这里应该用〈当〉。来自后面要接人、地点或事物，不能接职业；说他当了医生要用“当”。"}, {"text": "这份礼物来自十块钱。", "explanation": "这里应该用〈花〉。来自要接人、地点或事物，不能接钱数；说花了多少钱要用“花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的同事来自了上海。", "corrected_sentence": "我的同事来自上海。", "error_description": "错误：“来自”表示来源，是静态的，后面不能加表示完成的“了”，应说“我的同事来自上海”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份礼物来自过妈妈。", "corrected_sentence": "这份礼物来自妈妈。", "error_description": "错误：“来自”后面不能加“过”，应说“这份礼物来自妈妈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
