INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个地方，就是指某个位置或区域。", "primary_collocate": null, "pronunciation": "dì fang", "ipa": "ti˥˩ fɑŋ", "syllable_count": 2, "sentences": [{"text": "这个地方很漂亮。", "target_word": "地方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你住在什么地方？", "target_word": "地方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想去一个安静的地方。", "target_word": "地方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里是个好地方。", "target_word": "地方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "北京有很多好玩的地方。", "target_word": "地方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个地方太小，坐不下十个人。", "target_word": "地方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我找不到可以停车的地方。", "target_word": "地方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我们去了一个没人的地方。", "target_word": "地方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把书放在一个很容易找到的地方。", "target_word": "地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去过很多国家，最喜欢海边的小地方。", "target_word": "地方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个地方", "label": "量词：个"}, {"form": "小地方", "label": "复合"}], "register": "中性", "sense_fingerprint": "地方|某个位置或区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e7fa8c-7e28-4a9f-9f73-de782ccd99f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21308, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地方", "is_correct": true, "explanation": "正确答案：地方（dì fang），指某个位置或区域。"}, {"text": "大方", "is_correct": false, "explanation": "韵母不同：“大”（dà）与“地”（dì）的韵母 a 与 i 不同，“大方”意思是不小气、举止自然。"}, {"text": "比方", "is_correct": false, "explanation": "声母与声调不同：“比”（bǐ，第三声）与“地”（dì，第四声）不同，“比方”意思是比如。"}, {"text": "立方", "is_correct": false, "explanation": "声母不同：“立”（lì）与“地”（dì）的声母 l 与 d 不同，“立方”意思是立方、立方米。"}, {"text": "敌方", "is_correct": false, "explanation": "声调不同：“敌”（dí，第二声）与“地”（dì，第四声）不同，“敌方”意思是敌对的一方。"}], "explanations": {"地方": "正确答案：地方（dì fang），指某个位置或区域。", "大方": "韵母不同：“大”（dà）与“地”（dì）的韵母 a 与 i 不同，“大方”意思是不小气、举止自然。", "比方": "声母与声调不同：“比”（bǐ，第三声）与“地”（dì，第四声）不同，“比方”意思是比如。", "立方": "声母不同：“立”（lì）与“地”（dì）的声母 l 与 d 不同，“立方”意思是立方、立方米。", "敌方": "声调不同：“敌”（dí，第二声）与“地”（dì，第四声）不同，“敌方”意思是敌对的一方。"}, "sentence_index": null, "correct_answer": "地方"}, "level_3": {"options": [{"text": "地方", "is_correct": true, "explanation": "正确答案：“这个地方很漂亮”中的“地方”指可以看的位置或区域。"}, {"text": "问题", "is_correct": false, "explanation": "语义：“问题”不是可以“漂亮”的事物，与“很漂亮”冲突。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“漂亮”通常形容外貌、景色等，不修饰“时间”。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是一种活动，不能说“很漂亮”，与句中的描述冲突。"}], "explanations": {"地方": "正确答案：“这个地方很漂亮”中的“地方”指可以看的位置或区域。", "问题": "语义：“问题”不是可以“漂亮”的事物，与“很漂亮”冲突。", "时间": "搭配：“漂亮”通常形容外貌、景色等，不修饰“时间”。", "考试": "语义：考试是一种活动，不能说“很漂亮”，与句中的描述冲突。"}, "sentence_index": 0, "correct_answer": "地方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在学习地方很努力。", "explanation": "这里应该用〈方面〉。“在……方面”表示领域，“学习方面”是固定说法；“地方”指位置，不能放在“学习”后面表示领域。"}, {"text": "他在公司的地方很高。", "explanation": "这里应该用〈地位〉。“地位”指一个人在组织中的身份和重要性；“地方”指位置，不能用“很高”形容他在公司的身份。"}, {"text": "他用这种地方解决了问题。", "explanation": "这里应该用〈方式〉。“用……方式”表示做事的办法；“地方”指位置，不能作为解决问题的办法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21308, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "地方", "is_correct": true, "explanation": "正确答案：地方（dì fang），指某个位置或区域。"}, {"text": "西方", "is_correct": false, "explanation": "声母与声调不同：“西”（xī）与“地”（dì）的声母 x 与 d 不同，“西方”意思是西边、西方国家。"}, {"text": "对方", "is_correct": false, "explanation": "韵母不同：“对”（duì）比“地”（dì）多一个 u，“对方”意思是另一方、对手。"}, {"text": "你方", "is_correct": false, "explanation": "声母不同：“你”（nǐ）与“地”（dì）的声母 n 与 d 不同，“你方”意思是你们一方。"}, {"text": "德方", "is_correct": false, "explanation": "韵母不同：“德”（dé）与“地”（dì）的韵母 e 与 i 不同，“德方”意思是德国一方。"}], "explanations": {"地方": "正确答案：地方（dì fang），指某个位置或区域。", "西方": "声母与声调不同：“西”（xī）与“地”（dì）的声母 x 与 d 不同，“西方”意思是西边、西方国家。", "对方": "韵母不同：“对”（duì）比“地”（dì）多一个 u，“对方”意思是另一方、对手。", "你方": "声母不同：“你”（nǐ）与“地”（dì）的声母 n 与 d 不同，“你方”意思是你们一方。", "德方": "韵母不同：“德”（dé）与“地”（dì）的韵母 e 与 i 不同，“德方”意思是德国一方。"}, "sentence_index": null, "correct_answer": "地方"}, "level_3": {"options": [{"text": "地方", "is_correct": true, "explanation": "正确答案：“可以停车的地方”中的“地方”指场所。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能“可以停车”，与“可以停车的”冲突。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是场所，不能作“可以停车的”所修饰的对象。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“可以停车的”修饰场所或事物，不修饰人。"}], "explanations": {"地方": "正确答案：“可以停车的地方”中的“地方”指场所。", "电脑": "语义：电脑不能“可以停车”，与“可以停车的”冲突。", "钥匙": "语义：钥匙不是场所，不能作“可以停车的”所修饰的对象。", "老师": "搭配：“可以停车的”修饰场所或事物，不修饰人。"}, "sentence_index": 6, "correct_answer": "地方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议地方定在北京。", "explanation": "这里应该用〈地点〉。“地点”指会议、活动所在的场所，“地方”不能直接修饰“会议”。"}, {"text": "球掉在地方上了。", "explanation": "这里应该用〈地面〉。“掉在地面上”指落到地上；“地方上”指某个地区，不能表示落在地表。"}, {"text": "事情糟糕到了这种地方。", "explanation": "这里应该用〈地步〉。“到……地步”表示程度；“地方”指空间位置，不能表示程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在这里找到了一只适合学习的地方。", "corrected_sentence": "他在这里找到了一个适合学习的地方。", "error_description": "量词错误：“地方”应该用量词“个”，“只”常用于动物或某些器物，不能用来计量“地方”。应说“一个适合学习的地方”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她找到了一个能休息地方。", "corrected_sentence": "她找到了一个能休息的地方。", "error_description": "“的”缺失：修饰“地方”的动词短语“能休息”后面要加“的”，应说“能休息的地方”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
