INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21312, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指地球上靠近赤道、一年四季都很热的地区。", "primary_collocate": null, "pronunciation": "rè dài dì qū", "ipa": "ʐɤ˥˩ taɪ˥˩ ti˥˩ tɕʰy˥", "syllable_count": 4, "sentences": [{"text": "热带地区一年四季都像夏天。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天我们这里很冷，热带地区却很暖和。", "target_word": "热带地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那种大鸟住在热带地区的森林里。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热带地区的太阳特别大。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "赤道附近是热带地区。", "target_word": "热带地区", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师在地图上指出热带地区。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去热带地区旅行要带防晒霜。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热带地区的孩子不知道雪是什么。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个岛在热带地区，所以冬天也能游泳。", "target_word": "热带地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "椰子树多长在热带地区。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "熱帶地區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地球上一年四季都很热的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b265e353-0a56-4f5b-a790-095a42c113c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21312, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热带地区", "is_correct": true, "explanation": "正确。“一年四季都像夏天”描述热带地区的气候，符合句意。"}, {"text": "寒带", "is_correct": false, "explanation": "语义：寒带一年四季寒冷，与“像夏天”的语境冲突。"}, {"text": "极地", "is_correct": false, "explanation": "语义：极地常年低温，与“一年四季都像夏天”矛盾。"}, {"text": "北极", "is_correct": false, "explanation": "搭配：“一年四季都像夏天”不用来形容北极，搭配不当。"}], "explanations": {"热带地区": "正确。“一年四季都像夏天”描述热带地区的气候，符合句意。", "寒带": "语义：寒带一年四季寒冷，与“像夏天”的语境冲突。", "极地": "语义：极地常年低温，与“一年四季都像夏天”矛盾。", "北极": "搭配：“一年四季都像夏天”不用来形容北极，搭配不当。"}, "sentence_index": 0, "correct_answer": "热带地区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "热带地区是一条假想的线。", "explanation": "这里应该用〈赤道〉。赤道才是一条假想的线，热带地区是一片有范围的地区，不能说成线。"}, {"text": "他在热带地区过了三年，每年冬天都要铲雪。", "explanation": "这里应该用〈寒带地区〉。热带地区气温高、很少下雪，不用铲雪；每年冬天都要铲雪的是寒带地区。"}, {"text": "热带地区终年积雪。", "explanation": "这里应该用〈雪山地区〉。雪山地区终年积雪，热带地区气温较高，不会积雪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热带地区", "is_correct": true, "explanation": "正确。“去…旅行要带防晒霜”指阳光强烈的地方，热带地区符合句意。"}, {"text": "地下室", "is_correct": false, "explanation": "语义：地下室没有阳光，不需要防晒霜，与句意冲突。"}, {"text": "冰窖", "is_correct": false, "explanation": "语义：冰窖阴冷无阳光，与“防晒霜”的语境冲突。"}, {"text": "海底", "is_correct": false, "explanation": "搭配：“去海底旅行”并不常说，且“要带防晒霜”与海底环境不搭配。"}], "explanations": {"热带地区": "正确。“去…旅行要带防晒霜”指阳光强烈的地方，热带地区符合句意。", "地下室": "语义：地下室没有阳光，不需要防晒霜，与句意冲突。", "冰窖": "语义：冰窖阴冷无阳光，与“防晒霜”的语境冲突。", "海底": "搭配：“去海底旅行”并不常说，且“要带防晒霜”与海底环境不搭配。"}, "sentence_index": 6, "correct_answer": "热带地区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "椰子树多长在寒冷的热带地区。", "explanation": "“寒冷”与“热带地区”矛盾：热带地区气温较高，不能说寒冷。"}, {"text": "椰子树多长在热带地区，冬天常常下大雪。", "explanation": "“冬天常常下大雪”与热带地区的气候矛盾：热带地区气温较高，不会常下大雪。"}, {"text": "椰子树多长在热带地区，夏天人们都穿羽绒服。", "explanation": "“夏天穿羽绒服”与热带夏天炎热的气候矛盾，热带地区不会这样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去过一颗热带地区，那里很美。", "corrected_sentence": "我们去过一个热带地区，那里很美。", "error_description": "量词错误：“热带地区”前应用“个”，“颗”用于小而圆的东西，不能用于地区。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去一条热带地区旅行要带防晒霜。", "corrected_sentence": "去一个热带地区旅行要带防晒霜。", "error_description": "量词错误：“热带地区”前应用“个”，“条”用于细长的东西，不能用于地区。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21314, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "寒冷", "is_correct": true, "explanation": "“寒冷”与“温暖”在指温度时构成反义关系，指气温低、使人感到冷。"}, {"text": "复杂", "is_correct": false, "explanation": "与“温暖”没有反义或近义关系，“复杂”形容事物头绪多、难理清。"}, {"text": "清楚", "is_correct": false, "explanation": "与“温暖”没有反义或近义关系，“清楚”形容明白、不模糊。"}, {"text": "迅速", "is_correct": false, "explanation": "与“温暖”没有反义或近义关系，“迅速”形容速度快。"}], "correct_answer": "寒冷", "explanations": {"寒冷": "“寒冷”与“温暖”在指温度时构成反义关系，指气温低、使人感到冷。", "复杂": "与“温暖”没有反义或近义关系，“复杂”形容事物头绪多、难理清。", "清楚": "与“温暖”没有反义或近义关系，“清楚”形容明白、不模糊。", "迅速": "与“温暖”没有反义或近义关系，“迅速”形容速度快。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21314, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "寒冷", "is_correct": true, "explanation": "“寒冷”与“温暖”在指温度时构成反义关系，指气温低、使人感到冷。"}, {"text": "粗糙", "is_correct": false, "explanation": "与“温暖”没有反义或近义关系，“粗糙”形容表面不光滑。"}, {"text": "严肃", "is_correct": false, "explanation": "与“温暖”没有反义或近义关系，“严肃”形容态度郑重、不轻松。"}, {"text": "迟钝", "is_correct": false, "explanation": "与“温暖”没有反义或近义关系，“迟钝”形容反应慢。"}], "correct_answer": "寒冷", "explanations": {"寒冷": "“寒冷”与“温暖”在指温度时构成反义关系，指气温低、使人感到冷。", "粗糙": "与“温暖”没有反义或近义关系，“粗糙”形容表面不光滑。", "严肃": "与“温暖”没有反义或近义关系，“严肃”形容态度郑重、不轻松。", "迟钝": "与“温暖”没有反义或近义关系，“迟钝”形容反应慢。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21314, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "温暖就是不冷不热，让人感到很舒服。", "primary_collocate": null, "pronunciation": "wēn nuǎn", "ipa": "wən˥ nwan˨˩", "syllable_count": 2, "sentences": [{"text": "春天来了，天气越来越温暖。", "target_word": "温暖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里很温暖，一点儿也不冷。", "target_word": "温暖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天太阳很大，风也很温暖。", "target_word": "温暖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件毛衣又软又温暖。", "target_word": "温暖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢温暖的阳光。", "target_word": "温暖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "南方的冬天比北方温暖。", "target_word": "温暖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "被子很厚，睡起来很温暖。", "target_word": "温暖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的天气温暖又舒服。", "target_word": "温暖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把手放进温暖的水里。", "target_word": "温暖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条围巾很温暖，你戴上吧。", "target_word": "温暖", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "温暖的", "label": "定语形式"}, {"form": "很温暖", "label": "程度搭配"}, {"form": "溫暖", "label": "繁体"}], "register": "中性", "sense_fingerprint": "天气、房间、衣物等不冷不热、让人舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bc8be5-758a-4101-a27b-8c54507243b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温暖", "is_correct": true, "explanation": "“温暖”指天气不冷不热、让人舒服，符合春天天气转暖的语境。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：春天来了，天气应该越来越暖，“冰冷”与季节转暖的语境相反。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”形容价格低，不能用来形容天气。"}, {"text": "刺骨", "is_correct": false, "explanation": "搭配：“刺骨”形容寒风或冷水的感觉，不能用来修饰“天气越来越”这种逐渐变化。"}], "explanations": {"温暖": "“温暖”指天气不冷不热、让人舒服，符合春天天气转暖的语境。", "冰冷": "语义：春天来了，天气应该越来越暖，“冰冷”与季节转暖的语境相反。", "便宜": "搭配：“便宜”形容价格低，不能用来形容天气。", "刺骨": "搭配：“刺骨”形容寒风或冷水的感觉，不能用来修饰“天气越来越”这种逐渐变化。"}, "sentence_index": 0, "correct_answer": "温暖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子很温暖，两个大人都搬不动。", "explanation": "这里应该用〈沉重〉。温暖只表示不冷不热、舒服的温度，不能用来形容箱子的重量。"}, {"text": "冰箱里拿出来的饮料很温暖，喝一口很爽。", "explanation": "这里应该用〈冰凉〉。饮料从冰箱拿出来是凉的，“温暖”表示不冷不热的舒适温度，不能用来形容冰凉的饮料。"}, {"text": "夏天的中午非常温暖，大家都不出门。", "explanation": "这里应该用〈炎热〉。温暖表示不冷不热、舒服的温度，不能形容夏天中午的高温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温暖", "is_correct": true, "explanation": "“温暖”指被子厚、睡起来不冷不热、很舒服，与句意一致。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能用来形容睡觉时被子带来的感觉。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容坡度，不能用来形容睡起来的感觉。"}, {"text": "严寒", "is_correct": false, "explanation": "语义：“严寒”指极冷，与“被子很厚”的语境矛盾。"}], "explanations": {"温暖": "“温暖”指被子厚、睡起来不冷不热、很舒服，与句意一致。", "响亮": "搭配：“响亮”形容声音，不能用来形容睡觉时被子带来的感觉。", "陡峭": "搭配：“陡峭”形容坡度，不能用来形容睡起来的感觉。", "严寒": "语义：“严寒”指极冷，与“被子很厚”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "温暖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冰块摸起来很温暖。", "explanation": "这里应该用〈冰凉〉。冰块是冷的，“温暖”表示不冷不热的舒适温度，不能用来形容冰块。"}, {"text": "正午的沙漠温暖难耐。", "explanation": "这里应该用〈酷热〉。正午沙漠的高温应该用“酷热”，“温暖”不能形容这种极端高温。"}, {"text": "山顶的夜晚非常温暖。", "explanation": "这里应该用〈寒冷〉。山顶夜晚的低温应该用“寒冷”，“温暖”不能用于这种低温环境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬天的被窝很很温暖。", "corrected_sentence": "冬天的被窝很温暖。", "error_description": "重复副词：程度副词“很”只用一次，修饰形容词“温暖”。错误形式是“很很温暖”，正确形式是“很温暖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一件温暖毛衣。", "corrected_sentence": "这是一件温暖的毛衣。", "error_description": "助词缺失：形容词“温暖”修饰名词“毛衣”时要加“的”。错误形式是“温暖毛衣”，正确形式是“温暖的毛衣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21316, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "干燥", "is_correct": true, "explanation": "正确。“干燥”与“湿润”是反义词，指没有水分、摸起来不湿。"}, {"text": "明亮", "is_correct": false, "explanation": "不构成反义：“明亮”描述光线，与水分无关。"}, {"text": "温暖", "is_correct": false, "explanation": "不构成反义：“温暖”描述温度，与含水状态不对立。"}, {"text": "坚硬", "is_correct": false, "explanation": "不构成反义：“坚硬”描述质地，与是否含水无关。"}], "correct_answer": "干燥", "explanations": {"干燥": "正确。“干燥”与“湿润”是反义词，指没有水分、摸起来不湿。", "明亮": "不构成反义：“明亮”描述光线，与水分无关。", "温暖": "不构成反义：“温暖”描述温度，与含水状态不对立。", "坚硬": "不构成反义：“坚硬”描述质地，与是否含水无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21316, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "干燥", "is_correct": true, "explanation": "正确。“干燥”与“湿润”是反义词，指没有水分。"}, {"text": "整洁", "is_correct": false, "explanation": "不构成反义：“整洁”描述干净整齐，与含水量无关。"}, {"text": "柔软", "is_correct": false, "explanation": "不构成反义：“柔软”描述质地，与是否含水不对立。"}, {"text": "冰凉", "is_correct": false, "explanation": "不构成反义：“冰凉”描述温度感受，与水分状态无关。"}], "correct_answer": "干燥", "explanations": {"干燥": "正确。“干燥”与“湿润”是反义词，指没有水分。", "整洁": "不构成反义：“整洁”描述干净整齐，与含水量无关。", "柔软": "不构成反义：“柔软”描述质地，与是否含水不对立。", "冰凉": "不构成反义：“冰凉”描述温度感受，与水分状态无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21316, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西有水分，不干。", "primary_collocate": null, "pronunciation": "shī rùn", "ipa": "ʂɨ˥ ʐwən˥˩", "syllable_count": 2, "sentences": [{"text": "早上的草很湿润。", "target_word": "湿润", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里的空气湿润，不太干。", "target_word": "湿润", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后的土地很湿润。", "target_word": "湿润", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请用湿润的布擦桌子。", "target_word": "湿润", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "花需要湿润的土。", "target_word": "湿润", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冬天要多喝水，让嘴唇保持湿润。", "target_word": "湿润", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的风又凉又湿润。", "target_word": "湿润", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "蛋糕做得很湿润，很好吃。", "target_word": "湿润", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗完澡后，浴室里很湿润。", "target_word": "湿润", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "苔藓喜欢湿润的地方。", "target_word": "湿润", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "濕潤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西有水分、摸起来不干", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b265e353-0a56-4f5b-a790-095a42c113c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湿润", "is_correct": true, "explanation": "正确。早上的草带有露水，“湿润”符合句意。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：滚烫的草与清晨的环境冲突，草不会是滚烫的。"}, {"text": "炎热", "is_correct": false, "explanation": "搭配：“炎热”形容天气或气候，不能用来形容草本身。"}, {"text": "灼热", "is_correct": false, "explanation": "搭配：“灼热”形容高温，与“早上的草”搭配不合理。"}], "explanations": {"湿润": "正确。早上的草带有露水，“湿润”符合句意。", "滚烫": "语义：滚烫的草与清晨的环境冲突，草不会是滚烫的。", "炎热": "搭配：“炎热”形容天气或气候，不能用来形容草本身。", "灼热": "搭配：“灼热”形容高温，与“早上的草”搭配不合理。"}, "sentence_index": 0, "correct_answer": "湿润"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的衣服湿润得滴水，只好换一件。", "explanation": "这里应该用〈湿透〉。“湿润”只表示轻微潮湿，衣服滴水要用“湿透”。"}, {"text": "我的心情很湿润，所以很开心。", "explanation": "这里“湿润”用错了对象。湿润只形容含水分、不干燥的东西，不能形容心情；表达心情好应该说〈高兴〉。"}, {"text": "山上的石头湿润得很干燥。", "explanation": "这里前后矛盾：“湿润”指有水分，“干燥”指没有水分，不能同时形容石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿润", "is_correct": true, "explanation": "正确。“又凉又湿润”描述山里带水汽的风，符合句意。"}, {"text": "燥热", "is_correct": false, "explanation": "语义：“燥热”指干热，与“凉”的语境冲突。"}, {"text": "闷热", "is_correct": false, "explanation": "语义：“闷热”指湿热，与“凉”的语境冲突。"}, {"text": "炎热", "is_correct": false, "explanation": "搭配：“又凉又炎热”前后矛盾，搭配不当。"}], "explanations": {"湿润": "正确。“又凉又湿润”描述山里带水汽的风，符合句意。", "燥热": "语义：“燥热”指干热，与“凉”的语境冲突。", "闷热": "语义：“闷热”指湿热，与“凉”的语境冲突。", "炎热": "搭配：“又凉又炎热”前后矛盾，搭配不当。"}, "sentence_index": 6, "correct_answer": "湿润"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "苔藓喜欢湿润的太阳。", "explanation": "这里应该用〈温暖〉。湿润形容含水分、不干燥的东西，太阳不含水分，不能说湿润，应该说温暖的阳光。"}, {"text": "苔藓喜欢湿润的温度。", "explanation": "这里应该用〈适宜〉。温度不含水分，不能说湿润；应说“苔藓喜欢适宜的温度”。"}, {"text": "苔藓喜欢湿润的月亮。", "explanation": "这里应该用〈明亮〉。月亮是天体，不含水分，不能说湿润，应该说明亮的月亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里的泥土得湿润。", "corrected_sentence": "这里的泥土很湿润。", "error_description": "助词误用：“得”是结构助词，不能代替程度副词“很”，应说“这里的泥土很湿润”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块毛巾非常很湿润。", "corrected_sentence": "这块毛巾非常湿润。", "error_description": "程度副词重复：“非常”和“很”不能同时修饰“湿润”，去掉“很”，应说“这块毛巾非常湿润”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
