INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21318, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "适合就是一样东西和另一样东西很配。", "primary_collocate": null, "pronunciation": "shì hé", "ipa": "ʂɻ̩˥˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这件衣服很适合你。", "target_word": "适合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书适合小孩子看。", "target_word": "适合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "红色不适合他。", "target_word": "适合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个工作适合你吗？", "target_word": "适合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天适合吃冰淇淋。", "target_word": "适合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里很安静，适合学习。", "target_word": "适合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这双鞋太小，不适合我。", "target_word": "适合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很适合当老师。", "target_word": "适合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个游戏适合三岁的孩子玩。", "target_word": "适合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路适合骑自行车，不适合开车。", "target_word": "适合", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不适合", "label": "否定"}, {"form": "适合于", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：某物或某人与另一事物相配、合适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ebcdd33-4c2b-4870-aa27-7ac3753dba86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21318, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "失和", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，失和指关系不和睦。"}, {"text": "食盒", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，食盒指装食物的盒子。"}, {"text": "试喝", "is_correct": false, "explanation": "hē（第一声）与 hé（第二声）声调不同，试喝指先尝一下饮料。"}, {"text": "适合", "is_correct": true, "explanation": "正确答案，指东西或人与另一事物相配、合适。"}], "explanations": {"失和": "shī（第一声）与 shì（第四声）声调不同，失和指关系不和睦。", "食盒": "shí（第二声）与 shì（第四声）声调不同，食盒指装食物的盒子。", "试喝": "hē（第一声）与 hé（第二声）声调不同，试喝指先尝一下饮料。", "适合": "正确答案，指东西或人与另一事物相配、合适。"}, "sentence_index": null, "correct_answer": "适合"}, "level_3": {"options": [{"text": "适合", "is_correct": true, "explanation": "正确答案。衣服与人相配、合身，符合句意。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：衣服没有感情，不能喜欢人，句子说的是衣服与人是否相配。"}, {"text": "穿", "is_correct": false, "explanation": "配价：“穿”的宾语是衣服、鞋帽等穿戴物，不能说穿你。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：衣服不会讨厌人，这一说法与句子所讲的相配关系不符。"}], "explanations": {"适合": "正确答案。衣服与人相配、合身，符合句意。", "喜欢": "语义：衣服没有感情，不能喜欢人，句子说的是衣服与人是否相配。", "穿": "配价：“穿”的宾语是衣服、鞋帽等穿戴物，不能说穿你。", "讨厌": "语义：衣服不会讨厌人，这一说法与句子所讲的相配关系不符。"}, "sentence_index": 0, "correct_answer": "适合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快就适合了新的环境。", "explanation": "这里应该用〈适应〉。适合指东西之间相配；人或事物逐渐与环境、情况协调要用适应。"}, {"text": "这个做法适合法律。", "explanation": "这里应该用〈符合〉。适合指东西之间相配；做法与法律规定相合要用符合。"}, {"text": "这个结论适合道理。", "explanation": "这里应该用〈合乎〉。与道理相合要用合乎，适合不能用于这种说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "适合", "is_correct": true, "explanation": "正确答案。鞋子与脚不相配，句子说的是不适合穿。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：鞋子不会欣赏人，句子说的是鞋子与脚不相配。"}, {"text": "戴", "is_correct": false, "explanation": "配价：“戴”的宾语是帽子、首饰等，不能说戴我。"}, {"text": "适应", "is_correct": false, "explanation": "搭配：“适应”的对象是环境、情况，不能说鞋子适应人。"}], "explanations": {"适合": "正确答案。鞋子与脚不相配，句子说的是不适合穿。", "欣赏": "语义：鞋子不会欣赏人，句子说的是鞋子与脚不相配。", "戴": "配价：“戴”的宾语是帽子、首饰等，不能说戴我。", "适应": "搭配：“适应”的对象是环境、情况，不能说鞋子适应人。"}, "sentence_index": 6, "correct_answer": "适合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份证据与事实适合。", "explanation": "这里应该用〈吻合〉。适合指东西之间相配；两件事实、证据完全对应要用吻合。"}, {"text": "这门课适合三个小时。", "explanation": "这里应该用〈需要〉。适合指东西之间相配，不能用来说需要多长时间。"}, {"text": "这场雨适合了两天。", "explanation": "这里应该用〈持续〉。适合指东西之间相配，不能用来说持续了多长时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间小屋适合了你们住。", "corrected_sentence": "这间小屋适合你们住。", "error_description": "错误：“适合”是状态动词，不能在后面加“了”表示完成，“了”应去掉。正确：这间小屋适合你们住。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个房子没适合一家人住。", "corrected_sentence": "这个房子不适合一家人住。", "error_description": "错误：“没适合”。正确：“不适合”。“适合”是状态动词，表示否定要用“不”，不用“没”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
