INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21320, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "气候是一个地方很多年的天气情况。", "primary_collocate": null, "pronunciation": "qì hòu", "ipa": "tɕʰi˥˩ xou˥˩", "syllable_count": 2, "sentences": [{"text": "这里的气候很舒服。", "target_word": "气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方的气候比北方热。", "target_word": "气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的气候很潮湿。", "target_word": "气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方气候好，一年都不冷。", "target_word": "气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气候变化影响农民种地。", "target_word": "气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这里的气候，夏天不太热。", "target_word": "气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的地方，气候也不一样。", "target_word": "气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的气候适合种茶。", "target_word": "气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全球气候越来越暖。", "target_word": "气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不习惯这儿的气候。", "target_word": "气候", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "气候变化", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个地方多年的天气总体情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a33efdb-f4f8-4a3e-8e16-958ebcfd42fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "气候", "is_correct": true, "explanation": "“气候”指一个地方多年的天气情况，“这里的气候很舒服”说得通。"}, {"text": "地形", "is_correct": false, "explanation": "语义：“地形”指地面的起伏形状，不能用“舒服”来形容。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”一般说“便宜”“贵”，不说“舒服”。"}, {"text": "行李", "is_correct": false, "explanation": "语义：“行李”指出行携带的物品，“这里的行李很舒服”说不通。"}], "explanations": {"气候": "“气候”指一个地方多年的天气情况，“这里的气候很舒服”说得通。", "地形": "语义：“地形”指地面的起伏形状，不能用“舒服”来形容。", "价格": "搭配：“价格”一般说“便宜”“贵”，不说“舒服”。", "行李": "语义：“行李”指出行携带的物品，“这里的行李很舒服”说不通。"}, "sentence_index": 0, "correct_answer": "气候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天气候很糟，我们别去爬山了。", "explanation": "这里应该用〈天气〉。“气候”指一个地方多年的总体情况，说“明天”的情况要用“天气”。"}, {"text": "这几天气候下降了不少。", "explanation": "这里应该用〈气温〉。“气候”不说“下降”，温度的变化要说“气温”。"}, {"text": "这个小区的气候很安静。", "explanation": "这里应该用〈环境〉。“气候”指天气情况，形容安静要用“环境”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气候", "is_correct": true, "explanation": "“气候”指一个地方长期的天气情况，“不同的地方，气候也不一样”说得通。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学不随地方而变，“不同的地方，数学也不一样”说不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“钢琴”是乐器，不作为会因地方而异的比较对象，与“也不一样”不搭。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，在不同地方的月亮本质相同，句意不通。"}], "explanations": {"气候": "“气候”指一个地方长期的天气情况，“不同的地方，气候也不一样”说得通。", "数学": "语义：数学不随地方而变，“不同的地方，数学也不一样”说不通。", "钢琴": "搭配：“钢琴”是乐器，不作为会因地方而异的比较对象，与“也不一样”不搭。", "月亮": "语义：月亮是天体，在不同地方的月亮本质相同，句意不通。"}, "sentence_index": 6, "correct_answer": "气候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的气候很大，我们都很喜欢。", "explanation": "这里应该用〈风〉。“气候”指多年的总体情况，不用“很大”来形容；风大要说“风很大”。"}, {"text": "城市的气候很干净。", "explanation": "这里应该用〈空气〉。“气候”不能形容“干净”，空气干净要用“空气”。"}, {"text": "这里的气候很高，衣服不好干。", "explanation": "这里应该用〈湿度〉。“气候”不说“很高”，湿度高应说“湿度很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "北京的一个气候很干燥。", "corrected_sentence": "北京的气候很干燥。", "error_description": "“气候”指一个地方的总体天气情况，前面不能加“一个”。去掉“一个”，应为“北京的气候很干燥。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昆明的一个气候很温暖。", "corrected_sentence": "昆明的气候很温暖。", "error_description": "“气候”指一个地方的总体天气情况，前面不能加“一个”。去掉“一个”，应为“昆明的气候很温暖。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
