INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21324, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做一件事，比如做工作或做活动。", "primary_collocate": null, "pronunciation": "jìn xíng", "ipa": "tɕin˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "明天下午我们进行一次小测验。", "target_word": "进行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们已经进行了两个小时的讨论。", "target_word": "进行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校下个月将进行体育比赛。", "target_word": "进行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生正在对病人进行检查。", "target_word": "进行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生进行了一次谈话。", "target_word": "进行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们每天进行十分钟的体育锻炼。", "target_word": "进行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家安静，老师马上进行点名。", "target_word": "进行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每年都会进行一次安全培训。", "target_word": "进行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在进行紧张的实验。", "target_word": "进行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们对旧桥进行了修理。", "target_word": "进行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进行了", "label": "完成体"}, {"form": "进行着", "label": "持续体"}, {"form": "进行过", "label": "经历体"}, {"form": "進行", "label": "繁体"}], "register": "正式", "sense_fingerprint": "做（正式的工作或活动），常带动词性宾语，如进行检查、进行比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f562dea-1484-4d6c-8f48-09986f773a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进行", "is_correct": true, "explanation": "正确。“明天下午我们进行一次小测验”中，进行表示做这项活动，与“小测验”搭配自然。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：参观用于场所或展览，不能说参观一次小测验。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏指赏析美好事物，与小测验的性质不符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃指进食，与“一次小测验”无关。"}], "explanations": {"进行": "正确。“明天下午我们进行一次小测验”中，进行表示做这项活动，与“小测验”搭配自然。", "参观": "搭配：参观用于场所或展览，不能说参观一次小测验。", "欣赏": "语义：欣赏指赏析美好事物，与小测验的性质不符。", "吃": "语义：吃指进食，与“一次小测验”无关。"}, "sentence_index": 0, "correct_answer": "进行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他进行了作业。", "explanation": "这里应该用〈做〉。进行多用于正式的活动或工作，做作业这类日常事务要用做。"}, {"text": "妈妈进行了早饭。", "explanation": "这里应该用〈做〉。进行不用于做饭这类家务，要说做早饭。"}, {"text": "我进行了一杯咖啡。", "explanation": "这里应该用〈喝了〉。“进行”的宾语是活动或工作，“一杯咖啡”不能作它的宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进行", "is_correct": true, "explanation": "正确。“老师马上进行点名”中，进行表示做点名这项活动，与“请大家安静”衔接自然。"}, {"text": "休息", "is_correct": false, "explanation": "配价：“休息”是不及物动词，不能带“点名”作宾语，“老师马上休息点名”不通。"}, {"text": "讲话", "is_correct": false, "explanation": "语义：“讲话”指说话，不能带“点名”作宾语，“老师马上讲话点名”不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是离合词，不能再带“点名”作宾语，“老师马上睡觉点名”不通。"}], "explanations": {"进行": "正确。“老师马上进行点名”中，进行表示做点名这项活动，与“请大家安静”衔接自然。", "休息": "配价：“休息”是不及物动词，不能带“点名”作宾语，“老师马上休息点名”不通。", "讲话": "语义：“讲话”指说话，不能带“点名”作宾语，“老师马上讲话点名”不通。", "睡觉": "配价：“睡觉”是离合词，不能再带“点名”作宾语，“老师马上睡觉点名”不通。"}, "sentence_index": 6, "correct_answer": "进行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他进行了一场大雨。", "explanation": "这里应该用〈下〉。“进行”表示人做某项活动或工作，下雨是自然现象，不能用“进行”。"}, {"text": "孩子们进行了很开心。", "explanation": "这里应该用〈玩得〉。“进行”不能直接与形容词“开心”作谓语，应说玩得很开心。"}, {"text": "我进行了一本书。", "explanation": "这里应该用〈读〉。“进行”的宾语是活动或工作，“一本书”不能作它的宾语，应说读一本书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校下周进行在体检。", "corrected_sentence": "学校下周进行体检。", "error_description": "错误：“进行在体检”，正确：“进行体检”。进行后面直接接动词性宾语，中间不能插入“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校明天将进行了一次安全演练。", "corrected_sentence": "学校明天将进行一次安全演练。", "error_description": "错误：“将进行了”，正确：“将进行”。“了”表示动作已经完成，与“明天”“将”的将来时间矛盾，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
