INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21326, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指全世界各个地方。", "primary_collocate": null, "pronunciation": "shì jiè gè dì", "ipa": "ʂɻ̩˥˩ tɕjɛ˥˩ kɤ˥˩ ti˥˩", "syllable_count": 4, "sentences": [{"text": "世界各地都有中国餐馆。", "target_word": "世界各地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他工作很忙，常常飞到世界各地。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世界各地的孩子都爱玩游戏。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师在世界各地教过中文。", "target_word": "世界各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界各地的天气不一样。", "target_word": "世界各地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "网络让世界各地的人可以聊天。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我收集了世界各地的明信片。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在世界各地都有人过春节。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的同学去了世界各地工作。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世界各地的足球迷都在看比赛。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "全世界的各个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0ed7dbc-a6e5-40ee-911c-fb724370c835') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世界各地", "is_correct": true, "explanation": "“世界各地”指全世界各个地方，与“都有中国餐馆”的范围相符。"}, {"text": "月球", "is_correct": false, "explanation": "语义：月球上没有餐馆，句子不成立。"}, {"text": "无人区", "is_correct": false, "explanation": "语义：无人区没有人居住，自然不会有餐馆，句意不通。"}, {"text": "海底", "is_correct": false, "explanation": "搭配：中国餐馆不会开在海底，“海底”与“餐馆”搭配不当。"}], "explanations": {"世界各地": "“世界各地”指全世界各个地方，与“都有中国餐馆”的范围相符。", "月球": "语义：月球上没有餐馆，句子不成立。", "无人区": "语义：无人区没有人居住，自然不会有餐馆，句意不通。", "海底": "搭配：中国餐馆不会开在海底，“海底”与“餐馆”搭配不当。"}, "sentence_index": 0, "correct_answer": "世界各地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校的世界各地都有篮球场。", "explanation": "这里应该用〈各处〉。“世界各地”指全球，不能用来指一所学校之内。"}, {"text": "我家世界各地有很多超市。", "explanation": "这里应该用〈附近〉。“世界各地”是全球范围，不能用来指家附近。"}, {"text": "这个公园的世界各地都种满了花。", "explanation": "这里应该用〈各个角落〉。“世界各地”指全球，不能用来指一个公园里的各处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世界各地", "is_correct": true, "explanation": "“世界各地”能修饰“明信片”，表示来自各处，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被收集成明信片，句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是明信片的来源或类别，句意不通。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“电脑的明信片”与“收集”搭配不当，明信片不是电脑的产物。"}], "explanations": {"世界各地": "“世界各地”能修饰“明信片”，表示来自各处，句意通顺。", "空气": "语义：空气不能被收集成明信片，句意不通。", "冰箱": "语义：冰箱不是明信片的来源或类别，句意不通。", "电脑": "搭配：“电脑的明信片”与“收集”搭配不当，明信片不是电脑的产物。"}, "sentence_index": 6, "correct_answer": "世界各地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的弟弟和世界各地是好朋友。", "explanation": "这里应该用〈一位同学〉。“世界各地”指许多地方，不能指一个人。"}, {"text": "他把书放在了书架的世界各地。", "explanation": "这里应该用〈各层〉。“世界各地”指全球，不能用来指一个书架的各层。"}, {"text": "这所医院的世界各地都有病人。", "explanation": "这里应该用〈各个病房〉。“世界各地”指全球，不能用来指一所医院之内。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个故事传了世界各地。", "corrected_sentence": "这个故事传到了世界各地。", "error_description": "错误：“传”后漏掉趋向补语“到”。正确说法是“传到了世界各地”，“传了世界各地”不成立，“到”不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在世界各地的有很多朋友。", "corrected_sentence": "她在世界各地有很多朋友。", "error_description": "错误：“世界各地”后面多加了“的”，“的”后面没有中心语，句子不通。正确说法是“她在世界各地有很多朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21328, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
