INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21328, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "小树和小草会慢慢变大。", "primary_collocate": null, "pronunciation": "shēng zhǎng", "ipa": "ʂəŋ⁵⁵ ʈʂɑŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "小草在春天生长得很快。", "target_word": "生长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种树喜欢在热的地方生长。", "target_word": "生长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了水和太阳，小树才能生长。", "target_word": "生长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竹子生长得特别快。", "target_word": "生长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的花草在雨后生长得更好了。", "target_word": "生长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小树在院子里慢慢生长。", "target_word": "生长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里太冷，草很难生长。", "target_word": "生长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有阳光，花不能正常生长。", "target_word": "生长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水多的地方，树生长得特别好。", "target_word": "生长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小树苗生长了一年，已经比我高了。", "target_word": "生长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生长了", "label": "体标（了）"}, {"form": "生长着", "label": "体标（着）"}, {"form": "生长过", "label": "体标（过）"}, {"form": "生长期", "label": "复合"}, {"form": "生長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "植物从小到大慢慢长大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fde7ad18-0ff2-44e3-844c-df7b9ce4ca9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生活", "is_correct": false, "explanation": "搭配：“生活”多用于人和动物，不说草在春天“生活得很快”。"}, {"text": "生长", "is_correct": true, "explanation": "正确：“生长”指植物慢慢长大，与小草在春天长得快的句意相符。"}, {"text": "生存", "is_correct": false, "explanation": "语义：“生存”指活下去，不是长得快，与句意不符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：草一般不说“生病”，“生病得很快”与句意不合。"}], "explanations": {"生活": "搭配：“生活”多用于人和动物，不说草在春天“生活得很快”。", "生长": "正确：“生长”指植物慢慢长大，与小草在春天长得快的句意相符。", "生存": "语义：“生存”指活下去，不是长得快，与句意不符。", "生病": "语义：草一般不说“生病”，“生病得很快”与句意不合。"}, "sentence_index": 0, "correct_answer": "生长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的工资今年生长了很多。", "explanation": "这里应该用〈增长〉。生长指生物从小慢慢长大，工资数量变多要用增长。"}, {"text": "今年的人口生长得很快。", "explanation": "这里应该用〈增长〉。生长指生物从小长大，人口数量增多要用增长。"}, {"text": "这座大楼生长了三层。", "explanation": "这里应该用〈扩建〉。生长指生物慢慢长大，建筑增加层数要用扩建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移动", "is_correct": false, "explanation": "语义：草不能“移动”来躲避寒冷，与“很难”的语境不合。"}, {"text": "说话", "is_correct": false, "explanation": "搭配：草不“说话”，“草很难说话”搭配不通。"}, {"text": "生长", "is_correct": true, "explanation": "正确：“生长”指植物在寒冷环境中慢慢长大，与“这里太冷，草很难”的语境相符。"}, {"text": "生火", "is_correct": false, "explanation": "搭配：“生火”的对象不是草，“草很难生火”搭配不通。"}], "explanations": {"移动": "语义：草不能“移动”来躲避寒冷，与“很难”的语境不合。", "说话": "搭配：草不“说话”，“草很难说话”搭配不通。", "生长": "正确：“生长”指植物在寒冷环境中慢慢长大，与“这里太冷，草很难”的语境相符。", "生火": "搭配：“生火”的对象不是草，“草很难生火”搭配不通。"}, "sentence_index": 6, "correct_answer": "生长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校生长了规模。", "explanation": "这里应该用〈扩大〉。生长指生物慢慢长大，学校规模的扩大要用扩大。"}, {"text": "他的汉语生长得很快。", "explanation": "这里应该用〈进步〉。生长用于生物，语言能力的提高要用进步。"}, {"text": "这家工厂每天生长很多汽车。", "explanation": "这里应该用〈生产〉。生长指生物长大，工厂制造汽车要用生产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片田里的麦子生长了很快。", "corrected_sentence": "这片田里的麦子生长得很快。", "error_description": "补语标记用错：表示动作或状态的程度要用“得”，应说“生长得很快”，不能用“了”说“生长了很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵树河边生长。", "corrected_sentence": "这棵树在河边生长。", "error_description": "漏掉介词：表示地点要用“在”，应说“在河边生长”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
