INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21330, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西做成可以用的东西。", "primary_collocate": null, "pronunciation": "jiā gōng", "ipa": "tɕja˥˥ kʊŋ˥˥", "syllable_count": 2, "sentences": [{"text": "工人把木头加工成桌子。", "target_word": "加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂加工牛奶。", "target_word": "加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把大豆加工成豆腐。", "target_word": "加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些铁要先加工，才能做成刀。", "target_word": "加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂加工好的衣服，明天就送到商店。", "target_word": "加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器可以加工很硬的铁。", "target_word": "加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把新鲜的鱼加工成鱼干。", "target_word": "加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶叶要经过加工，才好喝。", "target_word": "加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅正在加工一块石头。", "target_word": "加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小厂专门加工水果。", "target_word": "加工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加工了", "label": "体标"}, {"form": "加工过", "label": "体标"}, {"form": "加工厂", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，指把原料或半成品做成可以使用的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd55c2c29-17cd-4734-b3f1-6a6d294a15a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加工", "is_correct": true, "explanation": "正确：“加工”指把原料做成可用的东西，与“成桌子”相符。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”得到的是块或片，不能切成桌子。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”会把木头烧成灰，与“做成桌子”的结果矛盾。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能煮成桌子。"}], "explanations": {"加工": "正确：“加工”指把原料做成可用的东西，与“成桌子”相符。", "切": "搭配：“切”得到的是块或片，不能切成桌子。", "烧": "语义：“烧”会把木头烧成灰，与“做成桌子”的结果矛盾。", "煮": "搭配：“煮”的对象是食物，不能煮成桌子。"}, "sentence_index": 0, "correct_answer": "加工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他加工了那辆自行车。", "explanation": "这里应该用〈修理〉。加工是把原料做成可用的东西，修好旧物要说修理。"}, {"text": "工人在这里加工，修建新公路。", "explanation": "这里应该用〈施工〉。加工指把原料或半成品做成可用的东西，修建工程要说施工。"}, {"text": "他把垃圾加工干净。", "explanation": "这里应该用〈清理〉。加工不表示除去杂物，把脏乱清除干净要说清理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加工", "is_correct": true, "explanation": "正确：“加工”表示把鱼做成鱼干，与“新鲜的鱼”“成鱼干”相符。"}, {"text": "丢", "is_correct": false, "explanation": "搭配：“丢”后接“成”不成立，不能说“丢成鱼干”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与把鱼变成鱼干毫无关系。"}, {"text": "进", "is_correct": false, "explanation": "配价：“进”后不能直接带“成鱼干”这样的结果补语，“进成鱼干”不成立。"}], "explanations": {"加工": "正确：“加工”表示把鱼做成鱼干，与“新鲜的鱼”“成鱼干”相符。", "丢": "搭配：“丢”后接“成”不成立，不能说“丢成鱼干”。", "唱": "语义：“唱”与把鱼变成鱼干毫无关系。", "进": "配价：“进”后不能直接带“成鱼干”这样的结果补语，“进成鱼干”不成立。"}, "sentence_index": 6, "correct_answer": "加工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶加工孙子很辛苦。", "explanation": "这里应该用〈照顾〉。加工只用于物品或原料，不能用于照料人。"}, {"text": "这家农场加工了很多新品种。", "explanation": "这里应该用〈培育〉。加工指把原料做成可用的东西，培育作物品种要说培育。"}, {"text": "我们用水加工衣服。", "explanation": "这里应该用〈洗涤〉。加工不表示清洗，洗衣服要说洗涤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂已经加工这批钢材。", "corrected_sentence": "工厂已经加工了这批钢材。", "error_description": "错误：“已经加工这批钢材”，漏了“了”。正确：“已经加工了这批钢材”。“已经”表示动作已完成，句中动词后通常要用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们厂去年加工着很多牛奶。", "corrected_sentence": "我们厂去年加工了很多牛奶。", "error_description": "错误：“加工着很多牛奶”，“着”表示动作持续，去年已完成的动作应用“了”。正确：“加工了很多牛奶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
