INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21332, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示又做一次。", "primary_collocate": null, "pronunciation": "zài", "ipa": "tsai˥˩", "syllable_count": 1, "sentences": [{"text": "请你再说一次。", "target_word": "再", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想再看一遍。", "target_word": "再", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天我再来。", "target_word": "再", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你再试试吧。", "target_word": "再", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个菜很好吃，我想再尝一次。", "target_word": "再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没听清楚，请老师再讲一遍。", "target_word": "再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题我做错了，想再做一遍。", "target_word": "再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机没电了，我要再充一次电。", "target_word": "再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨天看了这部电影，今天不想再看了。", "target_word": "再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服太小了，我想再买一件大的。", "target_word": "再", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "再次", "label": "复合"}, {"form": "再见", "label": "复合"}], "register": "中性", "sense_fingerprint": "再|表示动作重复，又做一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e7fa8c-7e28-4a9f-9f73-de782ccd99f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21332, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "再", "is_correct": true, "explanation": "正确答案：再（zài），表示又做一次。"}, {"text": "菜", "is_correct": false, "explanation": "声母不同：“菜”（cài）与“再”（zài）的声母 c 与 z 不同，“菜”意思是蔬菜。"}, {"text": "灾", "is_correct": false, "explanation": "声调不同：“灾”（zāi，第一声）与“再”（zài，第四声）不同，“灾”意思是灾难。"}, {"text": "债", "is_correct": false, "explanation": "声母不同：“债”（zhài）与“再”（zài）的声母 zh 与 z 不同，“债”意思是债务。"}, {"text": "赛", "is_correct": false, "explanation": "声母不同：“赛”（sài）与“再”（zài）的声母 s 与 z 不同，“赛”意思是比赛。"}], "explanations": {"再": "正确答案：再（zài），表示又做一次。", "菜": "声母不同：“菜”（cài）与“再”（zài）的声母 c 与 z 不同，“菜”意思是蔬菜。", "灾": "声调不同：“灾”（zāi，第一声）与“再”（zài，第四声）不同，“灾”意思是灾难。", "债": "声母不同：“债”（zhài）与“再”（zài）的声母 zh 与 z 不同，“债”意思是债务。", "赛": "声母不同：“赛”（sài）与“再”（zài）的声母 s 与 z 不同，“赛”意思是比赛。"}, "sentence_index": null, "correct_answer": "再"}, "level_3": {"options": [{"text": "再", "is_correct": true, "explanation": "正确答案：“请你再说一次”中的“再”表示又做一次。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，与祈使句“请你……”冲突。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚刚发生，与“请你说”的祈使语气不符。"}, {"text": "曾经", "is_correct": false, "explanation": "搭配：“曾经”表示过去的经历，不能用在“请你……”的祈使句中。"}], "explanations": {"再": "正确答案：“请你再说一次”中的“再”表示又做一次。", "已经": "语义：“已经”表示动作已经完成，与祈使句“请你……”冲突。", "刚": "语义：“刚”表示刚刚发生，与“请你说”的祈使语气不符。", "曾经": "搭配：“曾经”表示过去的经历，不能用在“请你……”的祈使句中。"}, "sentence_index": 0, "correct_answer": "再"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我再第一次去北京。", "explanation": "这里的“再”表示又做一次，与“第一次”矛盾，应直接说“第一次去北京”。"}, {"text": "他再第一次拿了冠军。", "explanation": "这里的“再”表示又做一次，与“第一次”矛盾，应直接说“第一次拿了冠军”。"}, {"text": "昨天他再来了。", "explanation": "这里应该用〈又〉。“来了”是已经发生的重复，应说“又来了”；“再”用于还没发生的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21332, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "再", "is_correct": true, "explanation": "正确答案：再（zài），表示又做一次。"}, {"text": "才", "is_correct": false, "explanation": "声母不同：“才”（cái）与“再”（zài）的声母 c 与 z 不同，且声调也不同，“才”意思是刚刚、才能。"}, {"text": "猜", "is_correct": false, "explanation": "声母与声调不同：“猜”（cāi）与“再”（zài）的声母不同，“猜”意思是猜测。"}, {"text": "摘", "is_correct": false, "explanation": "声母与声调不同：“摘”（zhāi）与“再”（zài）的声母 zh 与 z 不同，“摘”意思是摘取。"}, {"text": "栽", "is_correct": false, "explanation": "声调不同：“栽”（zāi，第一声）与“再”（zài，第四声）不同，“栽”意思是种植。"}, {"text": "宰", "is_correct": false, "explanation": "声调不同：“宰”（zǎi，第三声）与“再”（zài，第四声）不同，“宰”意思是杀（牲畜）。"}], "explanations": {"再": "正确答案：再（zài），表示又做一次。", "才": "声母不同：“才”（cái）与“再”（zài）的声母 c 与 z 不同，且声调也不同，“才”意思是刚刚、才能。", "猜": "声母与声调不同：“猜”（cāi）与“再”（zài）的声母不同，“猜”意思是猜测。", "摘": "声母与声调不同：“摘”（zhāi）与“再”（zài）的声母 zh 与 z 不同，“摘”意思是摘取。", "栽": "声调不同：“栽”（zāi，第一声）与“再”（zài，第四声）不同，“栽”意思是种植。", "宰": "声调不同：“宰”（zǎi，第三声）与“再”（zài，第四声）不同，“宰”意思是杀（牲畜）。"}, "sentence_index": null, "correct_answer": "再"}, "level_3": {"options": [{"text": "再", "is_correct": true, "explanation": "正确答案：“想再做一遍”中的“再”表示又做一次。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示一直或经常，与“做一遍”的一次性动作冲突。"}, {"text": "常常", "is_correct": false, "explanation": "语义：“常常”表示经常，与“想做一遍”的一次性动作矛盾。"}, {"text": "不", "is_correct": false, "explanation": "搭配：“不”应放在“想”前，说“不想”；“想不”语序不通。"}], "explanations": {"再": "正确答案：“想再做一遍”中的“再”表示又做一次。", "总是": "语义：“总是”表示一直或经常，与“做一遍”的一次性动作冲突。", "常常": "语义：“常常”表示经常，与“想做一遍”的一次性动作矛盾。", "不": "搭配：“不”应放在“想”前，说“不想”；“想不”语序不通。"}, "sentence_index": 6, "correct_answer": "再"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妹妹再迟到了。", "explanation": "这里应该用〈又〉。“又”用于已经发生的重复，“再”通常用于尚未发生的动作，不能和已经发生的“迟到了”搭配。"}, {"text": "我上个月再去了一次北京。", "explanation": "这里应该用〈又〉。动作已经发生，表示已发生的重复用“又”，“再”用于还没发生的动作。"}, {"text": "他刚才再说了一遍，我还是没听懂。", "explanation": "这里应该用〈又〉。“说了一遍”已经发生，应说“又说了一遍”；“再”用于将来的重复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想读再一遍这本书。", "corrected_sentence": "我想再读一遍这本书。", "error_description": "“再”位置错误：“再”应放在动词前，说“再读一遍”，不能放在“读”的后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
