INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21334, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "果实是植物长出来的可以吃的东西，比如苹果和橘子。", "primary_collocate": null, "pronunciation": "guǒ shí", "ipa": "kwo˨˩˦ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "秋天到了，树上的果实都熟了。", "target_word": "果实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树的果实又大又甜。", "target_word": "果实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞到树上吃红色的果实。", "target_word": "果实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果树结了很多果实。", "target_word": "果实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民正在果园里采摘果实。", "target_word": "果实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种果实太酸，孩子们都不爱吃。", "target_word": "果实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天开花，秋天结出果实。", "target_word": "果实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些果实还是绿色的，还要再等一等。", "target_word": "果实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新鲜的果实放在盘子里。", "target_word": "果实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "果实成熟后，会自己掉到地上。", "target_word": "果实", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "植物结出的可食用的果子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0532c88-8ee2-41a8-8416-c67566056b85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21334, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "果实", "is_correct": true, "explanation": "果实，guǒ shí，指植物结出的可以吃的果子。"}, {"text": "过时", "is_correct": false, "explanation": "guò（第四声）与 guǒ（第三声）声调不同，意思是过时、落伍。"}, {"text": "过失", "is_correct": false, "explanation": "guò（第四声）与 guǒ（第三声）、shī（第一声）与 shí（第二声）声调都不同，意思是过失、错误。"}, {"text": "过世", "is_correct": false, "explanation": "guò、shì（均为第四声）与 guǒ shí 声调都不同，意思是去世。"}, {"text": "国事", "is_correct": false, "explanation": "guó（第二声）与 guǒ（第三声）、shì（第四声）与 shí（第二声）声调都不同，意思是国家大事。"}], "explanations": {"果实": "果实，guǒ shí，指植物结出的可以吃的果子。", "过时": "guò（第四声）与 guǒ（第三声）声调不同，意思是过时、落伍。", "过失": "guò（第四声）与 guǒ（第三声）、shī（第一声）与 shí（第二声）声调都不同，意思是过失、错误。", "过世": "guò、shì（均为第四声）与 guǒ shí 声调都不同，意思是去世。", "国事": "guó（第二声）与 guǒ（第三声）、shì（第四声）与 shí（第二声）声调都不同，意思是国家大事。"}, "sentence_index": null, "correct_answer": "果实"}, "level_3": {"options": [{"text": "果实", "is_correct": true, "explanation": "果实指树上结的果子，与“树上的”“熟了”相合。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“熟”多用于果实、庄稼，花朵不说“熟了”。"}, {"text": "果汁", "is_correct": false, "explanation": "语义：果汁是加工后的饮品，不会长在树上。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶不会成熟，不能说“都熟了”。"}], "explanations": {"果实": "果实指树上结的果子，与“树上的”“熟了”相合。", "花朵": "搭配：“熟”多用于果实、庄稼，花朵不说“熟了”。", "果汁": "语义：果汁是加工后的饮品，不会长在树上。", "树叶": "语义：树叶不会成熟，不能说“都熟了”。"}, "sentence_index": 0, "correct_answer": "果实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个果实很安静。", "explanation": "这里应该用〈房间〉。果实指植物结的果子，不能用来形容环境，形容安静要用〈房间〉或〈屋子〉。"}, {"text": "他用果实修好了那辆自行车。", "explanation": "这里应该用〈工具〉。果实是植物结的果子，不能用来修车，修车要用〈工具〉。"}, {"text": "我买了一只果实。", "explanation": "这里应该用〈颗〉或〈个〉。〈只〉多用于动物，果实的量词是〈颗〉和〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21334, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "果实", "is_correct": true, "explanation": "果实，guǒ shí，指植物结出的可以吃的果子。"}, {"text": "古时", "is_correct": false, "explanation": "gǔ（第三声）与 guǒ（第三声）韵母不同，意思是古代。"}, {"text": "国史", "is_correct": false, "explanation": "guó（第二声）与 guǒ（第三声）、shǐ（第三声）与 shí（第二声）声调都不同，意思是国家的历史。"}, {"text": "火石", "is_correct": false, "explanation": "h 与 guǒ 的 g 声母不同，意思是打火用的石头。"}], "explanations": {"果实": "果实，guǒ shí，指植物结出的可以吃的果子。", "古时": "gǔ（第三声）与 guǒ（第三声）韵母不同，意思是古代。", "国史": "guó（第二声）与 guǒ（第三声）、shǐ（第三声）与 shí（第二声）声调都不同，意思是国家的历史。", "火石": "h 与 guǒ 的 g 声母不同，意思是打火用的石头。"}, "sentence_index": null, "correct_answer": "果实"}, "level_3": {"options": [{"text": "果实", "is_correct": true, "explanation": "果实，植物结出的果子，与“结出”搭配。"}, {"text": "花瓣", "is_correct": false, "explanation": "搭配：“结出”不搭配花瓣，秋天结出的是果实。"}, {"text": "嫩芽", "is_correct": false, "explanation": "语义：嫩芽是春天才冒出的新苗，与“秋天结出”矛盾。"}, {"text": "树根", "is_correct": false, "explanation": "语义：树根长在地下，不会被“结出”。"}], "explanations": {"果实": "果实，植物结出的果子，与“结出”搭配。", "花瓣": "搭配：“结出”不搭配花瓣，秋天结出的是果实。", "嫩芽": "语义：嫩芽是春天才冒出的新苗，与“秋天结出”矛盾。", "树根": "语义：树根长在地下，不会被“结出”。"}, "sentence_index": 6, "correct_answer": "果实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一口气喝掉了一颗果实。", "explanation": "这里应该用〈吃〉。果实是固体食物，要说吃，不能说喝。"}, {"text": "这棵树的果实都开了。", "explanation": "这里应该用〈结〉。〈开〉多用于花朵，果实要说结。"}, {"text": "他穿上了一颗果实。", "explanation": "这里应该用〈拿〉或〈摘〉。〈穿〉用于衣服鞋袜，果实不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "树上挂着几只红红的果实。", "corrected_sentence": "树上挂着几颗红红的果实。", "error_description": "量词错误：“果实”的量词应为“颗”或“个”，“只”多用于动物，不能用于果实。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋天，果实慢慢熟了透。", "corrected_sentence": "秋天，果实慢慢熟透了。", "error_description": "补语结构错误：“熟透”是复合补语，中间不能插入“了”，应为“熟透了”，“了”放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
