INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21336, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情必须有的东西，比如做对事情需要的东西。", "primary_collocate": null, "pronunciation": "tiáo jiàn", "ipa": "tʰi̯ɑʊ˧˥ tɕiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这个工作的第一个条件是会说中文。", "target_word": "条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好语言需要什么条件？", "target_word": "条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物长大要有水和阳光这两个条件。", "target_word": "条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要申请这个项目，需要具备一定的条件。", "target_word": "条件", "complexity_tier": "T3", "furigana": "yào shēnqǐng zhège xiàngmù, xūyào jùbèi yídìng de tiáojiàn。", "sentence_source": "generated"}, {"text": "参加比赛的条件是年满十八岁。", "target_word": "条件", "complexity_tier": "T3", "furigana": "cānjiā bǐsài de tiáojiàn shì niánmǎn shíbā suì。", "sentence_source": "generated"}, {"text": "要做好这件事，我们还缺一个条件。", "target_word": "条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想拿到这笔奖学金，需要满足三个条件。", "target_word": "条件", "complexity_tier": "T3", "furigana": "xiǎng nádào zhè bǐ jiǎngxuéjīn, xūyào mǎnzú sān ge tiáojiàn。", "sentence_source": "generated"}, {"text": "报名这门课的条件是先交一百块钱。", "target_word": "条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看书的条件很简单：安静，还要有灯。", "target_word": "条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想养好这盆花，需要一些必要的条件。", "target_word": "条件", "complexity_tier": "T3", "furigana": "xiǎng yǎnghǎo zhè pén huā, xūyào yìxiē bìyào de tiáojiàn。", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}], "register": "中性", "sense_fingerprint": "条件：做成事情必须有的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8c9982-2261-4a26-bafc-a41b87d5771d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21336, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "条件", "is_correct": true, "explanation": "条件指做事必须具备的前提，符合「第一个条件是会说中文」。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：「工资」是报酬，不能与「是会说中文」这类要求搭配。"}, {"text": "时间", "is_correct": false, "explanation": "语义：「时间」不是任职的前提，「会说中文」不能是时间。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能作为任职要求，句意不通。"}], "explanations": {"条件": "条件指做事必须具备的前提，符合「第一个条件是会说中文」。", "工资": "搭配：「工资」是报酬，不能与「是会说中文」这类要求搭配。", "时间": "语义：「时间」不是任职的前提，「会说中文」不能是时间。", "天气": "语义：天气不能作为任职要求，句意不通。"}, "sentence_index": 0, "correct_answer": "条件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把条件放在桌子上了。", "explanation": "这里应该用〈书〉。条件指做事必须具备的前提，不是可以拿来放的东西。"}, {"text": "他没来的条件是生病了。", "explanation": "这里应该用〈原因〉。条件指做事的前提，不指不来的原因。"}, {"text": "这个学生的条件很聪明。", "explanation": "这里应该用〈头脑〉。聪明形容人的头脑，不能用条件来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "条件", "is_correct": true, "explanation": "条件指满足某事所需的要求，符合「满足三个条件」。"}, {"text": "文件", "is_correct": false, "explanation": "搭配：「满足」一般搭配「要求」「条件」，不说「满足文件」。"}, {"text": "证件", "is_correct": false, "explanation": "语义：证件不是需要被满足的对象，句意不通。"}, {"text": "地方", "is_correct": false, "explanation": "语义：「满足三个地方」没有意义，地方不能作为需要满足的对象。"}], "explanations": {"条件": "条件指满足某事所需的要求，符合「满足三个条件」。", "文件": "搭配：「满足」一般搭配「要求」「条件」，不说「满足文件」。", "证件": "语义：证件不是需要被满足的对象，句意不通。", "地方": "语义：「满足三个地方」没有意义，地方不能作为需要满足的对象。"}, "sentence_index": 6, "correct_answer": "条件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议的条件在二楼。", "explanation": "这里应该用〈地点〉。条件指前提，不指位置。"}, {"text": "他对朋友的条件很深，大家都很佩服。", "explanation": "这里应该用〈感情〉。「很深」形容感情，条件不能说深。"}, {"text": "这次活动的条件很短。", "explanation": "这里应该用〈时间〉。条件不用长短来形容，「短」指的是时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个工作需要三条件。", "corrected_sentence": "这个工作需要三个条件。", "error_description": "错误：数词“三”后缺少量词，应为“三个条件”。正确：数词和量词“三个”要放在名词“条件”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些条件们都很重要。", "corrected_sentence": "这些条件都很重要。", "error_description": "错误形式是「条件们」，正确形式是「条件」。「们」只用于指人的名词，「条件」是事物，不能加「们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
