INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以买卖的东西。", "primary_collocate": null, "pronunciation": "shāng pǐn", "ipa": "ʂaŋ˥ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "商店里摆着很多新商品。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件商品多少钱？", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上卖商品，生意很好。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商品上有价格，你可以自己看。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买到不好的商品，可以去换。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的商品每天都有人买。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把新商品送到了商店。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正在给商品定价。", "target_word": "商品", "complexity_tier": "T3", "furigana": "lǎobǎn zhèngzài gěi shāngpǐn dìngjià.", "sentence_source": "generated"}, {"text": "这些商品是从国外运来的。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店里的商品很便宜，我常去买。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件商品", "label": "量词"}, {"form": "一种商品", "label": "量词"}, {"form": "商品经济", "label": "复合"}, {"form": "商品房", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：可以买卖的东西，货物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bca74fc9-b4a9-4068-a7f1-1de1a45d97e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商品", "is_correct": true, "explanation": "正确。商店里摆着的是可以卖的东西。"}, {"text": "工人", "is_correct": false, "explanation": "语义：工人是人，不能摆放在商店里。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“摆”的对象是有形的物体，空气不能摆。"}, {"text": "梦想", "is_correct": false, "explanation": "搭配：“摆”不能与“梦想”搭配。"}], "explanations": {"商品": "正确。商店里摆着的是可以卖的东西。", "工人": "语义：工人是人，不能摆放在商店里。", "空气": "搭配：“摆”的对象是有形的物体，空气不能摆。", "梦想": "搭配：“摆”不能与“梦想”搭配。"}, "sentence_index": 0, "correct_answer": "商品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有一个商品，想请教老师。", "explanation": "这里应该用〈问题〉。想请教老师的是问题，商品指可以买卖的东西，不能这样说。"}, {"text": "他给孩子讲了一个商品。", "explanation": "这里应该用〈故事〉。讲的是故事，商品指用来买卖的东西。"}, {"text": "孩子在草地上踢了一个商品。", "explanation": "这里应该用〈球〉。踢的是球，商品指可以买卖的东西，不能用来踢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商品", "is_correct": true, "explanation": "正确。工人送来的是可以卖的东西，送到商店。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：商店不会收送来的垃圾，与“新”和送货的语境矛盾。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“送”的对象是物品，阳光不能送。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“送”的对象是物品，月亮不能送到商店。"}], "explanations": {"商品": "正确。工人送来的是可以卖的东西，送到商店。", "垃圾": "语义：商店不会收送来的垃圾，与“新”和送货的语境矛盾。", "阳光": "搭配：“送”的对象是物品，阳光不能送。", "月亮": "搭配：“送”的对象是物品，月亮不能送到商店。"}, "sentence_index": 6, "correct_answer": "商品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的商品很热，我们去游泳吧。", "explanation": "这里应该用〈天气〉。商品指可以买卖的东西，不能说热不热来决定去游泳。"}, {"text": "我晚上十点就上床睡商品了。", "explanation": "这里应该用〈觉〉。商品指可以买卖的东西，不能“睡”。"}, {"text": "他用商品给妈妈打了个电话。", "explanation": "这里应该用〈手机〉。打电话要用手机，商品是统称可以买卖的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店新进了两台商品。", "corrected_sentence": "这家店新进了两种商品。", "error_description": "量词用错了。“台”用于机器、电器等，商品应该用“种”或“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些商品们很便宜。", "corrected_sentence": "这些商品很便宜。", "error_description": "“们”加在了“商品”后面。商品不是人，不能加“们”表示复数；用“这些”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
