INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21342, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "用来说一个例子。", "primary_collocate": null, "pronunciation": "bǐ rú", "ipa": "pi˨˩˦ ʐu˧˥", "syllable_count": 2, "sentences": [{"text": "我喜欢很多水果，比如苹果和香蕉。", "target_word": "比如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京有很多好玩的地方，比如故宫和长城。", "target_word": "比如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会说好几种语言，比如英语、日语和法语。", "target_word": "比如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天都做运动，比如跑步、游泳。", "target_word": "比如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常做一些事，比如看书、听音乐。", "target_word": "比如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些动物很可爱，比如熊猫和小猫。", "target_word": "比如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店有很多饮料，比如茶、咖啡和果汁。", "target_word": "比如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语要多练习，比如每天说一点儿。", "target_word": "比如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去过不少国家，比如日本和法国。", "target_word": "比如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢的运动很多，比如篮球和足球。", "target_word": "比如", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "比如说", "label": "复合"}], "register": "中性", "sense_fingerprint": "连词，用在句中引出例子，后面常跟具体的人、事或物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb4457-02e8-4e80-8df6-6e789a775f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比如", "is_correct": true, "explanation": "正确。“比如”用来举例，后面列出的“苹果和香蕉”是“水果”的具体例子。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，前面说喜欢很多水果，后面接一串并列的例子，句意不通。"}, {"text": "因为", "is_correct": false, "explanation": "配价：“因为”要带出原因小句，后面须有谓语，“因为苹果和香蕉”只是名词短语，句子不完整。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，说“或者苹果和香蕉”变成二选一，与列举例子的意思不符。"}], "explanations": {"比如": "正确。“比如”用来举例，后面列出的“苹果和香蕉”是“水果”的具体例子。", "但是": "语义：“但是”表示转折，前面说喜欢很多水果，后面接一串并列的例子，句意不通。", "因为": "配价：“因为”要带出原因小句，后面须有谓语，“因为苹果和香蕉”只是名词短语，句子不完整。", "或者": "语义：“或者”表示选择，说“或者苹果和香蕉”变成二选一，与列举例子的意思不符。"}, "sentence_index": 0, "correct_answer": "比如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很想去北京，比如我没有时间。", "explanation": "这里是转折，应该用〈但是〉。“比如”只用于举出同类的例子，不能引出与前文相反的情况。"}, {"text": "天气很冷，比如我们没有出门。", "explanation": "这里是因果关系，应该用〈所以〉。“比如”不表示结果，只能引出例子。"}, {"text": "我没去，比如天下雨了。", "explanation": "这里是原因，应该用〈因为〉。“比如”不能引出原因，只用于举例。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比如", "is_correct": true, "explanation": "正确。“比如”引出例子，后面列出茶、咖啡和果汁。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，前面只说饮料多，无法推出后面列出的几种饮料，句意不通。"}, {"text": "虽然", "is_correct": false, "explanation": "配价：“虽然”后面需要完整小句，并与“但是”等呼应，“虽然茶、咖啡和果汁”不成句。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，前后意思要相反，这里后面接的是并列的例子，不合语境。"}], "explanations": {"比如": "正确。“比如”引出例子，后面列出茶、咖啡和果汁。", "所以": "语义：“所以”表示结果，前面只说饮料多，无法推出后面列出的几种饮料，句意不通。", "虽然": "配价：“虽然”后面需要完整小句，并与“但是”等呼应，“虽然茶、咖啡和果汁”不成句。", "然而": "语义：“然而”表示转折，前后意思要相反，这里后面接的是并列的例子，不合语境。"}, "sentence_index": 6, "correct_answer": "比如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的力气真大，比如一头牛一样。", "explanation": "这里是打比方，应该用〈好比〉。“比如”只用于举出同类的例子，不用于把人比作事物。"}, {"text": "他喜欢篮球和足球，比如运动。", "explanation": "“比如”后面应是具体的例子。“运动”是前面“篮球和足球”的总称，不能放在这里当例子。"}, {"text": "他喜欢篮球和足球，比如他喜欢的运动很多。", "explanation": "“比如”后面应该是具体的例子。“他喜欢的运动很多”是总的说法，不是例子，应该先说总的，再用“比如”引出“篮球和足球”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我周末喜欢做很多事，比如看电影和比如散步。", "corrected_sentence": "我周末喜欢做很多事，比如看电影和散步。", "error_description": "“比如”只用一次，统领整个例子列。在“和”后面又加了“比如”，重复了，应说“比如看电影和散步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校附近有很多餐馆，比如例如川菜和粤菜。", "corrected_sentence": "学校附近有很多餐馆，比如川菜和粤菜。", "error_description": "“比如”和“例如”意思相同，不能叠加使用。只用“比如”即可，应说“比如川菜和粤菜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
