INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21344, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "表示事情做完了或变成了别的样子。", "primary_collocate": null, "pronunciation": "chéng", "ipa": "ʈʂʰɤŋ˧˥", "syllable_count": 1, "sentences": [{"text": "请把这张纸剪成两半。", "target_word": "成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把蛋糕切成了六块。", "target_word": "成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把月亮画成了方的。", "target_word": "成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于把这件事办成了。", "target_word": "成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，河水变成了冰。", "target_word": "成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把教室布置成了花园。", "target_word": "成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把长句子改成了短句子。", "target_word": "成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划终于办成了。", "target_word": "成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把大米磨成了粉。", "target_word": "成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下了一夜，路都变成了小河。", "target_word": "成", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "成了", "label": "体标"}, {"form": "变成", "label": "复合"}, {"form": "做成", "label": "复合"}], "register": "中性", "sense_fingerprint": "放在动词后，表示做成或变成另一种样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a269e1a5-c59d-4121-a4c6-6e6ac15ab5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21344, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成", "is_correct": true, "explanation": "成（chéng）是目标词，放在动词后表示做成或变成另一种样子。"}, {"text": "长", "is_correct": false, "explanation": "cháng（第二声）与 chéng 韵母不同（ang/eng），意思是长短、长大。"}, {"text": "层", "is_correct": false, "explanation": "céng 与 chéng 声母不同（c/ch），意思是层次、楼层。"}, {"text": "撑", "is_correct": false, "explanation": "chēng（第一声）与 chéng（第二声）声调不同，意思是支撑。"}, {"text": "沉", "is_correct": false, "explanation": "chén（第二声）与 chéng 韵母不同（n/ng），意思是沉没。"}], "explanations": {"成": "成（chéng）是目标词，放在动词后表示做成或变成另一种样子。", "长": "cháng（第二声）与 chéng 韵母不同（ang/eng），意思是长短、长大。", "层": "céng 与 chéng 声母不同（c/ch），意思是层次、楼层。", "撑": "chēng（第一声）与 chéng（第二声）声调不同，意思是支撑。", "沉": "chén（第二声）与 chéng 韵母不同（n/ng），意思是沉没。"}, "sentence_index": null, "correct_answer": "成"}, "level_3": {"options": [{"text": "成", "is_correct": true, "explanation": "成：“剪成两半”表示剪开后变成两半，符合语境。"}, {"text": "断", "is_correct": false, "explanation": "搭配：“剪断”指切断、剪断开，不能说“剪断两半”。"}, {"text": "碎", "is_correct": false, "explanation": "语义：“碎”表示弄成细小的碎片，不是分成两半。"}, {"text": "裂", "is_correct": false, "explanation": "语义：“裂”指开裂、出现裂缝，用剪刀剪纸不说“剪裂两半”。"}], "explanations": {"成": "成：“剪成两半”表示剪开后变成两半，符合语境。", "断": "搭配：“剪断”指切断、剪断开，不能说“剪断两半”。", "碎": "语义：“碎”表示弄成细小的碎片，不是分成两半。", "裂": "语义：“裂”指开裂、出现裂缝，用剪刀剪纸不说“剪裂两半”。"}, "sentence_index": 0, "correct_answer": "成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "几年不见，他成了我最好的朋友。", "explanation": "这里的“成”是“成为”，单独作谓语，不是放在动词后的结果补语。"}, {"text": "这件事成不成，明天就知道了。", "explanation": "这里的“成”表示“成功、办得到”，单独作谓语，不是结果补语。"}, {"text": "成千上万的人来参观展览。", "explanation": "这里的“成”在固定成语“成千上万”中，表示数量极多，与结果补语无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21344, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "成", "is_correct": true, "explanation": "成（chéng）是目标词，放在动词后表示做成或变成另一种样子。"}, {"text": "虫", "is_correct": false, "explanation": "chóng（第二声）与 chéng 韵母不同（o/e），意思是昆虫。"}, {"text": "称", "is_correct": false, "explanation": "chēng（第一声）与 chéng 声调不同，意思是称重。"}, {"text": "曾", "is_correct": false, "explanation": "céng 与 chéng 声母不同（c/ch），意思是曾经。"}, {"text": "陈", "is_correct": false, "explanation": "chén（第二声）与 chéng 韵母不同（n/ng），意思是陈旧。"}], "explanations": {"成": "成（chéng）是目标词，放在动词后表示做成或变成另一种样子。", "虫": "chóng（第二声）与 chéng 韵母不同（o/e），意思是昆虫。", "称": "chēng（第一声）与 chéng 声调不同，意思是称重。", "曾": "céng 与 chéng 声母不同（c/ch），意思是曾经。", "陈": "chén（第二声）与 chéng 韵母不同（n/ng），意思是陈旧。"}, "sentence_index": null, "correct_answer": "成"}, "level_3": {"options": [{"text": "成", "is_correct": true, "explanation": "成：“改成”表示改动后变成另一种形式，符合语境。"}, {"text": "织", "is_correct": false, "explanation": "语义：“织”指用线、布等编结，句子不能被编织，句意不通。"}, {"text": "掉", "is_correct": false, "explanation": "搭配：“改掉”表示去除缺点或习惯，不能用于句子的改写。"}, {"text": "坏", "is_correct": false, "explanation": "语义：“改坏”表示改得不好、弄坏了，与“改成短句子”的意思不符。"}], "explanations": {"成": "成：“改成”表示改动后变成另一种形式，符合语境。", "织": "语义：“织”指用线、布等编结，句子不能被编织，句意不通。", "掉": "搭配：“改掉”表示去除缺点或习惯，不能用于句子的改写。", "坏": "语义：“改坏”表示改得不好、弄坏了，与“改成短句子”的意思不符。"}, "sentence_index": 6, "correct_answer": "成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大学毕业后成了一名老师。", "explanation": "这里的“成”是动词“成为”，单独作谓语，不是结果补语，不接在动词后表示变成的样子。"}, {"text": "工资涨了一成。", "explanation": "这里的“成”表示十分之一，是数量用法，与“变成另一种样子”无关。"}, {"text": "这个计划终于成了。", "explanation": "这里的“成”是动词“成功”，单独作谓语，不是结果补语的用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把木头劈了成两段。", "corrected_sentence": "他把木头劈成了两段。", "error_description": "错在“了”和“成”的顺序：应为“劈成了两段”，结果补语“成”紧跟动词，“了”放在“成”后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
