INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21346, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "你需要一样东西，就表示你离不开它。", "primary_collocate": null, "pronunciation": "xū yào", "ipa": "ɕy˥ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我需要一杯热水。", "target_word": "需要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子需要父母的关心。", "target_word": "需要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你需要帮忙吗？", "target_word": "需要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个工作需要很多时间。", "target_word": "需要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "植物需要阳光和水才能长大。", "target_word": "需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他生病了，需要好好休息。", "target_word": "需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买房子需要一大笔钱。", "target_word": "需要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不需要新手机，旧的还能用。", "target_word": "需要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人需要有人照顾。", "target_word": "需要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做这道菜需要什么东西？", "target_word": "需要", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "不需要", "label": "否定"}, {"form": "需不需要", "label": "正反问"}], "register": "中性", "sense_fingerprint": "必须有某物或某条件才行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7679ce6-7410-49f6-bfdd-e5891d0d533a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "需要", "is_correct": true, "explanation": "需要：必须有某物才行，此处说我必须有一杯热水。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”用于固体食物，水要说“喝”，不说“吃一杯热水”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是要清洁的东西，句中说的是要一杯水，不能是洗。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍”是击打或拍照，不能用来表示要某样东西。"}], "explanations": {"需要": "需要：必须有某物才行，此处说我必须有一杯热水。", "吃": "搭配：“吃”用于固体食物，水要说“喝”，不说“吃一杯热水”。", "洗": "语义：“洗”的对象是要清洁的东西，句中说的是要一杯水，不能是洗。", "拍": "语义：“拍”是击打或拍照，不能用来表示要某样东西。"}, "sentence_index": 0, "correct_answer": "需要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一加一需要二。", "explanation": "这里应该用〈等于〉。表示数字相等要说等于，“需要”表示必须有某物才行。"}, {"text": "这个问题需要很多困难。", "explanation": "这里应该用〈存在〉。说有某种困难要用存在，“需要”不表示有或存在。"}, {"text": "我需要一阵头痛。", "explanation": "这里应该用〈感到〉。“需要”表示必须有某物才行，身体的不适要说感到，不能说需要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "需要", "is_correct": true, "explanation": "需要：必须有某物才行，此处说买房子必须有一大笔钱。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，不说“喝一大笔钱”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿夹住，钱不能被咬。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能唱钱。"}], "explanations": {"需要": "需要：必须有某物才行，此处说买房子必须有一大笔钱。", "喝": "搭配：“喝”的对象是饮料，不说“喝一大笔钱”。", "咬": "语义：“咬”是用牙齿夹住，钱不能被咬。", "唱": "语义：“唱”的对象是歌曲，不能唱钱。"}, "sentence_index": 6, "correct_answer": "需要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市需要南方。", "explanation": "这里应该用〈位于〉。“位于”说地理位置，“需要”表示必须有某物，不能用来说城市在哪个方位。"}, {"text": "这条路需要很远的地方。", "explanation": "这里应该用〈通往〉。“通往”说道路的去向，“需要”表示必须有某物，不能用来说路通到哪里。"}, {"text": "这个词需要来自英语。", "explanation": "这里应该用〈源于〉。“源于”说词语的来源，“需要”表示必须有某物，不能用来说来源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们没需要买新的电脑。", "corrected_sentence": "我们不需要买新的电脑。", "error_description": "否定副词用错：“需要”表示必要，否定要用“不”，不能用“没”，应说“不需要”，即“我们不需要买新的电脑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们很需要了帮助。", "corrected_sentence": "他们很需要帮助。", "error_description": "“很”表示程度，与表示完成的“了”不同用；“很需要了帮助”应删去“了”，说“他们很需要帮助”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
