INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21348, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卖出", "is_correct": true, "explanation": "正确。买进与卖出互为反义，一买一卖。"}, {"text": "收藏", "is_correct": false, "explanation": "与买进无反义关系，收藏指把珍贵的东西保存起来。"}, {"text": "出发", "is_correct": false, "explanation": "与买进无反义关系，出发指离开某地前往别处。"}, {"text": "睡觉", "is_correct": false, "explanation": "与买进无反义关系，睡觉指入睡休息。"}], "correct_answer": "卖出", "explanations": {"卖出": "正确。买进与卖出互为反义，一买一卖。", "收藏": "与买进无反义关系，收藏指把珍贵的东西保存起来。", "出发": "与买进无反义关系，出发指离开某地前往别处。", "睡觉": "与买进无反义关系，睡觉指入睡休息。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21348, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用钱把东西买过来。", "primary_collocate": null, "pronunciation": "mǎi jìn", "ipa": "mai˨˩˦ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "超市每天从农场买进新鲜牛奶。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板买进了一百件新衣服。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校买进了一批桌子和椅子。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的公司从朋友那里买进了一辆旧车。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里刚买进了一些水果，很新鲜。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂买进原料，做成商品再卖出去。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店今天早上买进了二十斤鱼。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱合适，我们就多买进一些。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一次买进了三台电脑。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店从出版社买进了很多新书。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "买进了", "label": "体标"}, {"form": "买进过", "label": "体标"}, {"form": "買進", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：花钱把东西买入、收进来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bca74fc9-b4a9-4068-a7f1-1de1a45d97e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21348, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "买进", "is_correct": true, "explanation": "正确。mǎi jìn，指花钱把东西买过来。"}, {"text": "迈进", "is_correct": false, "explanation": "mài jìn（第四声）与 mǎi（第三声）声调不同，意思是向前迈步。"}, {"text": "埋进", "is_correct": false, "explanation": "mái jìn（第二声）与 mǎi（第三声）声调不同，意思是埋入。"}, {"text": "摆进", "is_correct": false, "explanation": "bǎi jìn 与 mǎi 声母不同（b 与 m），意思是摆放进去。"}], "explanations": {"买进": "正确。mǎi jìn，指花钱把东西买过来。", "迈进": "mài jìn（第四声）与 mǎi（第三声）声调不同，意思是向前迈步。", "埋进": "mái jìn（第二声）与 mǎi（第三声）声调不同，意思是埋入。", "摆进": "bǎi jìn 与 mǎi 声母不同（b 与 m），意思是摆放进去。"}, "sentence_index": null, "correct_answer": "买进"}, "level_3": {"options": [{"text": "买进", "is_correct": true, "explanation": "正确。与“从农场”的来源方向一致，指从农场买入牛奶。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉是丢弃，与超市每天进货、保证新鲜的意思相反。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：销毁是彻底毁掉，与超市每天进货、出售的意思矛盾。"}, {"text": "生产", "is_correct": false, "explanation": "配价：超市不是牛奶的制造者，“生产”的主语应是制造者。"}], "explanations": {"买进": "正确。与“从农场”的来源方向一致，指从农场买入牛奶。", "扔掉": "语义：扔掉是丢弃，与超市每天进货、保证新鲜的意思相反。", "销毁": "语义：销毁是彻底毁掉，与超市每天进货、出售的意思矛盾。", "生产": "配价：超市不是牛奶的制造者，“生产”的主语应是制造者。"}, "sentence_index": 0, "correct_answer": "买进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她深深地买进了一口气，然后开始唱歌。", "explanation": "这里应该用〈吸〉。“买进”表示用钱购买东西，不能用来指吸气。"}, {"text": "学校买进了一项新规定。", "explanation": "这里应该用〈制定〉。“买进”的对象是货物或资产，规定不能用钱买。"}, {"text": "他买进了一句承诺。", "explanation": "这里应该用〈许下〉。“买进”只用于有形的货物或资产，承诺不能买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21348, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "买进", "is_correct": true, "explanation": "正确。mǎi jìn，指花钱把东西买过来。"}, {"text": "卖劲", "is_correct": false, "explanation": "mài jìn（第四声）与 mǎi（第三声）声调不同，意思是使劲、卖力。"}, {"text": "卖尽", "is_correct": false, "explanation": "mài jìn 与 mǎi 声调不同，意思是全部卖光。"}, {"text": "埋进", "is_correct": false, "explanation": "mái jìn（第二声）与 mǎi（第三声）声调不同，意思是埋入。"}], "explanations": {"买进": "正确。mǎi jìn，指花钱把东西买过来。", "卖劲": "mài jìn（第四声）与 mǎi（第三声）声调不同，意思是使劲、卖力。", "卖尽": "mài jìn 与 mǎi 声调不同，意思是全部卖光。", "埋进": "mái jìn（第二声）与 mǎi（第三声）声调不同，意思是埋入。"}, "sentence_index": null, "correct_answer": "买进"}, "level_3": {"options": [{"text": "买进", "is_correct": true, "explanation": "正确。指饭店一早进货，与句意相符。"}, {"text": "养殖", "is_correct": false, "explanation": "语义：养殖是培育动物，饭店不是养殖的主体，句子说不通。"}, {"text": "送给", "is_correct": false, "explanation": "配价：“送给”需要接受者，句中没有接受者。"}, {"text": "参观", "is_correct": false, "explanation": "语义：参观的对象是地方或场所，不能用于鱼。"}], "explanations": {"买进": "正确。指饭店一早进货，与句意相符。", "养殖": "语义：养殖是培育动物，饭店不是养殖的主体，句子说不通。", "送给": "配价：“送给”需要接受者，句中没有接受者。", "参观": "语义：参观的对象是地方或场所，不能用于鱼。"}, "sentence_index": 6, "correct_answer": "买进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书店把这些书买进了书架。", "explanation": "这里应该用〈放〉。“买进”表示用钱购买，不表示把东西放进某处。"}, {"text": "书店买进了一场展览。", "explanation": "这里应该用〈举办〉。“买进”的对象是货物或资产，展览不能买。"}, {"text": "老板买进了一位顾客的信任。", "explanation": "这里应该用〈赢得〉。“买进”只用于有形的货物或资产，信任不能买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校上个月买进着五张课桌。", "corrected_sentence": "学校上个月买进了五张课桌。", "error_description": "错误在“买进”后的动态助词。上个月已经完成的购买应用“了”，“着”表示持续状态，不能用于已完成的事件，应说“买进了五张课桌”，不能说“买进着五张课桌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天要从批发商那里买进了十箱饮料。", "corrected_sentence": "我们明天要从批发商那里买进十箱饮料。", "error_description": "错误在“买进”后的“了”。“明天要”表示还没发生的事，“买进”后不能加表示完成的“了”，应说“明天要买进十箱饮料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
