INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21352, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不同国家的人互相买卖东西。", "primary_collocate": null, "pronunciation": "guó jì mào yì", "ipa": "kuɔ˧˥ tɕi˥˩ maʊ˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "我爸爸做国际贸易，常常去国外。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际贸易就是不同国家的人买卖东西。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做国际贸易要懂外语。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想做国际贸易，所以学了英语和法语。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的国际贸易主要卖茶叶。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠国际贸易赚了很多钱。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际贸易让我们能买到外国的水果。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有很多做国际贸易的商人。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做国际贸易的人常常坐飞机出差。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在上网也能做国际贸易。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國際貿易", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不同国家的人互相买卖东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0ed7dbc-a6e5-40ee-911c-fb724370c835') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际贸易", "is_correct": true, "explanation": "“做国际贸易”指从事不同国家之间的买卖，与“我爸爸做”相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被“做”，句意不通。"}, {"text": "风景", "is_correct": false, "explanation": "搭配：“做”不与“风景”搭配，说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是可以去做的事情，句意不通。"}], "explanations": {"国际贸易": "“做国际贸易”指从事不同国家之间的买卖，与“我爸爸做”相符。", "空气": "语义：空气不能被“做”，句意不通。", "风景": "搭配：“做”不与“风景”搭配，说不通。", "天气": "语义：天气是自然现象，不是可以去做的事情，句意不通。"}, "sentence_index": 0, "correct_answer": "国际贸易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的国际贸易很好吃。", "explanation": "这里应该用〈国际美食〉。贸易是交易活动，不能吃，也不能用“很好吃”来形容。"}, {"text": "他们在国际贸易见面。", "explanation": "这里应该用〈国际机场〉。“国际贸易”是活动，不是地点，不能用“在……见面”。"}, {"text": "他结交了很多国际贸易。", "explanation": "这里应该用〈国际友人〉。“结交”的对象是人，国际贸易不是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际贸易", "is_correct": true, "explanation": "“国际贸易”能促成商品买卖，作主语“让我们能买到外国的水果”，句意通顺。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不能让人买到水果，句意不通。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：沉默不能使人买到外国水果，句意荒谬。"}, {"text": "咖啡", "is_correct": false, "explanation": "配价：“让我们能买到”需要能促成买卖的主语，“咖啡”不具备这种功能。"}], "explanations": {"国际贸易": "“国际贸易”能促成商品买卖，作主语“让我们能买到外国的水果”，句意通顺。", "阳光": "语义：阳光不能让人买到水果，句意不通。", "沉默": "语义：沉默不能使人买到外国水果，句意荒谬。", "咖啡": "配价：“让我们能买到”需要能促成买卖的主语，“咖啡”不具备这种功能。"}, "sentence_index": 6, "correct_answer": "国际贸易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下班以后，把国际贸易放进了书包。", "explanation": "这里应该用〈文件〉。国际贸易是活动，不是物品，不能放进书包。"}, {"text": "妈妈热情地给国际贸易倒了一杯茶。", "explanation": "这里应该用〈客人〉。国际贸易是活动，不能接受招待。"}, {"text": "他每天下午把国际贸易搬到楼上去。", "explanation": "这里应该用〈桌子〉。国际贸易是活动，不是家具，不能搬动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂专门国际贸易。", "corrected_sentence": "这家工厂专门做国际贸易。", "error_description": "错误：“国际贸易”前漏掉动词“做”，句子缺少谓语。正确说法是“专门做国际贸易”，“做”不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他打国际贸易已经十年了。", "corrected_sentence": "他做国际贸易已经十年了。", "error_description": "错误形式：“打国际贸易”；正确形式：“做国际贸易”。从事国际贸易要用动词“做”（或“从事”），不能用“打”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
