INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21356, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西送到别的地方去。", "primary_collocate": null, "pronunciation": "yùn wǎng", "ipa": "yn˥˩ wɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司把新电脑运往各个分店。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些蔬菜每天早上运往市场。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把帐篷运往山上的营地。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一批大米已经运往灾区了。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机把海鲜运往东京的饭店。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的汽车零件都运往国外。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花明天一早运往机场。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机开车把木头运往河边。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年我们的茶叶运往很多国家。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用大船把石头运往小岛。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "运往", "label": "基本形"}, {"form": "运往了", "label": "体标（了）"}, {"form": "運往", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把东西送去别的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bca74fc9-b4a9-4068-a7f1-1de1a45d97e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运往", "is_correct": true, "explanation": "正确。“运往”表示把东西送到各个分店。"}, {"text": "搬走", "is_correct": false, "explanation": "配价：“搬走”需要说明从哪里搬走，且“各个分店”不能作搬走的对象。"}, {"text": "生产", "is_correct": false, "explanation": "配价：“生产”不带“各个分店”这种地点作宾语，句子说不通。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：销毁是毁掉，与把电脑送往分店的意思相反。"}], "explanations": {"运往": "正确。“运往”表示把东西送到各个分店。", "搬走": "配价：“搬走”需要说明从哪里搬走，且“各个分店”不能作搬走的对象。", "生产": "配价：“生产”不带“各个分店”这种地点作宾语，句子说不通。", "销毁": "语义：销毁是毁掉，与把电脑送往分店的意思相反。"}, "sentence_index": 0, "correct_answer": "运往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议已经运往灾区了。", "explanation": "这里应该用〈召开〉。“运往”的对象是货物，会议不能用车船运送，应说“在灾区召开”。"}, {"text": "这个笑话已经运往各个学校了。", "explanation": "这里应该用〈传开〉。“运往”是用车船运送实物，笑话不能这样运送。"}, {"text": "他把水果运往冰箱里了。", "explanation": "这里应该用〈放进〉。“运往”指长途运输，把水果放进冰箱是近距离移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运往", "is_correct": true, "explanation": "正确。“运往”表示把花送到机场。"}, {"text": "种植", "is_correct": false, "explanation": "配价：“种植”需要说明种在哪里，且“机场”不能作种植的处所。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：修剪是剪去枝叶，与把花送往机场的意思不符。"}, {"text": "摘下", "is_correct": false, "explanation": "语义：摘下是采摘，与把花送往机场的意思不符，句子说不通。"}], "explanations": {"运往": "正确。“运往”表示把花送到机场。", "种植": "配价：“种植”需要说明种在哪里，且“机场”不能作种植的处所。", "修剪": "语义：修剪是剪去枝叶，与把花送往机场的意思不符。", "摘下": "语义：摘下是采摘，与把花送往机场的意思不符，句子说不通。"}, "sentence_index": 6, "correct_answer": "运往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们用大船把电运往小岛。", "explanation": "这里应该用〈输送〉。“运往”用于车船运送货物，电要靠线路输送。"}, {"text": "他们用大船把阳光运往小岛。", "explanation": "这里应该用〈照到〉。“运往”的对象是货物，阳光是自然现象，不能用船运送。"}, {"text": "这首歌已经运往小岛了。", "explanation": "这里应该用〈传到〉。“运往”只用于货物，歌曲不能用车船运送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司把一批零件运往在各个分店。", "corrected_sentence": "公司把一批零件运往各个分店。", "error_description": "错误在“往”后面多加了介词“在”。“往”已经引出去向，后面直接接地点，应说“运往各个分店”，不能说“运往在各个分店”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些药品明天一早运往过机场。", "corrected_sentence": "这些药品明天一早运往机场。", "error_description": "错误在“过”。“过”表示过去的经历，“明天一早”是将来，不能用“过”，应说“明天一早运往机场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
