INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21358, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示某事物含有某种意思，或必然带来某种结果。", "primary_collocate": null, "pronunciation": "yì wèi zhe", "ipa": "i˥˩ wei˥˩ ʈʂə", "syllable_count": 3, "sentences": [{"text": "下雨意味着今天不能去爬山了。", "target_word": "意味着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个红灯意味着车必须停下来。", "target_word": "意味着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生了孩子意味着要多花很多时间。", "target_word": "意味着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑得早，意味着冬天快到了。", "target_word": "意味着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学一门新语言意味着要天天练习。", "target_word": "意味着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不说话，不一定意味着他不高兴。", "target_word": "意味着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子变大意味着租金也会更高。", "target_word": "意味着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考上大学意味着新生活开始了。", "target_word": "意味着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个声音意味着火车快到站了。", "target_word": "意味着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱变多不意味着人就会快乐。", "target_word": "意味着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不意味着", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "动词，表示某事物含有某种意思或必然带来某种结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd55c2c29-17cd-4734-b3f1-6a6d294a15a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21358, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意味着", "is_correct": true, "explanation": "正确：“意味着”表示某事含有某种意思或带来某种结果，与“下雨”和“今天不能去”相符。"}, {"text": "答应", "is_correct": false, "explanation": "语义：“答应”需要人的行为，“下雨”不能答应。"}, {"text": "需要", "is_correct": false, "explanation": "搭配：“需要”表示必须有某物或某事，不能表示下雨带来今天不能去的结果。"}, {"text": "同意", "is_correct": false, "explanation": "语义：“同意”的主语应是人，下雨不能同意什么。"}], "explanations": {"意味着": "正确：“意味着”表示某事含有某种意思或带来某种结果，与“下雨”和“今天不能去”相符。", "答应": "语义：“答应”需要人的行为，“下雨”不能答应。", "需要": "搭配：“需要”表示必须有某物或某事，不能表示下雨带来今天不能去的结果。", "同意": "语义：“同意”的主语应是人，下雨不能同意什么。"}, "sentence_index": 0, "correct_answer": "意味着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我意味着去北京工作。", "explanation": "这里应该用〈打算〉。意味着表示事物含有某种意思或带来某种结果，人的计划要说打算。"}, {"text": "妈妈意味着明天带我去公园。", "explanation": "这里应该用〈答应〉。意味着说明事物的含义，不能表示人许下诺言。"}, {"text": "校长意味着下周放假。", "explanation": "这里应该用〈宣布〉。意味着不能用来表示人公开发布消息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意味着", "is_correct": true, "explanation": "正确：“意味着”表示某事带来某种结果，“房子变大”导致租金更高，与之相符。"}, {"text": "请求", "is_correct": false, "explanation": "语义：“请求”的主语应是人，“房子变大”不能请求什么。"}, {"text": "盼望", "is_correct": false, "explanation": "语义：“盼望”表达人的愿望，房子无法盼望租金更高。"}, {"text": "喜欢", "is_correct": false, "explanation": "搭配：“喜欢”不能接“房子变大”这样的事件作主语，“房子变大喜欢租金更高”不成立。"}], "explanations": {"意味着": "正确：“意味着”表示某事带来某种结果，“房子变大”导致租金更高，与之相符。", "请求": "语义：“请求”的主语应是人，“房子变大”不能请求什么。", "盼望": "语义：“盼望”表达人的愿望，房子无法盼望租金更高。", "喜欢": "搭配：“喜欢”不能接“房子变大”这样的事件作主语，“房子变大喜欢租金更高”不成立。"}, "sentence_index": 6, "correct_answer": "意味着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他意味着我去吃饭。", "explanation": "这里应该用〈邀请〉。意味着表示含义或结果，不表示人发出邀请。"}, {"text": "医生意味着他戒烟。", "explanation": "这里应该用〈劝告〉。意味着不能表示人对他人提出建议。"}, {"text": "妈妈意味着我带伞。", "explanation": "这里应该用〈提醒〉。意味着不表示提示他人注意某事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次迟到很意味着你要重新排队。", "corrected_sentence": "这次迟到意味着你要重新排队。", "error_description": "错误：“很意味着”，副词“很”放在了“意味着”前。正确：“这次迟到意味着你要重新排队。”“意味着”是动词，不能用副词“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次胜利不意味着了比赛结束。", "corrected_sentence": "这次胜利不意味着比赛结束。", "error_description": "错误：“意味着了比赛结束”，“了”放在了“意味着”后。正确：“不意味着比赛结束”。“意味着”后面直接接宾语小句，不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
