INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21360, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "卖东西的大房子，人们去那里买吃的和用的。", "primary_collocate": null, "pronunciation": "chāo shì", "ipa": "ʈʂʰaʊ˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我每个星期六去超市买菜。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的水果很新鲜。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在超市买了牛奶和面包。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家超市离我家很近。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市晚上十点才关门。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家旁边新开了一家超市。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在超市工作，每天都很忙。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里人太多，我们不想去了。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把买好的东西从超市拿回了家。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的东西比小店便宜一点。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一家超市", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，顾客自己拿东西再付钱的大商店，卖食品和日用品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b19119-d89a-436b-a0df-53ddddc827e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21360, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "超市", "is_correct": true, "explanation": "正确。“超市”指顾客自选商品、付款的大型商店。"}, {"text": "超时", "is_correct": false, "explanation": "声调不同：shí（第二声）与 shì（第四声）不同，意思是超过时间。"}, {"text": "招式", "is_correct": false, "explanation": "声母不同：zhāo 与 chāo 的声母不同（zh 与 ch），意思是招数。"}, {"text": "朝市", "is_correct": false, "explanation": "声调不同：cháo（第二声）与 chāo（第一声）不同，意思是早市。"}], "explanations": {"超市": "正确。“超市”指顾客自选商品、付款的大型商店。", "超时": "声调不同：shí（第二声）与 shì（第四声）不同，意思是超过时间。", "招式": "声母不同：zhāo 与 chāo 的声母不同（zh 与 ch），意思是招数。", "朝市": "声调不同：cháo（第二声）与 chāo（第一声）不同，意思是早市。"}, "sentence_index": null, "correct_answer": "超市"}, "level_3": {"options": [{"text": "医院", "is_correct": false, "explanation": "语义：医院不卖菜，“买菜”的地点不能是医院。"}, {"text": "超市", "is_correct": true, "explanation": "正确。超市卖食品和蔬菜，符合“去……买菜”的语境。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理存取款的地方，不卖菜。"}, {"text": "书店", "is_correct": false, "explanation": "搭配：书店卖的是书，不说在书店“买菜”。"}], "explanations": {"医院": "语义：医院不卖菜，“买菜”的地点不能是医院。", "超市": "正确。超市卖食品和蔬菜，符合“去……买菜”的语境。", "银行": "语义：银行是办理存取款的地方，不卖菜。", "书店": "搭配：书店卖的是书，不说在书店“买菜”。"}, "sentence_index": 0, "correct_answer": "超市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去超市看病。", "explanation": "这里应该用〈医院〉。超市是卖东西的地方，不能用来看病。"}, {"text": "我们去超市看电影。", "explanation": "这里应该用〈电影院〉。超市卖食品和日用品，不放映电影，“去超市看电影”不符合实际。"}, {"text": "我们坐超市去学校。", "explanation": "“坐”后面要接交通工具，超市不是交通工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不是工作的地方，“在书包工作”说不通。"}, {"text": "超市", "is_correct": true, "explanation": "正确。超市是工作场所，符合“他在……工作”的语境。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是插花的器物，不是工作的地方，“在花瓶工作”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：窗户不是工作场所，不能用于“在……工作”。"}], "explanations": {"书包": "语义：书包是装东西的袋子，不是工作的地方，“在书包工作”说不通。", "超市": "正确。超市是工作场所，符合“他在……工作”的语境。", "花瓶": "语义：花瓶是插花的器物，不是工作的地方，“在花瓶工作”说不通。", "窗户": "搭配：窗户不是工作场所，不能用于“在……工作”。"}, "sentence_index": 6, "correct_answer": "超市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去超市剪头发。", "explanation": "这里应该用〈理发店〉。超市卖食品和日用品，不提供理发服务，“去超市剪头发”不符合实际。"}, {"text": "我去超市寄信。", "explanation": "这里应该用〈邮局〉。寄信要去邮局，超市卖食品和日用品，不办理寄信。"}, {"text": "我借了超市一本书。", "explanation": "“借”的对象应是人，超市是场所，不能向它借书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我朋友在街角开了一只超市。", "corrected_sentence": "我朋友在街角开了一家超市。", "error_description": "错误在量词“只”：超市的量词应用“家”，“只”多用于动物，不能用于商店。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他超市里买了两瓶酸奶。", "corrected_sentence": "他在超市里买了两瓶酸奶。", "error_description": "错误：“超市里买了”；正确：“在超市里买了”。表示动作发生的处所要用介词“在”引出，缺少“在”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21362, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出售", "is_correct": true, "explanation": "反义：“购买”是花钱买进，“出售”是把东西卖出去，二者意思相反。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”是把坏了的东西弄好，与“购买”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”是动脑子想问题，与“购买”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”是慢慢走路，与“购买”没有反义关系。"}], "correct_answer": "出售", "explanations": {"出售": "反义：“购买”是花钱买进，“出售”是把东西卖出去，二者意思相反。", "修理": "无关：“修理”是把坏了的东西弄好，与“购买”没有反义关系。", "思考": "无关：“思考”是动脑子想问题，与“购买”没有反义关系。", "散步": "无关：“散步”是慢慢走路，与“购买”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21362, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出售", "is_correct": true, "explanation": "反义：“购买”是花钱买进，“出售”是把东西卖出去，二者意思相反。"}, {"text": "写作", "is_correct": false, "explanation": "无关：“写作”是写文章，与“购买”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "无关：“跑步”是快速移动身体，与“购买”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：“睡觉”是休息，与“购买”没有反义关系。"}], "correct_answer": "出售", "explanations": {"出售": "反义：“购买”是花钱买进，“出售”是把东西卖出去，二者意思相反。", "写作": "无关：“写作”是写文章，与“购买”没有反义关系。", "跑步": "无关：“跑步”是快速移动身体，与“购买”没有反义关系。", "睡觉": "无关：“睡觉”是休息，与“购买”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21362, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用钱买东西。", "primary_collocate": null, "pronunciation": "gòu mǎi", "ipa": "koʊ˥˩ maɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在网上购买了一台电脑。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这里购买火车票。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客可以用现金购买。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想购买一辆新车。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她购买了很多水果。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以用手机购买电影票。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这家店不能购买药品。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "购买之前，他问了朋友的意见。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人喜欢在节日购买礼物。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定购买新的机器。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "购买了", "label": "体标"}, {"form": "购买过", "label": "体标"}, {"form": "購買", "label": "繁体"}, {"form": "购买力", "label": "复合"}, {"form": "购买者", "label": "复合"}], "register": "书面", "sense_fingerprint": "花钱买下东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b26b9a-9d68-4360-8cd8-e1c05a934069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：“唱”后面不能跟“电脑”这样的物品，句子说不通。"}, {"text": "购买", "is_correct": true, "explanation": "购买：用钱买下东西，此处指在网上花钱买了一台电脑。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，后面不能带“电脑”作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "语义：电脑不是可以吃的东西，“吃”与“电脑”不搭。"}], "explanations": {"唱": "搭配：“唱”后面不能跟“电脑”这样的物品，句子说不通。", "购买": "购买：用钱买下东西，此处指在网上花钱买了一台电脑。", "游泳": "配价：“游泳”是不及物动词，后面不能带“电脑”作宾语。", "吃": "语义：电脑不是可以吃的东西，“吃”与“电脑”不搭。"}, "sentence_index": 0, "correct_answer": "购买"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个星期都去图书馆购买书。", "explanation": "这里应该用〈借〉。“我”去图书馆是借阅书籍，不用付钱，不是购买；图书馆自己采购书籍才可以说购买。"}, {"text": "学生们在办公室购买了免费的课本。", "explanation": "这里应该用〈领取〉。课本是免费发放的，不用花钱，与“购买”矛盾。"}, {"text": "朋友免费购买了一台旧电脑送给我。", "explanation": "这里应该用〈赠送〉。“免费”与“购买”矛盾，购买要付钱；把东西送人要用赠送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，后面不能带“药品”作宾语。"}, {"text": "购买", "is_correct": true, "explanation": "购买：用钱买下东西，此处指顾客在这家店不能买到药品。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是风景、艺术，不跟“药品”搭配。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，后面不能直接带“药品”作宾语。"}], "explanations": {"散步": "配价：“散步”是不及物动词，后面不能带“药品”作宾语。", "购买": "购买：用钱买下东西，此处指顾客在这家店不能买到药品。", "欣赏": "搭配：“欣赏”的对象是风景、艺术，不跟“药品”搭配。", "咳嗽": "配价：“咳嗽”是不及物动词，后面不能直接带“药品”作宾语。"}, "sentence_index": 6, "correct_answer": "购买"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司向小公司购买了一批旧机器，收到了一笔钱。", "explanation": "这里应该用〈出售〉。收到钱说明是卖出去，购买则是付钱买进，二者矛盾。"}, {"text": "他购买了这个木箱，是他亲手做的。", "explanation": "这里应该用〈制作〉。亲手做的东西不是买来的，“购买”与“是他亲手做的”矛盾。"}, {"text": "他从父亲那里购买了这家店铺，一分钱也没有花。", "explanation": "这里应该用〈继承〉。“一分钱也没有花”与购买要付钱矛盾；从父母那里得到财产要用继承。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在超市购买了过一箱牛奶。", "corrected_sentence": "妈妈在超市购买过一箱牛奶。", "error_description": "体标重复：“购买”后面只能用一个动态助词。“了”和“过”同时用在“购买”后面，应只保留“过”，说“购买过”，不能说“购买了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明天要购买了一辆新车。", "corrected_sentence": "他明天要购买一辆新车。", "error_description": "体标错误：“明天要”表示将来的事情，“购买”后面不能用表示完成的“了”，应去掉“了”，说“明天要购买一辆新车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
