INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21364, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们做出来卖的东西。", "primary_collocate": null, "pronunciation": "chǎn pǐn", "ipa": "ʈʂʰan˨˩˦ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家公司的产品卖得很好。", "target_word": "产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的新产品下个月上市。", "target_word": "产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个产品用起来很方便。", "target_word": "产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在商店里看了很多产品。", "target_word": "产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好产品不怕贵。", "target_word": "产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种产品对孩子很安全。", "target_word": "产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在检查产品的质量。", "target_word": "产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个产品的价格有点贵。", "target_word": "产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理给客人介绍了新产品。", "target_word": "产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些产品都是工厂自己做的。", "target_word": "产品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "產品", "label": "繁体"}, {"form": "新产品", "label": "复合"}, {"form": "产品经理", "label": "复合"}], "register": "中性", "sense_fingerprint": "生产出来用于出售的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b26b9a-9d68-4360-8cd8-e1c05a934069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "办公室", "is_correct": false, "explanation": "语义：办公室是工作的场所，不是商品，不能说“卖得很好”。"}, {"text": "产品", "is_correct": true, "explanation": "产品：人们生产出来用于出售的东西，与“卖得很好”相配。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“卖”的对象是商品，不能说“卖价格”。"}, {"text": "文件", "is_correct": false, "explanation": "语义：文件不是商品，不能说“卖得很好”。"}], "explanations": {"办公室": "语义：办公室是工作的场所，不是商品，不能说“卖得很好”。", "产品": "产品：人们生产出来用于出售的东西，与“卖得很好”相配。", "价格": "搭配：“卖”的对象是商品，不能说“卖价格”。", "文件": "语义：文件不是商品，不能说“卖得很好”。"}, "sentence_index": 0, "correct_answer": "产品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位作家的产品很有名。", "explanation": "这里应该用〈作品〉。作品指文学、艺术等创作的成果，产品指工厂生产、用于出售的东西，不能用来指作家的著作。"}, {"text": "这座大桥是团队花了三年完成的产品。", "explanation": "这里应该用〈工程〉。大桥是建造出来的工程，产品指工厂生产、用于出售的东西，不能用来指一座桥。"}, {"text": "妈妈在厨房里生了一个产品。", "explanation": "这里应该用〈孩子〉。“生”多用于人或动物，产品是人们生产出来用于出售的东西，不能说“生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病", "is_correct": false, "explanation": "语义：病是疾病，没有质量可以让工人检查。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“质量”说的是物品的好坏，不跟“名字”搭配。"}, {"text": "产品", "is_correct": true, "explanation": "产品：工厂生产出来的物品，有质量可以检查。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是感受，工人不会去检查它的质量。"}], "explanations": {"病": "语义：病是疾病，没有质量可以让工人检查。", "名字": "搭配：“质量”说的是物品的好坏，不跟“名字”搭配。", "产品": "产品：工厂生产出来的物品，有质量可以检查。", "心情": "语义：心情是感受，工人不会去检查它的质量。"}, "sentence_index": 6, "correct_answer": "产品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个化学反应的产品是水。", "explanation": "这里应该用〈产物〉。化学反应生成的物质一般说产物，产品指人们生产出来用于出售的东西。"}, {"text": "这块田的产品长得很好。", "explanation": "这里应该用〈作物〉。作物是田里种植、生长的植物，产品指人们生产出来用于出售的东西，不会“长”。"}, {"text": "老师正在批改学生的产品。", "explanation": "这里应该用〈作业〉。老师批改的是学生的作业，产品指人们生产出来用于出售的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司推出了三只新产品。", "corrected_sentence": "我们公司推出了三种新产品。", "error_description": "量词错误：“产品”不用“只”计量（“只”多用于动物和成对物品中的一个），应改为“种”，说“三种新产品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些产品们都很受欢迎。", "corrected_sentence": "这些产品都很受欢迎。", "error_description": "词尾错误：“产品”是无生命的东西，一般不加“们”表示复数，应说“这些产品”。“们”多用于指人的名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53a40b39-1e4b-40af-9a4c-51f680758502') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
