INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21366, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21366, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西从一个地方送到另一个地方。", "primary_collocate": null, "pronunciation": "yùn shū", "ipa": "yn˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "这些水果用卡车运输到城里。", "target_word": "运输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物用船运输比较便宜。", "target_word": "运输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机可以快速运输新鲜的海产品。", "target_word": "运输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在运输建筑材料。", "target_word": "运输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门运输冷冻食品。", "target_word": "运输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路很窄，大车没法运输木头。", "target_word": "运输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车把煤炭运输到南方。", "target_word": "运输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用大船运输了很多大米。", "target_word": "运输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪天，运输蔬菜会变慢。", "target_word": "运输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车只能运输一吨货。", "target_word": "运输", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "运输了", "label": "体标"}, {"form": "运输着", "label": "体标"}, {"form": "运输过", "label": "体标"}, {"form": "运输车", "label": "复合"}, {"form": "运输船", "label": "复合"}], "register": "中性", "sense_fingerprint": "用车、船、飞机等把货物送到别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd26c9eef-4edc-40c1-a354-68e7e6b9dc50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21366, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运输", "is_correct": true, "explanation": "正确：“运输”指用车船送货物，“用卡车运输到城里”通顺。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物，不能表示用卡车送货，句子说不通。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍”是用手掌打或拍照，不能表示用卡车运送货物，句子说不通。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是加热，不能表示运送货物，句子说不通。"}], "explanations": {"运输": "正确：“运输”指用车船送货物，“用卡车运输到城里”通顺。", "煮": "语义：“煮”是加热食物，不能表示用卡车送货，句子说不通。", "拍": "语义：“拍”是用手掌打或拍照，不能表示用卡车运送货物，句子说不通。", "烤": "语义：“烤”是加热，不能表示运送货物，句子说不通。"}, "sentence_index": 0, "correct_answer": "运输"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们今天运输进了新房。", "explanation": "这里应该用〈搬〉。“运输”指用车船运送货物，人搬进新家要用“搬”。"}, {"text": "我运输了一封信给老师。", "explanation": "这里应该用〈寄〉。“运输”指大批货物的运送，寄一封信要用“寄”。"}, {"text": "他运输着书包去上学。", "explanation": "这里应该用〈背〉。“运输”用于货物，背书包上学要用“背”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运输", "is_correct": true, "explanation": "正确：“运输”指用火车等把大批货物送到别处，“火车把煤炭运输到南方”通顺。"}, {"text": "熬", "is_correct": false, "explanation": "语义：“熬”是慢慢加热或忍耐，不能表示把煤炭送到南方，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“煤炭”搭配作宾语，“把煤炭唱到南方”不成立。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洁，不能表示把煤炭送到南方，句子说不通。"}], "explanations": {"运输": "正确：“运输”指用火车等把大批货物送到别处，“火车把煤炭运输到南方”通顺。", "熬": "语义：“熬”是慢慢加热或忍耐，不能表示把煤炭送到南方，句子说不通。", "唱": "搭配：“唱”不能与“煤炭”搭配作宾语，“把煤炭唱到南方”不成立。", "洗": "语义：“洗”是清洁，不能表示把煤炭送到南方，句子说不通。"}, "sentence_index": 6, "correct_answer": "运输"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈运输着一束花回家。", "explanation": "这里应该用〈拿〉。“运输”指用车船运送大批货物，手里拿一束花回家要用“拿”。"}, {"text": "他运输着一把伞上楼。", "explanation": "这里应该用〈拿〉。“运输”指用车船运送大批货物，手里拿一把伞上楼要用“拿”。"}, {"text": "老师运输着学生去参观。", "explanation": "这里应该用〈带〉。“运输”用于货物，带学生去参观要用“带”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "港口正在用轮船运输了石油。", "corrected_sentence": "港口正在用轮船运输石油。", "error_description": "错误在体标：“正在”表示动作进行中，不与完成标记“了”同用，应说“正在运输石油”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们正在煤炭运输到码头。", "corrected_sentence": "工人们正在把煤炭运输到码头。", "error_description": "错误在“把”字句：处置宾语“煤炭”前要用“把”，应说“把煤炭运输到码头”，不能省去“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df46aac7-2890-436a-8430-9a3819e2362a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
