INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21368, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21368, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "把某些人或事物放进或算在某个整体之内。", "primary_collocate": null, "pronunciation": "bāo kuò", "ipa": "pɑu˥ kuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "这次旅行的费用包括饭钱。", "target_word": "包括", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班有二十个人，包括老师。", "target_word": "包括", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格包括早饭和晚饭。", "target_word": "包括", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他会说很多语言，包括中文和日语。", "target_word": "包括", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书包括十个小故事。", "target_word": "包括", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我买的东西包括水果、牛奶和面包。", "target_word": "包括", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房租不包括水电费，要自己付。", "target_word": "包括", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的爱好很多，包括游泳和跑步。", "target_word": "包括", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张票包括了一顿午饭。", "target_word": "包括", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全家人都去了，包括奶奶。", "target_word": "包括", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "包括了", "label": "体标"}], "register": "中性", "sense_fingerprint": "把某些人或事物放进或算在整体之内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425e7d8f-3989-4c55-aef2-e45784558d9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21368, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包括", "is_correct": true, "explanation": "正确：“包括”表示整体中含有“饭钱”这一部分，与句意相合。"}, {"text": "支付", "is_correct": false, "explanation": "配价：“支付”需要付款人作主语，“费用”不能作付款人，不能说“费用支付饭钱”。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”的主语须是人，“费用讨论饭钱”不通。"}, {"text": "需要", "is_correct": false, "explanation": "语义：“需要”表示需求，“费用需要饭钱”与旅行费用的构成意义不符。"}], "explanations": {"包括": "正确：“包括”表示整体中含有“饭钱”这一部分，与句意相合。", "支付": "配价：“支付”需要付款人作主语，“费用”不能作付款人，不能说“费用支付饭钱”。", "讨论": "语义：“讨论”的主语须是人，“费用讨论饭钱”不通。", "需要": "语义：“需要”表示需求，“费用需要饭钱”与旅行费用的构成意义不符。"}, "sentence_index": 0, "correct_answer": "包括"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动的费用包括了预算。", "explanation": "这里应该用〈超出〉。“包括”表示整体中含有某部分，预算不是费用的一部分；说费用高于预算要用“超出”。"}, {"text": "这些水果包括农场。", "explanation": "这里应该用〈来自〉。“包括”说的是整体含有的部分，农场不是水果的组成部分；说来源要用“来自”。"}, {"text": "这座公园包括城东。", "explanation": "这里应该用〈位于〉。“包括”表示含有，说公园所在的地理位置要用“位于”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包括", "is_correct": true, "explanation": "正确：“房租不包括水电费”表示房租里不含水电费，要自己付，与句意一致。"}, {"text": "认识", "is_correct": false, "explanation": "语义：“认识”表示理解或了解，“房租不认识水电费”与句意不符。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”需要有情感的主体，房租不能“喜欢”水电费。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是有故障的器物，“水电费”不能被修理。"}], "explanations": {"包括": "正确：“房租不包括水电费”表示房租里不含水电费，要自己付，与句意一致。", "认识": "语义：“认识”表示理解或了解，“房租不认识水电费”与句意不符。", "喜欢": "语义：“喜欢”需要有情感的主体，房租不能“喜欢”水电费。", "修理": "搭配：“修理”的对象是有故障的器物，“水电费”不能被修理。"}, "sentence_index": 6, "correct_answer": "包括"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师包括我们班，所以全班都要听课。", "explanation": "“包括”的整体与部分颠倒了。应说“我们班包括老师”，“老师包括我们班”用错了关系。"}, {"text": "三个学生包括学校，所以学校很小。", "explanation": "“包括”的整体与部分颠倒了。应说“学校包括三个学生”，这里用错了关系。"}, {"text": "这个城市包括我们省，所以我们很熟悉这里。", "explanation": "“包括”的整体与部分颠倒了。应说“我们省包括这个城市”，“城市包括省”用错了关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动包括过很多游戏。", "corrected_sentence": "这次活动包括很多游戏。", "error_description": "体标错误：“包括”表示含有，不用“过”表示经历；“包括过很多游戏”不通。正确形式是“这次活动包括很多游戏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份保险不包括在牙科，要另外买。", "corrected_sentence": "这份保险不包括牙科，要另外买。", "error_description": "结构错误：“包括”后直接接宾语，不能插入“在”；“在”只用于“包括在……之中/内”的格式。正确形式是“不包括牙科”，“不包括在牙科”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
