INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21370, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西卖给别人，换回钱。", "primary_collocate": null, "pronunciation": "xiāo shòu", "ipa": "ɕjɑʊ˥ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这家店专门销售旧书。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司销售电脑和手机。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶在国外也销售得很好。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在网上销售水果。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店不能销售过期的牛奶。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些衣服只在春天销售。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把新产品销售到了很多城市。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里销售各种各样的零食。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在市场上销售自己做的面包。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的鞋子已经销售了一百双。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "销售", "label": "基本形"}, {"form": "销售了", "label": "体标（了）"}, {"form": "销售过", "label": "体标（过）"}, {"form": "銷售", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把东西卖给别人换钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bca74fc9-b4a9-4068-a7f1-1de1a45d97e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "销售", "is_correct": true, "explanation": "店铺专门卖旧书，“销售”指卖出商品换钱，与“专门”搭配。"}, {"text": "培育", "is_correct": false, "explanation": "语义：培育是培养动植物或人才，旧书不能被培育，句子说不通。"}, {"text": "讲解", "is_correct": false, "explanation": "语义：讲解的对象是内容或知识，不能讲解一批旧书。"}, {"text": "制作", "is_correct": false, "explanation": "语义：这家店经营的旧书是现成的，不是制作出来的。"}], "explanations": {"销售": "店铺专门卖旧书，“销售”指卖出商品换钱，与“专门”搭配。", "培育": "语义：培育是培养动植物或人才，旧书不能被培育，句子说不通。", "讲解": "语义：讲解的对象是内容或知识，不能讲解一批旧书。", "制作": "语义：这家店经营的旧书是现成的，不是制作出来的。"}, "sentence_index": 0, "correct_answer": "销售"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些旧书免费销售给学生。", "explanation": "这里应该用〈赠送〉。“销售”要收钱换回钱，免费给人要说赠送。"}, {"text": "我们把设备销售给客户使用一个月。", "explanation": "这里应该用〈出租〉。“销售”是卖断，物品归买方；只让对方使用一段时间要说出租。"}, {"text": "他把过期的牛奶销售到了垃圾桶里。", "explanation": "这里应该用〈丢弃〉。“销售”要卖给人换钱，扔掉的东西要说丢弃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "销售", "is_correct": true, "explanation": "把新产品卖到很多城市，“销售”指卖出换钱，与“到了很多城市”搭配。"}, {"text": "研发", "is_correct": false, "explanation": "配价：“研发”不能带“到……城市”这样的去向宾语。"}, {"text": "发明", "is_correct": false, "explanation": "语义：发明的是新事物，不是把产品送到各地。"}, {"text": "撤回", "is_correct": false, "explanation": "语义：撤回是收回，与把新产品送往多个城市的方向相反。"}], "explanations": {"销售": "把新产品卖到很多城市，“销售”指卖出换钱，与“到了很多城市”搭配。", "研发": "配价：“研发”不能带“到……城市”这样的去向宾语。", "发明": "语义：发明的是新事物，不是把产品送到各地。", "撤回": "语义：撤回是收回，与把新产品送往多个城市的方向相反。"}, "sentence_index": 6, "correct_answer": "销售"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把自己的旧衣服销售给了灾区。", "explanation": "这里应该用〈捐赠〉。“销售”要收钱，捐给灾区不收钱要说捐赠。"}, {"text": "我把书销售给同学看了三天。", "explanation": "这里应该用〈借〉。“销售”是卖断，借给别人看一段时间要说“借”。"}, {"text": "他们用玩具销售了一本书。", "explanation": "这里应该用〈交换〉。“销售”要收钱，用物品换物品要说交换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司去年销售着一千台电脑。", "corrected_sentence": "我们公司去年销售了一千台电脑。", "error_description": "错误在“销售”后的动态助词。去年已经完成的销售应用“了”，“着”表示持续状态，不能用于已完成的事件，应说“销售了一千台电脑”，不能说“销售着一千台电脑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款洗衣机销售地很好。", "corrected_sentence": "这款洗衣机销售得很好。", "error_description": "错误在补语的结构助词。“销售”后接程度补语，要用“得”，“地”只用于状语，应说“销售得很好”，不能说“销售地很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
