INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21372, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用身体或东西挨着别的东西。", "primary_collocate": null, "pronunciation": "kào", "ipa": "kʰau˥˩", "syllable_count": 1, "sentences": [{"text": "他靠着墙站在门口。", "target_word": "靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢靠着窗户坐。", "target_word": "靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人靠在椅子上睡着了。", "target_word": "靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把自行车靠在树旁边。", "target_word": "靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗靠着我的腿躺下。", "target_word": "靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠着车门站了很久。", "target_word": "靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她累了，把头靠在我的肩上。", "target_word": "靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梯子靠在墙上，很不安全。", "target_word": "靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别靠门站着，有人要进来。", "target_word": "靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子靠着妈妈坐在沙发上。", "target_word": "靠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "靠着", "label": "体标（着）"}, {"form": "靠了", "label": "体标（了）"}, {"form": "靠过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "用身体或物体挨着、倚着别的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e7fa8c-7e28-4a9f-9f73-de782ccd99f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21372, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "靠", "is_correct": true, "explanation": "正确答案：靠（kào），指用身体或东西挨着别的东西。"}, {"text": "烤", "is_correct": false, "explanation": "声调不同：“烤”（kǎo，第三声）与“靠”（kào，第四声）不同，“烤”意思是烘烤。"}, {"text": "考", "is_correct": false, "explanation": "声调不同：“考”（kǎo，第三声）与“靠”（kào，第四声）不同，“考”意思是考试。"}, {"text": "告", "is_correct": false, "explanation": "声母不同：“告”（gào）与“靠”（kào）的声母 g 与 k 不同，“告”意思是告诉。"}, {"text": "套", "is_correct": false, "explanation": "声母不同：“套”（tào）与“靠”（kào）的声母 t 与 k 不同，声调与韵母相同，“套”意思是套子、套装。"}], "explanations": {"靠": "正确答案：靠（kào），指用身体或东西挨着别的东西。", "烤": "声调不同：“烤”（kǎo，第三声）与“靠”（kào，第四声）不同，“烤”意思是烘烤。", "考": "声调不同：“考”（kǎo，第三声）与“靠”（kào，第四声）不同，“考”意思是考试。", "告": "声母不同：“告”（gào）与“靠”（kào）的声母 g 与 k 不同，“告”意思是告诉。", "套": "声母不同：“套”（tào）与“靠”（kào）的声母 t 与 k 不同，声调与韵母相同，“套”意思是套子、套装。"}, "sentence_index": null, "correct_answer": "靠"}, "level_3": {"options": [{"text": "靠", "is_correct": true, "explanation": "正确答案：“他靠着墙站在门口”中的“靠”表示挨着、倚着。"}, {"text": "拿", "is_correct": false, "explanation": "语义：“拿”指用手握住可以拿起的东西，墙不能被拿。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象应是食物，墙不能被吃。"}, {"text": "搬", "is_correct": false, "explanation": "配价：“搬”要求可以移动的物体作宾语，墙不能被搬动。"}], "explanations": {"靠": "正确答案：“他靠着墙站在门口”中的“靠”表示挨着、倚着。", "拿": "语义：“拿”指用手握住可以拿起的东西，墙不能被拿。", "吃": "语义：“吃”的对象应是食物，墙不能被吃。", "搬": "配价：“搬”要求可以移动的物体作宾语，墙不能被搬动。"}, "sentence_index": 0, "correct_answer": "靠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钱靠在桌子上。", "explanation": "这里的“靠”表示挨着，但钱一般说“放在”桌子上，不能说“靠在”桌子上。"}, {"text": "她把书靠在脑袋上读。", "explanation": "这里的“靠”表示挨着，但读书时一般说“拿在手里”或“放在桌上”，不能说“靠在脑袋上”。"}, {"text": "他把手靠在水里洗菜。", "explanation": "这里的“靠”表示挨着，但手不能靠在水里洗菜；这种情况应说“泡在水里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21372, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "靠", "is_correct": true, "explanation": "正确答案：靠（kào），指用身体或东西挨着别的东西。"}, {"text": "扣", "is_correct": false, "explanation": "韵母不同：“扣”（kòu）与“靠”（kào）的韵母 ou 与 ao 不同，“扣”意思是扣子或扣住。"}, {"text": "号", "is_correct": false, "explanation": "声母不同：“号”（hào）与“靠”（kào）的声母 h 与 k 不同，声调与韵母相同，“号”意思是号码。"}, {"text": "拷", "is_correct": false, "explanation": "声调不同：“拷”（kǎo，第三声）与“靠”（kào，第四声）不同，“拷”意思是拷问、拷贝。"}, {"text": "告", "is_correct": false, "explanation": "声母不同：“告”（gào）与“靠”（kào）的声母 g 与 k 不同，声调与韵母相同，“告”意思是告诉。"}], "explanations": {"靠": "正确答案：靠（kào），指用身体或东西挨着别的东西。", "扣": "韵母不同：“扣”（kòu）与“靠”（kào）的韵母 ou 与 ao 不同，“扣”意思是扣子或扣住。", "号": "声母不同：“号”（hào）与“靠”（kào）的声母 h 与 k 不同，声调与韵母相同，“号”意思是号码。", "拷": "声调不同：“拷”（kǎo，第三声）与“靠”（kào，第四声）不同，“拷”意思是拷问、拷贝。", "告": "声母不同：“告”（gào）与“靠”（kào）的声母 g 与 k 不同，声调与韵母相同，“告”意思是告诉。"}, "sentence_index": null, "correct_answer": "靠"}, "level_3": {"options": [{"text": "靠", "is_correct": true, "explanation": "正确答案：“把头靠在我的肩上”中的“靠”表示头挨着肩膀。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”表示用牙齿咬住，与头放在肩上的动作不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示抛掷，头不能被扔在肩上。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”用于把物体悬挂起来，不说“把头挂在肩上”。"}], "explanations": {"靠": "正确答案：“把头靠在我的肩上”中的“靠”表示头挨着肩膀。", "咬": "语义：“咬”表示用牙齿咬住，与头放在肩上的动作不符。", "扔": "语义：“扔”表示抛掷，头不能被扔在肩上。", "挂": "搭配：“挂”用于把物体悬挂起来，不说“把头挂在肩上”。"}, "sentence_index": 6, "correct_answer": "靠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他靠了一巴掌。", "explanation": "这里应该用〈挨〉。“挨一巴掌”表示受到打击，“靠”没有这种用法。"}, {"text": "他靠了一顿骂。", "explanation": "这里应该用〈挨〉。“挨骂”表示遭受责骂，“靠”没有这种用法。"}, {"text": "他一下午都把这件事靠在心上。", "explanation": "这里应该用〈放〉。“放在心上”表示记挂、重视；“靠”表示挨着，不能说“靠在心上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫靠沙发上睡觉。", "corrected_sentence": "小猫靠在沙发上睡觉。", "error_description": "介词“在”缺失：“靠”后面接处所时，常说“靠在……上”，不能说“靠沙发上”，应说“靠在沙发上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她靠着椅背着睡着了。", "corrected_sentence": "她靠着椅背睡着了。", "error_description": "错误：多加了一个“着”。正确：“靠着”已含“着”，后面不能再加“着”，应说“她靠着椅背睡着了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
