INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21374, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西从做出来到大家手里，中间经过的人或公司。", "primary_collocate": null, "pronunciation": "gōng yìng liàn", "ipa": "kʊŋ˥ iŋ˥˩ ljɛn˥˩", "syllable_count": 3, "sentences": [{"text": "这家工厂的供应链很稳定。", "target_word": "供应链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情让全球供应链出了问题。", "target_word": "供应链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司负责管理供应链。", "target_word": "供应链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "供应链断了，商店就没有货。", "target_word": "供应链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的供应链能让价格便宜一些。", "target_word": "供应链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个品牌正在改变它的供应链。", "target_word": "供应链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找新的供应链伙伴。", "target_word": "供应链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "供应链太长，运货的时间也长。", "target_word": "供应链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的供应链涉及很多国家。", "target_word": "供应链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把供应链放在本国。", "target_word": "供应链", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "全球供应链", "label": "复合"}, {"form": "供应链管理", "label": "复合"}, {"form": "供应链金融", "label": "复合"}], "register": "中性", "sense_fingerprint": "商品从生产到消费者之间相连的各个环节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26dbc4a2-a243-4c22-9f23-9c2db77eb70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "供应链", "is_correct": true, "explanation": "供应链：指从生产到消费者之间相连的各环节，“很稳定”描述其运行状况。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”指人的情绪，工厂没有心情，不能“很稳定”。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“学历”只用于人，不能与“工厂”搭配。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”描述人或动物的外形，不用于工厂。"}], "explanations": {"供应链": "供应链：指从生产到消费者之间相连的各环节，“很稳定”描述其运行状况。", "心情": "语义：“心情”指人的情绪，工厂没有心情，不能“很稳定”。", "学历": "搭配：“学历”只用于人，不能与“工厂”搭配。", "身高": "体貌：“身高”描述人或动物的外形，不用于工厂。"}, "sentence_index": 0, "correct_answer": "供应链"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们换了一台新的供应链。", "explanation": "这里应该用〈条〉。供应链是抽象的网络，量词用“条”，“台”用于机器。"}, {"text": "我们在这条供应链里游了一会儿泳。", "explanation": "这里应该用〈泳池〉。供应链是环节的网络，不是可以游泳的地方。"}, {"text": "我每天在这个供应链上骑车回家。", "explanation": "这里应该用〈马路〉。供应链是抽象的环节网络，不是骑车的道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "供应链", "is_correct": true, "explanation": "供应链：指生产到消费者之间的环节网络，“伙伴”指与之合作的环节或企业。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能作合作的“伙伴”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是事物的属性，不能成为“伙伴”。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“学费”不能修饰“伙伴”，“新的学费伙伴”不成立。"}], "explanations": {"供应链": "供应链：指生产到消费者之间的环节网络，“伙伴”指与之合作的环节或企业。", "天气": "语义：“天气”是自然现象，不能作合作的“伙伴”。", "颜色": "语义：“颜色”是事物的属性，不能成为“伙伴”。", "学费": "搭配：“学费”不能修饰“伙伴”，“新的学费伙伴”不成立。"}, "sentence_index": 6, "correct_answer": "供应链"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司在市中心租了一间供应链。", "explanation": "这里应该用〈办公室〉。供应链是环节的网络，不是可以租用的房间。"}, {"text": "我们的供应链每天都去跑步。", "explanation": "这里应该用〈员工〉。去跑步的是人，供应链是环节的网络，不能跑步。"}, {"text": "周末我们在供应链里散步。", "explanation": "这里应该用〈公园〉。供应链是抽象的环节网络，不是可以散步的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司重新设计了一台供应链。", "corrected_sentence": "这家公司重新设计了一条供应链。", "error_description": "量词错误：“供应链”应用量词“条”，“台”用于机器。应为：这家公司重新设计了一条供应链。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的供应链长很。", "corrected_sentence": "我们的供应链很长。", "error_description": "语序错误：“很”应放在形容词“长”之前，说“很长”，不能说“长很”。应为：我们的供应链很长。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "断开", "is_correct": true, "explanation": "正确：“断开”与“连接”意思相反，指使两个东西分离。"}, {"text": "保持", "is_correct": false, "explanation": "与“连接”没有反义关系，“保持”指维持原状。"}, {"text": "进入", "is_correct": false, "explanation": "与“连接”没有反义关系，“进入”指从外面到里面。"}, {"text": "观察", "is_correct": false, "explanation": "与“连接”没有反义关系，“观察”指仔细地看。"}], "correct_answer": "断开", "explanations": {"断开": "正确：“断开”与“连接”意思相反，指使两个东西分离。", "保持": "与“连接”没有反义关系，“保持”指维持原状。", "进入": "与“连接”没有反义关系，“进入”指从外面到里面。", "观察": "与“连接”没有反义关系，“观察”指仔细地看。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分离", "is_correct": true, "explanation": "正确：“分离”与“连接”意思相反，指使两个东西分开。"}, {"text": "修理", "is_correct": false, "explanation": "与“连接”没有反义关系，“修理”指修补使其恢复正常。"}, {"text": "支持", "is_correct": false, "explanation": "与“连接”没有反义关系，“支持”指给予帮助或撑持。"}, {"text": "参加", "is_correct": false, "explanation": "与“连接”没有反义关系，“参加”指加入某项活动。"}], "correct_answer": "分离", "explanations": {"分离": "正确：“分离”与“连接”意思相反，指使两个东西分开。", "修理": "与“连接”没有反义关系，“修理”指修补使其恢复正常。", "支持": "与“连接”没有反义关系，“支持”指给予帮助或撑持。", "参加": "与“连接”没有反义关系，“参加”指加入某项活动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让两个东西合在一起。", "primary_collocate": null, "pronunciation": "lián jiē", "ipa": "ljɛn˧˥ tɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "这座桥连接着两个城市。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把电脑和电视连接起来。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路连接山上和山下。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手机连接了无线网。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路连接北京和上海。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用电线把两台机器连接好了。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络把世界各地的人连接在一起。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个门连接着客厅和厨房。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的手机连接上耳机了吗？", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两条小河在这里连接，变成一条大河。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连接了", "label": "体标"}, {"form": "连接着", "label": "体标"}, {"form": "連接", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使两个事物接在一起或相通", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d81d48-6f38-42b1-91d4-5cab678d6582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "语义：桥不能“参观”城市，参观是人去看一个地方。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象一般是房间、地面，不说“打扫两个城市”。"}, {"text": "离开", "is_correct": false, "explanation": "语义：桥与城市是相连的，不是“离开”，“离开着两个城市”说不通。"}, {"text": "连接", "is_correct": true, "explanation": "正确：“连接着两个城市”说桥把两个城市接在一起，与语境相符。"}], "explanations": {"参观": "语义：桥不能“参观”城市，参观是人去看一个地方。", "打扫": "搭配：“打扫”的对象一般是房间、地面，不说“打扫两个城市”。", "离开": "语义：桥与城市是相连的，不是“离开”，“离开着两个城市”说不通。", "连接": "正确：“连接着两个城市”说桥把两个城市接在一起，与语境相符。"}, "sentence_index": 0, "correct_answer": "连接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和他是去年连接的。", "explanation": "这里应该用〈认识〉。“连接”指事物之间的接通，人与人初次相识要说“认识”。"}, {"text": "他一直连接我，想让我帮忙。", "explanation": "这里应该用〈找〉。“连接”指事物之间的接通，找人、与人取得联系不用“连接”。"}, {"text": "两家公司连接以后，成立了一个新公司。", "explanation": "这里应该用〈联合〉。“连接”指物体之间的接通，公司之间的合作要说“联合”或“合并”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分开", "is_correct": false, "explanation": "语义：“分开”与“在一起”意思相反，句子自相矛盾。"}, {"text": "拆散", "is_correct": false, "explanation": "语义：“拆散”指使分离，与“在一起”矛盾。"}, {"text": "隔开", "is_correct": false, "explanation": "搭配：“隔开”后面一般接处所或对象，与“在一起”搭配不当。"}, {"text": "连接", "is_correct": true, "explanation": "正确：“连接在一起”说把人联系起来，与“在一起”相符。"}], "explanations": {"分开": "语义：“分开”与“在一起”意思相反，句子自相矛盾。", "拆散": "语义：“拆散”指使分离，与“在一起”矛盾。", "隔开": "搭配：“隔开”后面一般接处所或对象，与“在一起”搭配不当。", "连接": "正确：“连接在一起”说把人联系起来，与“在一起”相符。"}, "sentence_index": 6, "correct_answer": "连接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩连接得很好，每天一起吃饭。", "explanation": "这里应该用〈相处〉。“连接”指事物之间的接通，人与人之间融洽地相处要说“相处”。"}, {"text": "这次考试我连接了三十分。", "explanation": "这里应该用〈得〉。考试分数是“得”来的，不说“连接”。"}, {"text": "他每天连接两个小时的书，成绩一直很好。", "explanation": "这里应该用〈读〉。“连接”不能和书搭配表示阅读，读书要说“读”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把两根水管连接下来了。", "corrected_sentence": "工人把两根水管连接起来了。", "error_description": "补语选错：“连接”后应接趋向补语“起来”，表示连在一起；“下来”不能与“连接”搭配，应说“连接起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们明天连接了两台旧电脑。", "corrected_sentence": "他们明天连接两台旧电脑。", "error_description": "体标错误：“了”表示已经完成，不能用于“明天”这样的将来时间，应说“明天连接两台旧电脑”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
