INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21380, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你需要的东西。", "primary_collocate": null, "pronunciation": "xū qiú", "ipa": "ɕy˥˥ tɕʰjoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "每个孩子的需求都不一样，爸妈要多听听。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人有什么需求，可以直接告诉服务员。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的需求很简单，有吃有住就行。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买手机以前，先想想自己的需求。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不好意思说出自己的需求。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间太小，不能满足我的需求。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很快就明白了客人的需求。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把你的需求写在这张纸上。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的需求不多，一本书一杯茶就够了。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的生活需求，都应该得到关心。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "生活需求", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人或客人所需要的具体东西或要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b69fe6f-45ff-4aa8-b887-4f71b2511eeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21380, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：身高是孩子的体征，不是可以“多听听”的东西，句子说不通。"}, {"text": "需求", "is_correct": true, "explanation": "正确：“每个孩子的需求都不一样”指每个孩子想要的东西不同，“爸妈要多听听”与之搭配，合理。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是凭证，不是孩子想要的东西，“爸妈要多听听门票”没有意义。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票是乘车的凭证，不能被“多听听”，与“不一样”也不构成合理的说法。"}], "explanations": {"身高": "体貌：身高是孩子的体征，不是可以“多听听”的东西，句子说不通。", "需求": "正确：“每个孩子的需求都不一样”指每个孩子想要的东西不同，“爸妈要多听听”与之搭配，合理。", "门票": "语义：门票是凭证，不是孩子想要的东西，“爸妈要多听听门票”没有意义。", "车票": "语义：车票是乘车的凭证，不能被“多听听”，与“不一样”也不构成合理的说法。"}, "sentence_index": 0, "correct_answer": "需求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的需求是明天别下雨。", "explanation": "这里应该用〈希望〉。“需求”指自己需要的东西，不能用来表示对天气的盼望。"}, {"text": "我的需求是当一名老师。", "explanation": "这里应该用〈理想〉。“理想”指心中向往的目标，“需求”指自己必要的东西，不能用来表示职业理想。"}, {"text": "他有一张需求，想请大家帮忙。", "explanation": "这里应该用“种”或“个”。“张”用于纸、桌子等扁平的东西，不能用来计量“需求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21380, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "座位", "is_correct": false, "explanation": "搭配：“明白”多接想法、意思等，不说明白客人的座位。"}, {"text": "需求", "is_correct": true, "explanation": "正确：“明白了客人的需求”指弄清客人想要什么，搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以“明白”的内容，“明白了客人的颜色”说不通。"}, {"text": "身份证", "is_correct": false, "explanation": "语义：身份证是证件，不能作为“明白”的对象，句子没有合理的意思。"}], "explanations": {"座位": "搭配：“明白”多接想法、意思等，不说明白客人的座位。", "需求": "正确：“明白了客人的需求”指弄清客人想要什么，搭配自然。", "颜色": "语义：颜色不是可以“明白”的内容，“明白了客人的颜色”说不通。", "身份证": "语义：身份证是证件，不能作为“明白”的对象，句子没有合理的意思。"}, "sentence_index": 6, "correct_answer": "需求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我需求一本新字典。", "explanation": "这里应该用〈需要〉。“需求”是名词，不能直接带宾语；“需要”是动词，可以直接带宾语“一本新字典”。"}, {"text": "我对这次旅行充满需求。", "explanation": "这里应该用〈期待〉。“充满”搭配“期待”“希望”，不搭配“需求”；“需求”指必要的东西。"}, {"text": "我有一条需求，要先写下来。", "explanation": "这里应该用“种”或“个”。“条”用于长条形的东西，不能用来计量“需求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的一双需求只是想要一杯热茶。", "corrected_sentence": "他的需求只是想要一杯热茶。", "error_description": "错误在“一双需求”。“双”用于成对的东西，不能用来计量“需求”；这里不需要数量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老人的一朵需求都很简单，有人陪着就好。", "corrected_sentence": "这位老人的需求都很简单，有人陪着就好。", "error_description": "错误在“一朵需求”。“朵”用于花朵等，不能用来计量抽象的“需求”；应去掉数量词，直接说“需求”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21384, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21384, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21384, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "心里觉得够了，开心了。", "primary_collocate": null, "pronunciation": "mǎn zú", "ipa": "man˨˩ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "他对现在的生活很满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完这碗热面，我觉得很满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子吃完饭，满足地笑了。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得到第一名，但还不满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一杯热茶就能让她满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗吃饱了，满足地睡着了。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要对一点成绩就满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，有家人在身边，他就很满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来不满足于现在的成绩，每天都练习。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完这场电影，大家都觉得很满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "满足了", "label": "体标"}, {"form": "满足感", "label": "复合"}], "register": "中性", "sense_fingerprint": "心里觉得够了、感到满意和开心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '840fc245-6719-4ace-a4d0-78c0a43c1a8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "满足", "is_correct": true, "explanation": "正确：“很满足”表示对现在的生活心里觉得够了，符合句意。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“很快”一般用于速度、动作，不用来形容对生活的满意。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：陈旧指过时，与“现在的”生活相矛盾。"}, {"text": "矮", "is_correct": false, "explanation": "语义：“矮”描述人或物的高度，不能用来形容对生活的感受。"}], "explanations": {"满足": "正确：“很满足”表示对现在的生活心里觉得够了，符合句意。", "快": "搭配：“很快”一般用于速度、动作，不用来形容对生活的满意。", "陈旧": "语义：陈旧指过时，与“现在的”生活相矛盾。", "矮": "语义：“矮”描述人或物的高度，不能用来形容对生活的感受。"}, "sentence_index": 0, "correct_answer": "满足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很满足你的帮助。", "explanation": "这里应该用〈感激〉。满足表示心里觉得够了，表达对别人帮助的感谢要用感激，不能说“满足你的帮助”。"}, {"text": "老人满足常乐，很少抱怨。", "explanation": "这里应该用〈知足〉。“知足常乐”是固定说法，不能换成“满足常乐”。"}, {"text": "听到这个好消息，他满足得跳了起来。", "explanation": "这里应该用〈高兴〉。满足表示心里觉得够了，不能用来形容兴奋得跳起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "满足", "is_correct": true, "explanation": "正确：“就满足”表示只要有一点成绩就觉得够了，符合句意。"}, {"text": "放大", "is_correct": false, "explanation": "语义：放大指使东西变大，不能用来说对成绩的态度。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”指把文件印出来，与对成绩的态度无关，句意不通。"}, {"text": "运输", "is_correct": false, "explanation": "语义：“运输”指运送货物，与对成绩的态度无关，句意不通。"}], "explanations": {"满足": "正确：“就满足”表示只要有一点成绩就觉得够了，符合句意。", "放大": "语义：放大指使东西变大，不能用来说对成绩的态度。", "打印": "语义：“打印”指把文件印出来，与对成绩的态度无关，句意不通。", "运输": "语义：“运输”指运送货物，与对成绩的态度无关，句意不通。"}, "sentence_index": 6, "correct_answer": "满足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个瓶子装了水，很快就满足了。", "explanation": "这里应该用〈装满〉。满足表示心里觉得够了，不能用来说容器被装满。"}, {"text": "他满足了这次比赛。", "explanation": "这里应该用〈放弃〉。满足表示心里觉得够了，表示不再参加比赛要用放弃，不能说“满足了这次比赛”。"}, {"text": "我满足了你的道歉。", "explanation": "这里应该用〈接受〉。满足表示心里觉得够了，表示同意对方的道歉要用接受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈看着吃饱的孩子，满足笑了。", "corrected_sentence": "妈妈看着吃饱的孩子，满足地笑了。", "error_description": "状语错误：“满足”修饰后面的动词“笑”，要加“地”，应说“满足地笑了”，不说“满足笑了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这次旅行地满足。", "corrected_sentence": "他对这次旅行很满足。", "error_description": "结构助词错误：“地”只用于修饰后面的动词，这里“满足”作谓语，应用程度副词“很”，说“很满足”，不说“地满足”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
