INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21386, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "整个地球，就是全世界。", "primary_collocate": null, "pronunciation": "quán qiú", "ipa": "tɕʰyæn˧˥ tɕʰjoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "全球的人都在看这场比赛。", "target_word": "全球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种手机在全球都很有名。", "target_word": "全球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全球天气越来越热。", "target_word": "全球", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司在全球有三百家店。", "target_word": "全球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个消息很快传遍了全球。", "target_word": "全球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的歌在全球卖了一千万张。", "target_word": "全球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全球有七十多亿人。", "target_word": "全球", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了保护地球，全球的人都要少用塑料袋。", "target_word": "全球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位歌手在全球很多城市开过演唱会。", "target_word": "全球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全球各国的学生都想来这所大学学习。", "target_word": "全球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全球化", "label": "派生"}], "register": "中性", "sense_fingerprint": "整个地球；全世界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b2333-0eb6-4215-84dd-38c7b4eb1246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21386, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全球", "is_correct": true, "explanation": "正确答案。“全球的人”指世界各地的人。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能作为“的人”的范围，“天气的人”搭配不当。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是人群的范围，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是人，不能说“空气的人”，句意不通。"}], "explanations": {"全球": "正确答案。“全球的人”指世界各地的人。", "天气": "搭配：“天气”不能作为“的人”的范围，“天气的人”搭配不当。", "冰箱": "语义：冰箱是家电，不是人群的范围，句意不通。", "空气": "语义：空气不是人，不能说“空气的人”，句意不通。"}, "sentence_index": 0, "correct_answer": "全球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他全球都是汗。", "explanation": "这里应该用〈全身〉。“全球”指整个地球，说身体的范围要用“全身”。"}, {"text": "我们全球都很喜欢这位老师。", "explanation": "这里应该用〈全班〉。“全球”指世界范围，班级里的人要说“全班”。"}, {"text": "我全球坐火车。", "explanation": "这里应该用〈全程〉。“全程”指从头到尾的整段行程，说整段路都坐某种交通工具要用“全程”，“全球”指世界范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全球", "is_correct": true, "explanation": "正确答案。“全球”指整个地球，可以作“有”的主语。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是场所，不可能有七十多亿人。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不可能有七十多亿人，句子与事实不符。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“有七十多亿人”需要地域或群体作主语，“厨房”不能与之搭配。"}], "explanations": {"全球": "正确答案。“全球”指整个地球，可以作“有”的主语。", "公园": "语义：公园是场所，不可能有七十多亿人。", "教室": "语义：教室不可能有七十多亿人，句子与事实不符。", "厨房": "搭配：“有七十多亿人”需要地域或群体作主语，“厨房”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "全球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全球都到了。", "explanation": "这里应该用〈全员〉。“全员”指单位或团队的全部成员，说人员到齐要用“全员”，“全球”指世界范围。"}, {"text": "我全球都在学习。", "explanation": "这里应该用〈全天〉。“全球”指世界范围，说一整天的时间要用“全天”。"}, {"text": "他全球都很开心。", "explanation": "这里应该用〈全家〉。“全球”指世界，说家人的范围要用“全家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个电影在全球的很受欢迎。", "corrected_sentence": "这个电影在全球很受欢迎。", "error_description": "助词错误：“全球”后不应加“的”。“在全球很受欢迎”是正确的状语结构，多加的“的”使句子残缺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "全球是上千种语言。", "corrected_sentence": "全球有上千种语言。", "error_description": "动词错误：表示存在或拥有时要用“有”，不能用“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
