INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21388, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "环节是一个事情中的一个小部分。", "primary_collocate": null, "pronunciation": "huán jié", "ipa": "xwan˧˥ tɕje˧˥", "syllable_count": 2, "sentences": [{"text": "这是比赛中最重要的一个环节。", "target_word": "环节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭的每个环节都要小心。", "target_word": "环节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后一个环节是大家一起唱歌。", "target_word": "环节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在哪个环节出了问题？", "target_word": "环节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查是生产中的重要环节。", "target_word": "环节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议有三个环节。", "target_word": "环节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个环节需要两个人一起做。", "target_word": "环节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在面试的第一个环节很紧张。", "target_word": "环节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个环节的时间都不长。", "target_word": "环节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个环节太难了，我想跳过。", "target_word": "环节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "環節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "整个过程中相互连着的一个步骤或部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b72803e1-d339-466f-98b7-61dea376201f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21388, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环节", "is_correct": true, "explanation": "环节：指整个过程中相互连着的一个步骤或部分，与“比赛中最重要的一个环节”的句意相符。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”不是比赛过程中的步骤或部分，句意说不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不是比赛过程中的步骤，“比赛中最重要的一个月亮”句意不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能当作比赛过程中的一个部分。"}], "explanations": {"环节": "环节：指整个过程中相互连着的一个步骤或部分，与“比赛中最重要的一个环节”的句意相符。", "饮料": "语义：“饮料”不是比赛过程中的步骤或部分，句意说不通。", "月亮": "语义：“月亮”不是比赛过程中的步骤，“比赛中最重要的一个月亮”句意不通。", "身材": "体貌：“身材”指人的体形，不能当作比赛过程中的一个部分。"}, "sentence_index": 0, "correct_answer": "环节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们班最聪明的环节。", "explanation": "这里应该用〈同学〉。“环节”指过程中的步骤或部分，不能用来指人。"}, {"text": "这本书的第三环节讲了历史。", "explanation": "这里应该用〈章节〉。“环节”指事情过程中的一个小部分，不用来指书的章节，书的分段应说“章节”。"}, {"text": "春节是中国的一个环节。", "explanation": "这里应该用〈节日〉。“环节”指过程中的一个部分，不能用来指节日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环节", "is_correct": true, "explanation": "环节：指整个过程中相互连着的一个步骤或部分，与“这个环节需要两个人一起做”的句意相符。"}, {"text": "动物", "is_correct": false, "explanation": "语义：“动物”不是可以由两个人一起做的过程部分，句意说不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“做”不能与“声音”搭配，不能说“做声音”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是可以由两个人一起完成的步骤，句意说不通。"}], "explanations": {"环节": "环节：指整个过程中相互连着的一个步骤或部分，与“这个环节需要两个人一起做”的句意相符。", "动物": "语义：“动物”不是可以由两个人一起做的过程部分，句意说不通。", "声音": "搭配：“做”不能与“声音”搭配，不能说“做声音”。", "天空": "语义：“天空”不是可以由两个人一起完成的步骤，句意说不通。"}, "sentence_index": 6, "correct_answer": "环节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的环节很开朗。", "explanation": "这里应该用〈性格〉。“环节”是过程中的一部分，不能用来形容人的性格。"}, {"text": "今天的环节很蓝。", "explanation": "这里应该用〈天空〉。“环节”指过程中的一部分，不能用来形容颜色；“很蓝”形容的应是天空、海水等景物。"}, {"text": "这首歌的环节很好听。", "explanation": "这里应该用〈声音〉。“环节”指过程中的步骤或部分，不能用来形容歌曲的声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是产品测试的最后一座环节。", "corrected_sentence": "这是产品测试的最后一个环节。", "error_description": "量词错误：“环节”应用量词“个”，“座”多用于山、桥、楼等大型建筑，应为“最后一个环节”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几个环节们都很重要。", "corrected_sentence": "这几个环节都很重要。", "error_description": "多加了“们”：“环节”不指人，不能加“们”表示复数，应为“这几个环节都很重要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
