INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21396, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "因素就是让一件事发生或变化的一个原因。", "primary_collocate": null, "pronunciation": "yīn sù", "ipa": "in˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "天气是今天人少的一个因素。", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨是迟到的因素之一。", "target_word": "因素", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "睡得太少是我生病的一个因素。", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房价变高有很多因素。", "target_word": "因素", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不开心，有工作的因素，也有家里的因素。", "target_word": "因素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格高是客人变少的一个因素。", "target_word": "因素", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "找出让事情变坏的因素，才能解决问题。", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气冷也是菜价变贵的因素。", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个因素很小，不会改变结果。", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪些因素让学生的成绩变好了？", "target_word": "因素", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "决定因素", "label": "复合"}], "register": "中性", "sense_fingerprint": "因素|让一件事发生或变化的一个原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3bd6d02-7b3a-476c-b3ee-298438b187a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因素", "is_correct": true, "explanation": "“天气是今天人少的一个因素”指让人少的一个原因，“因素”符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能导致人少，句意不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能导致人少，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”是人的情绪，不能说成是今天人少这件事的条件。"}], "explanations": {"因素": "“天气是今天人少的一个因素”指让人少的一个原因，“因素”符合句意。", "味道": "语义：味道不能导致人少，句意不通。", "歌曲": "语义：歌曲不能导致人少，句意不通。", "心情": "搭配：“心情”是人的情绪，不能说成是今天人少这件事的条件。"}, "sentence_index": 0, "correct_answer": "因素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一座很重要的因素。", "explanation": "这里应该用〈个〉。“座”用于山、桥、楼等大型物体，“因素”应用量词“个”。"}, {"text": "这次比赛的因素参加了决赛。", "explanation": "这里应该用〈选手〉。“参加”的主语要是人或队，“因素”是条件，不能参加决赛。"}, {"text": "这种药的因素很好。", "explanation": "这里应该用〈效果〉。“好”形容药的作用，应说“效果”；“因素”不能用来评价药的作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因素", "is_correct": true, "explanation": "“找出让事情变坏的因素”指找出导致变坏的条件，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能让事情变坏，“找出颜色”句意不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不能让事情变坏，“找出名字”句意不通。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指外表，不是让事情变坏的条件。"}], "explanations": {"因素": "“找出让事情变坏的因素”指找出导致变坏的条件，符合句意。", "颜色": "语义：颜色不能让事情变坏，“找出颜色”句意不通。", "名字": "语义：名字不能让事情变坏，“找出名字”句意不通。", "外貌": "体貌：“外貌”指外表，不是让事情变坏的条件。"}, "sentence_index": 6, "correct_answer": "因素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场火灾的因素被扑灭了。", "explanation": "这里应该用〈火势〉。“扑灭”用于火或火势，“因素”是条件，不能被扑灭。"}, {"text": "我们的因素在操场上踢球。", "explanation": "这里应该用〈学生〉。“踢球”需要有行为能力的人，“因素”是条件，不能做动作。"}, {"text": "这件衣服的因素是十块钱。", "explanation": "这里应该用〈价格〉。“十块钱”说的是价钱，“因素”不能指衣服的价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次降温是菜价上涨的一棵因素。", "corrected_sentence": "这次降温是菜价上涨的一个因素。", "error_description": "量词错误：“因素”应用量词“个”，“棵”用于植物，不能用于“因素”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于找了出关键因素。", "corrected_sentence": "他们终于找出了关键因素。", "error_description": "错误：“找了出关键因素”。带宾语时，“了”要放在补语“出”之后，应说“找出了关键因素”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
