INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21398, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "别人对你做一件事，你心里有了感觉，这就是受到。", "primary_collocate": null, "pronunciation": "shòu dào", "ipa": "ʂou˥˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "小明做了好事，受到老师的表扬。", "target_word": "受到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只小狗受到全家人的喜爱。", "target_word": "受到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他迟到了，受到了老师的批评。", "target_word": "受到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我刚到北京时，受到很多邻居的帮助。", "target_word": "受到", "complexity_tier": "T3", "furigana": "wǒ gāng dào Běijīng shí shòudào hěn duō línjū de bāngzhù", "sentence_source": "generated"}, {"text": "小鸟受到惊吓，飞走了。", "target_word": "受到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的话让我受到很大的鼓励。", "target_word": "受到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她听到这个消息后，受到了很大的打击。", "target_word": "受到", "complexity_tier": "T3", "furigana": "tā tīngdào zhège xiāoxi hòu shòudào le hěn dà de dǎjī", "sentence_source": "generated"}, {"text": "她受到过很多人的关心。", "target_word": "受到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受到别人的夸奖，他很高兴。", "target_word": "受到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没考好，却受到了大家的安慰。", "target_word": "受到", "complexity_tier": "T3", "furigana": "tā méi kǎo hǎo, què shòudào le dàjiā de ānwèi", "sentence_source": "generated"}], "morphological_forms": [{"form": "受到了", "label": "完成体"}, {"form": "受到过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "受到：承受别人给予的表扬、批评、影响、帮助等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '020655ba-9334-42e1-8d99-bb5d113bb481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "违反", "is_correct": false, "explanation": "搭配：“违反”的对象是规则或法律，不能与“表扬”搭配。"}, {"text": "处罚", "is_correct": false, "explanation": "语义：“处罚”与“做了好事”及“表扬”的语义相反。"}, {"text": "受到", "is_correct": true, "explanation": "正确：“受到”表示承受别人给予的表扬，与“做了好事”的语境相符。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人或行为，不能作“表扬”的宾语。"}], "explanations": {"违反": "搭配：“违反”的对象是规则或法律，不能与“表扬”搭配。", "处罚": "语义：“处罚”与“做了好事”及“表扬”的语义相反。", "受到": "正确：“受到”表示承受别人给予的表扬，与“做了好事”的语境相符。", "批评": "搭配：“批评”的对象是人或行为，不能作“表扬”的宾语。"}, "sentence_index": 0, "correct_answer": "受到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我终于受到了这份工作。", "explanation": "这里应该用〈得到〉。受到用于表扬、批评、帮助等待遇，获得工作要用得到。"}, {"text": "他受到了一封妈妈寄来的信。", "explanation": "这里应该用〈收到〉。受到是承受别人给予的待遇，接到信件要用收到。"}, {"text": "我们受到了美好的假期。", "explanation": "这里应该用〈享受〉。受到指承受表扬、批评等，享受假期要用享受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带来", "is_correct": false, "explanation": "语义：“带来”的施加者应是别人，此处“她”是听到消息的人，语义不符。"}, {"text": "受到", "is_correct": true, "explanation": "正确：“受到”表示承受打击，与“听到这个消息后”的语境相符。"}, {"text": "施加", "is_correct": false, "explanation": "语义：“施加”的主语应是施加者，此处“她”是承受者，语义不符。"}, {"text": "发出", "is_correct": false, "explanation": "搭配：“发出”搭配的是声音、信号，不能与“打击”搭配。"}], "explanations": {"带来": "语义：“带来”的施加者应是别人，此处“她”是听到消息的人，语义不符。", "受到": "正确：“受到”表示承受打击，与“听到这个消息后”的语境相符。", "施加": "语义：“施加”的主语应是施加者，此处“她”是承受者，语义不符。", "发出": "搭配：“发出”搭配的是声音、信号，不能与“打击”搭配。"}, "sentence_index": 6, "correct_answer": "受到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在路上受到了老朋友。", "explanation": "这里应该用〈遇到〉。受到是承受别人给予的待遇，在路上见到老朋友要用遇到。"}, {"text": "他终于受到了那张车票。", "explanation": "这里应该用〈买到〉。受到指承受别人的表扬、批评等，车票要用买到。"}, {"text": "我在抽屉里受到了丢失的钥匙。", "explanation": "这里应该用〈找到〉。受到指承受别人的影响，找回丢失的东西要用找到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛后，他受到着很多朋友的祝贺。", "corrected_sentence": "这次比赛后，他受到了很多朋友的祝贺。", "error_description": "错误：“着”表示持续的状态，而“这次比赛后”指已经完成的事件，“受到”后应用“了”。正确说法是“这次比赛后，他受到了很多朋友的祝贺”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没有受到了这样的鼓励。", "corrected_sentence": "他从来没有受到过这样的鼓励。", "error_description": "错误：“没有”否定经历时，“受到”后应用“过”，不能用“了”。正确说法是“从来没有受到过这样的鼓励”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
